window.__D("text/maamarim-melukatim/c020",{"p":[[1500390034,"<h3>בס\"ד. ש\"פ תבוא, ח\"י אלול ה'תש\"ל<sup data-n=\"2221\">*</sup></h3>\n<b>את</b> הוי' האמרת גו' והוי' האמירך גו'<sup data-n=\"2222\">1</sup>, ואיתא בגמרא<sup data-n=\"2223\">2</sup> אמר להם הקב\"ה לישראל כו' אתם עשיתוני חטיבה אחת בעולם שנאמר<sup data-n=\"2224\">3</sup> שמע ישראל ה' אלקינו ה' אחד ואני אעשה אתכם חטיבה אחת בעולם שנאמר<sup data-n=\"2225\">4</sup> ומי כעמך ישראל גוי אחד בארץ. וצריך להבין מה שאמרו אתם עשיתוני חטיבה אחת, דפירוש עשיתוני כו' הוא, דזה שהוי' הוא אחד (חטיבה אחת), נעשה זה ע\"י ישראל. וכמובן גם מזה שמדמין אני אעשה אתכם כו' לאתם עשיתוני (ובפרט להגירסא<sup data-n=\"2226\">5</sup> אף אני אעשה), דכמו שפירוש אני אעשה אתכם כו' הוא דזה שישראל הם גוי אחד נעשה ע\"י הקב\"ה [כמו שממשיך בכתוב<sup data-n=\"2227\">6</sup> (לאחרי שאומר ומי כעמך ישראל גוי אחד בארץ) אשר הלך האלקים בעצמו לפדות לו עם גו', ופירש רש\"י<sup data-n=\"2228\">7</sup> וממה הם מיוחדים מכל הגוים, מזה אשר הלך האלקים בעצמו לפדות לו עם כו' מזה אנו מיוחדים]<sup data-n=\"2229\">8</sup>, עד\"ז הוא גם פירוש אתם עשיתוני כו', דענין הוי' אחד נעשה על ידי ישראל.\nב) <b>והנה</b> פירוש הנ\"ל בהאמרת והאמירך (אתם עשיתוני חטיבה אחת בעולם ואני אעשה אתכם חטיבה אחת בעולם) בא בהמשך למה דאיתא בגמרא<sup data-n=\"2230\">9</sup> (לפנ\"ז) תפילין דמארי<sup data-n=\"2231\">10</sup> עלמא מה כתיב בהו כו' ומי כעמך ישראל גוי אחד בארץ, ומי משתבח קוב\"ה בשבחייהו דישראל, אין, דכתיב את ה' האמרת היום וכתיב וה' האמירך היום, אמר להם הקב\"ה לישראל אתם עשיתוני חטיבה אחת בעולם ואני אעשה אתכם חטיבה אחת בעולם. והביאור בזה (בשאלת הגמרא \"ומי משתבח קוב\"ה בשבחייהו דישראל\"), כי תפילין נק' פאר, כמ\"ש<sup data-n=\"2232\">11</sup> פארך חבוש עליך,שהתפילין מביאים תפארת ושבח להאדם החובש אותם, וכמו\"כ הוא גם בתפילין דמארי עלמא שהם מביאים בו תפארת ושבח כביכול, ומזה מובן, דומי כעמך ישראל גו' שכתוב בתפילין דמארי עלמא, זהו תפארתו ושבחו של הקב\"ה<sup data-n=\"2233\">12</sup>. וזהו שמקשה בגמרא ומי משתבח קוב\"ה בשבחייהו דישראל, הרי פסוק זה (ומי כעמך ישראל גו') הוא שבחם של ישראל, ואיך הוא תפארתו ושבחו של הקב\"ה. ומתרץ \"אין, דכתיב את ה' האמרת\", האמרת לשון חשיבות ושבח<sup data-n=\"2234\">13</sup>, שישראל פועלים חשיבות ושבח בהקב\"ה. וצריך להבין, דהראי' מהפסוק את ה' האמרת היא (לכאורה) רק שהקב\"ה משתבח ע\"י השבחים שישראל משבחים אותו ית' (הוי' אלקינו הוי' אחד), דהגם שכל הנבראים הם באין ערוך כלל לגבי' ית' מ\"מ עלה ברצונו ית' שע\"י השבחים שישראל משבחים אותו יובא בו (כביכול) חשיבות ושבח, ואיך מוכח מזה שקוב\"ה משתבח בשבחייהו דישראל, בהשבח של מעלת ישראל, מה שישראל הם גוי אחד בארץ. וצריך לומר, דע\"י את ה' האמרת, שישראל משבחים את הקב\"ה והקב\"ה משתבח בזה, עי\"ז נעשה שהקב\"ה משתבח בהשבח דישראל גופא<sup data-n=\"2235\">14</sup>. ויש להוסיף, דמזה שהפסוק שכתוב בתפילין דמארי עלמא הוא (לא הפסוק שמע ישראל גו' הוי' אחד (כבתפילין שלנו), אלא) הפסוק ומי כעמך ישראל גוי אחד בארץ, מוכח, דשבח זה של הקב\"ה, דמשתבח קוב\"ה בשבחייהו דישראל, הוא שבח גדול יותר מהשבח דאת הוי' האמרת (השבח של ה' ע\"י שישראל משבחים אותו). ועד ששבח זה (מה שמשתבח בהשבח דישראל עצמם) הוא (התפילין) הפאר שלו. גם צריך להבין מה שמביא אדמו\"ר הצ\"צ (במאמרו ד\"ה את ה' האמרת היום)<sup data-n=\"2236\">15</sup>, דבענין האמרת והאמירך יש שתי דיעות. דהרשב\"א<sup data-n=\"2237\">16</sup> כתב שהאמרת והאמירך הוא ע\"ד דודי לי ואני לו<sup data-n=\"2238\">17</sup>, והמהרש\"א<sup data-n=\"2239\">18</sup> כתב שהוא ע\"ד אני לדודי ודודי לי<sup data-n=\"2240\">19</sup>. וצריך להבין, הרי הסדר דהאמרת והאמירך (האמרת ואח\"כ האמירך) הוא דוגמת אני לדודי (ואח\"כ) ודודי לי, ומהו טעמו של הרשב\"א דהאמרת והאמירך הוא ע\"ד דודי לי ואני לו.\nג) <b>ויובן</b> כל זה בהקדים מה שמביא אדמו\"ר הצ\"צ (במאמרו הנ\"ל)<sup data-n=\"2241\">20</sup> מ\"ש הבחיי<sup data-n=\"2242\">21</sup> דבפסוק את ה' האמרת וגו' יש ט\"ו תיבות כנגד ט\"ו דברים<sup data-n=\"2243\">22</sup> שהיו במשכן. ובבחיי שם, ש\"המשכן דוגמת בריאת העולם, וטעם הדבר בבריאת עולםובמשכן, כדי לרמוז מש\"כ<sup data-n=\"2244\">23</sup> כי בי\"ה ה' צור עולמים\". והיינו, דט\"ו הדברים שבמשכן רומזים על י\"ה (בגימטריא ט\"ו). ומזה מובן גם בנוגע לט\"ו התיבות שבפסוק את ה' האמרת, שהם רומזים על י\"ה. וממשיך בבחיי שם, שכנגדן (כנגד הט\"ו דברים שבמשכן) נמצאו ט\"ו פעמים ת\"ק בשבעה רקיעים<sup data-n=\"2245\">24</sup>. ומבאר בהמאמר&lt;20&gt;, דזהו גם מה שואתחנן בגימט' תקט\"ו<sup data-n=\"2246\">25</sup>, ט\"ו פעמים ת\"ק. וע\"פ המבואר במק\"א<sup data-n=\"2247\">26</sup> דענין ואתחנן בגימט' תקט\"ו (שת\"ק וט\"ו הם בתיבה אחת<sup data-n=\"2248\">27</sup>) הוא חיבור ויחוד בחינת ט\"ו (י\"ה) עם בחינת ת\"ק (כדלקמן), יש לומר, דזה שבפסוק את הוי' האמרת יש ט\"ו תיבות (וכן זה שבמשכן היו ט\"ו דברים) שרומז על י\"ה (כנ\"ל) הכוונה בזה היא (לא לבחי' י\"ה כמו שהיא בפ\"ע, כי אם) לבחי' י\"ה כמו שהיא מחוברת ומיוחדת עם בחי' ת\"ק<sup data-n=\"2249\">28</sup>. ויובן זה ע\"פ מרז\"ל (שהובא לעיל) דענין את הוי' האמרת הוא אתם עשיתוני חטיבה אחת כו' הוי' אחד, שיש בזה שני פירושים. פירוש א', דהוי' אחד הוא כמ\"ש האריז\"ל עה\"פ<sup data-n=\"2250\">29</sup> ביום ההוא יהי' הוי' אחד, שי\"ה עם ו\"ה יהיו \"מקושרים באחדות א'\", חיבור מוחין ומדות<sup data-n=\"2251\">30</sup>. ופירוש הב' הוא, דפירוש הוי' אחד הוא ע\"ד אני הוי', דאני שהוא עצמות אוא\"ס עם שם הוי', כולא חד ממש<sup data-n=\"2252\">31</sup>. וזהו מה שט\"ו התיבות (בגמטריא י\"ה) שבפסוק את הוי' האמרת רומזות לבחי' י\"ה כמו שהיא מחוברת ומיוחדת עם בחי' ת\"ק, כי גם בהחיבור ויחוד דט\"ו עם ת\"ק (שבתיבת ואתחנן) יש שני פירושים, דוגמת שני הפירושים הנ\"ל בהוי' אחד. פירוש א', דת\"ק קאי על המדות שלמטה מהמוחין<sup data-n=\"2253\">32</sup>. כי עיקרי המדות הם ה' המדות שמחסד עד הוד<sup data-n=\"2254\">33</sup>, וכל אחד מהם כלול מיו\"ד ויו\"ד מיו\"ד, בגימטריא ת\"ק<sup data-n=\"2255\">34</sup>. וזהו גם זה שהענינים שבעולם הם במספר ת\"ק<sup data-n=\"2256\">35</sup>, כי שרש הנבראים הוא מהמדות. ועפ\"ז, ענין ואתחנן בגימטריא תקט\"ו (שת\"ק וט\"ו הם בתיבה אחת) הוא חיבור המוחין (י\"הבגימטריא ט\"ו) עם המדות (ת\"ק)<sup data-n=\"2257\">36</sup>, כפירוש הראשון בהוי' אחד. ופירוש ב', דת\"ק קאי על המדות דאריך שלמעלה מהמוחין. וענין תקט\"ו הוא לקשר ולחבר חו\"ב (י\"ה, ט\"ו) עם הכתר שלמעלה מהשתלשלות<sup data-n=\"2258\">37</sup>, דוגמת פירוש השני בהוי' אחד, שהוי' ואני (עצמות אוא\"ס שלמעלה מהשתלשלות), הם כולא חד.\nד) <b>ועפ\"ז</b> יובן גם השייכות דאת ה' האמרת לתפילין דמארי עלמא [דהגם שבתפילין דמארי עלמא כתיב ומי כעמך ישראל גו' שהו\"ע וה' האמירך, הרי שני הענינים דהאמרת והאמירך שייכים זל\"ז<sup data-n=\"2259\">38</sup>], כי גם בתפילין דמארי עלמא ישנם שני ענינים אלו. דתפילין הם ד' מוחין<sup data-n=\"2260\">39</sup>, ומה שהקב\"ה מניח תפילין, יש בזה שני פירושים<sup data-n=\"2261\">40</sup>. א', דהקב\"ה הוא ז\"א, והקב\"ה מניח תפילין הוא המשכת המוחין לז\"א [היינו, שנמשך בז\"א עצם המוחין. דזה שנמשך בהמדות דז\"א מהמוחין כפי שהם מצד סדר ההשתלשלות, הוא רק מבחינת מוחין השייכים למדות, וגם זה על ידי כמה וכמה צמצומים<sup data-n=\"2262\">41</sup>, ועד שבהתלבשותם בהמדות דז\"א הם נהפכים למהות מדות<sup data-n=\"2263\">42</sup>, דמוחין שבמדות לגבי מוחין עצמם הם<sup data-n=\"2263\">42</sup> מהות מדות. וענין הקב\"ה מניח תפילין הוא שבהמדות (ז\"א) נמשך עצם המוחין<sup data-n=\"2264\">43</sup>. דזהו מה שהתפילין נקראים פאר, שהקב\"ה ז\"א מתפאר בהם<sup data-n=\"2265\">44</sup>, דתפארת הוא מענין שבאין ערוך<sup data-n=\"2266\">45</sup>]. וב', דהקב\"ה הוא עצמות אוא\"ס שלמעלה מאצילות, והקב\"ה מניח תפילין הוא המשכת אוא\"ס במוחין. [ולפי פירוש זה מובן עוד יותר ענין הפאר דתפילין<sup data-n=\"2267\">46</sup>, כי תוספת האור שנמשך בהמוחין מעצמות אוא\"ס שלמעלה מאצילות הוא באין ערוך לגמרי].\n<b>וזהו</b> את הוי' האמרת, האמרת לשון חשיבות ושבח, דזה שהקב\"ה מניח תפילין (הפאר והשבח שלו), זה נעשה על ידי העבודה דישראל. וזהו אתם עשיתוני חטיבה אחת (עשיתוני דייקא), כי מצד סדר ההשתלשלות, כפי שנמדד ע\"פ קו המדה, ההמשכה מעליון לתחתון (מהמאציל לאצילות, וכן באצילות מהמוחין למדות) היא מצומצמת כפי כלי התחתון, ובכדי שיהי' הקב\"ה מניח תפילין בשני פירושים הנ\"ל, שהם דוגמת שני הפירושים דלעיל בהוי' אחד (חטיבה אחת), יחוד ו\"ה עם י\"ה ויחוד הוי' עם אני, זה נעשה על ידי העבודה דישראל, אתם עשיתוני.ה) <b>ויש</b> לקשר זה עם תורת הבעש\"ט<sup data-n=\"2268\">47</sup> ותורת אדמו\"ר הזקן<sup data-n=\"2269\">48</sup> [אשר ח\"י אלול הוא יום ההולדת שלהם<sup data-n=\"2270\">49</sup>] על הפסוק<sup data-n=\"2271\">50</sup> ואתה קדוש יושב תהלות ישראל, שהקב\"ה מצד עצמו הוא קדוש ומובדל, וע\"י תהלות ישראל, זה שישראל מהללים ומשבחים אותו ית', הוא יושב ונמשך למטה. וזהו את ה' האמרת, דע\"י שישראל משבחים אותו ית' (תהלות ישראל) עי\"ז נעשה שיהי' הקב\"ה מניח תפילין, שנמשך אור (שלמעלה מאצילות באצילות, ובאצילות גופא מהמוחין במדות) שלא כפי סדר ההשתלשלות, שעי\"ז הוא יושב ונמשך גם למטה. דבההמשכה ע\"פ סדר ההשתלשלות, כשהאור נמשך ומשתלשל, הוא מתמעט ומתצמצם, ועד שבעוה\"ז הגשמי, נעשה העלם והסתר לגמרי<sup data-n=\"2272\">51</sup>, משא\"כ כשההמשכה היא שלא כפי סדר ההשתלשלות [דשרש המשכה זו הוא מפנימיות ועצמות אוא\"ס שלמעלה משייכות לעולמות<sup data-n=\"2273\">52</sup>, שהמשכה זו היא ע\"י העבודה דישראל דוקא, לפי ששרש נשמות ישראל הוא בעצמות אוא\"ס<sup data-n=\"2274\">53</sup>], אזי נמשך הגילוי גם למטה<sup data-n=\"2272\">51</sup>.\nו) <b>והנה</b> המשכה זו (דהקב\"ה מניח תפילין) היא (בעיקר) על ידי קיום מצות תפילין. כמאמר רז\"ל<sup data-n=\"2275\">54</sup> על הפסוק<sup data-n=\"2276\">55</sup> מגיד דבריו ליעקב חוקיו ומשפטיו לישראל, מה שהוא עושה הוא אומר לישראל לעשות, וידוע הפירוש בזה<sup data-n=\"2277\">56</sup>, דע\"י שישראל עושים ומקיימים את המצוות, עי\"ז גורמים שהקב\"ה יעשה מצוות אלו<sup data-n=\"2278\">57</sup>. [וע\"ד תורת הבעש\"ט<sup data-n=\"2279\">58</sup> עה\"פ<sup data-n=\"2280\">59</sup> הוי' צלך, דכמו שהצל עושה מה שאדם עושה כך הבורא ב\"ה כביכול עושה מה שאדם עושה]. דמזה מובן גם במצות תפילין, והוקשהכל התורה כולה (המצוות) לתפילין<sup data-n=\"2281\">60</sup>, דזה שהקב\"ה מניח תפילין, נעשה ע\"י הנחת תפילין דישראל. ויובן זה ע\"פ הידוע<sup data-n=\"2282\">61</sup> דכוונת מצות תפילין [וכוונה זו היא חלק דהמצוה<sup data-n=\"2283\">62</sup>] היא לשעבד הלב והמוח. דענין השעבוד, שמשעבד עצמו לאלקות, הוא דוגמת מצות ק\"ש שענינה הוא קבלת עול מלכות שמים (פרשה ראשונה) וקבלת עול מצוות (פרשה שני')<sup data-n=\"2284\">63</sup>, דענין השעבוד וקב\"ע הוא למעלה מטו\"ד, וביחד עם זה, השעבוד דתפילין הוא בנוגע לכחות פרטים (משא\"כ הקב\"ע דק\"ש הוא כללי), שמשעבד את ד' המוחין (חו\"ב ודעת שנחלק לחו\"ג) שלו<sup data-n=\"2285\">64</sup>, וזה נמשך גם בהמדות שבלב, שעבוד הלב<sup data-n=\"2286\">65</sup>. ויש לומר דע\"י שמשעבד את המוחין שלו באופן דקב\"ע, שהוא המשכה מעצם הנפש (שהרי ענין הקב\"ע הוא מצד עצם הנפש שלמעלה מהשתל') בכח השכל שלו, עי\"ז נעשה ענין (פירוש) השני דהקב\"ה מניח תפילין, המשכת אוא\"ס<sup data-n=\"2287\">66</sup> במוחין דלמעלה, וע\"י שזה נמשך מהמוח להלב, עי\"ז נעשה ענין (פירוש) הראשון בהקב\"ה מניח תפילין, המשכת מוחין בז\"א.\nז) <b>ויש</b> להוסיף, דעל ידי ההמשכה דקב\"ע (למעלה מהשתלשלות שבאדם) בהמוח ובהלב, נמשך זה בכל הכחות<sup data-n=\"2288\">67</sup>, גם בכחות התחתונים. דזהו מה שהרצועות דתש\"ר צריכים להיות עד (למטה מן) הטבור<sup data-n=\"2289\">68</sup>, שגם עניני האדם שמפלגך ולתתא<sup data-n=\"2290\">69</sup> יהיו משועבדים לאלקות. ועי\"ז פועל כן גם בעולם, שגם בענינים התחתונים (דמפלגך ולתתא)<sup data-n=\"2291\">70</sup> יהי' גילוי אלקות. דנוסף לזה שבתפילין נמשך הגילוי דאחד כו'גם בקלף וכו' הגשמי, דבק\"ש הגילוי דהוי' אחד הוא בהאדם הקורא ק\"ש משא\"כ בתפילין<sup data-n=\"2292\">71</sup> ההמשכה היא גם בקלף וכו' הגשמי<sup data-n=\"2293\">72</sup> [דזהו שהוקשה כל התורה כולה לתפילין, כי ענין התומ\"צ הוא להמשיך אלקות למטה דוקא, להיות לו דירה בתחתונים<sup data-n=\"2294\">73</sup>], הנה הגילוי דתפילין פועל גם באלה שמצד עצמם הם מנגדים לקדושה. וכמ\"ש<sup data-n=\"2295\">74</sup> וראו כל עמי הארץ כי שם הוי' נקרא עליך ויראו ממך וארז\"ל<sup data-n=\"2296\">75</sup> אלו תפילין שבראש, דההמשכה שע\"י הנחת תפילין פועלת גם באלה שצריך לחדש בהם ויראו ממך (להיותם מנגדים). ולא עוד, אלא שוראו גו' כי שם הוי' נקרא עליך. דאומות העולם (גם אלה שמודים באלקות), ידיעתם היא רק בשם אלקים (בגימטריא הטבע<sup data-n=\"2297\">76</sup>), אבל משם הוי' (שלמעלה מהטבע) אינם יודעים, כמו שאמר פרעה לא ידעתי את הוי'<sup data-n=\"2298\">77</sup>, וע\"י שישראל מניחים תפילין, הגילוי דהוי' (שבישראל המניח תפילין) הוא באופן שגם עמי הארץ (ויתירה מזו, <i>כל</i> עמי הארץ שבזה נכלל אלה שמצד עצמם אינם מודים באלקות<sup data-n=\"2299\">78</sup>, גם לא בשם אלקים) רואים כי שם הוי' נקרא עליך, וראי' זו פועלת בהם ויראו ממך.\nח) <b>ויש</b> לקשר זה עם הגילוי דתורת החסידות, דח\"י אלול הוא יום הולדת דהבעש\"ט מייסד תורת החסידות הכללית ודאדמו\"ר הזקן מייסד תורת חסידות חב\"ד, שמההדגשות העיקריות בתורת החסידות היא שכל הענינים יומשכו למטה בגילוי. וכמ\"ש אדמו\"ר הזקן בשער היחוד והאמונה בתחילתו \"כתיב<sup data-n=\"2300\">79</sup> לעולם הוי' דברך נצב בשמים, ופירש הבעש\"ט ז\"ל כי דברך שאמרת יהי רקיע בתוך המים וגו' תיבות ואותיות אלו הן נצבות ועומדות לעולם בתוך רקיע השמים וכו'\", דאף שפירוש זה איתא במדרש תהלים על הפסוק (כמובא בלקוטי תורה<sup data-n=\"2301\">80</sup>), מ\"מ כותב אדמו\"ר הזקן \"ופירש הבעש\"ט ז\"ל\", דאחד הביאורים בזה<sup data-n=\"2302\">81</sup>, שהבעל שם טוב פירש (פאַנאַנדערגעשפּרייט) וגילה זה שיהי' ידוע לכל. ואדמו\"ר הזקן המשיך זה בשכל, שיהי' לתהלה ולשם ולתפארת<sup data-n=\"2303\">82</sup>, דקאי על חב\"ד<sup data-n=\"2304\">83</sup>, ועד שזה יהי' מושג גם בשכלדנפש הבהמית, ואפילו בשכלם של אלה שהיו (לפני שלמדו ענין זה) מינים<sup data-n=\"2305\">84</sup>, לתתך עליון על כל הגוים<sup data-n=\"2306\">85</sup>.\nט) <b>וזהו</b> את הוי' האמרת אתם עשיתוני חטיבה אחת בעולם שנאמר שמע ישראל הוי' אלקינו הוי' אחד, שע\"י שישראל אומרים הוי' אחד בק\"ש, ובפרט בתפילין<sup data-n=\"2307\">86</sup> שממשיכים הוי' אחד גם בקלף הגשמי, עי\"ז הקב\"ה מניח תפילין, שהם (התפילין) הפאר והשבח שלו (כנ\"ל), האמרת לשון חשיבות ושבח. והטעם על זה שבכחם של ישראל שע\"י קיום המצוות שלהם יהי' קיום המצוות דהקב\"ה, ממשיך בכתוב, והוי' האמירך גו' להיות לו לעם סגולה<sup data-n=\"2308\">87</sup>. וזהו שמסיים (בפסוק והוי' האמירך) ולשמור כל מצותיו (אף שלכאורה שייך זה בפסוק את ה' האמרת, דהשבח שישראל משבחים את הקב\"ה הוא זה שקיבלו עליהם להיות לך לאלקים גו' ולשמור חוקיו ומצותיו גו')<sup data-n=\"2309\">88</sup>, כי לשמור כל מצותיו דישראל מביאה את מצותיו, שהקב\"ה יעשה המצוות. ולכן נאמר זה בפסוק והוי' האמירך (בהשבח שהקב\"ה משבח את ישראל), כי זה שבכחם של ישראל לעשות (ע\"י קיום המצוות שלהם) שיהי' מצותיו דהקב\"ה, הוא שבח גדול לישראל<sup data-n=\"2310\">89</sup>. ויש לומר, דזהו מ\"ש הרשב\"א דענין האמרת והאמירך הוא ע\"ד דודי לי ואני לו (בתחילה דודי לי ואח\"כ ואני לו), כי הכח בישראל להיות את ה' האמרת, להוסיף (כביכול) חשיבות ושבח בהקב\"ה, הוא ע\"י זה שהוי' האמירך.\nיו\"ד) <b>והנה</b> זה דהוי' האמירך להיות לו לעם סגולה, הוא לא מצד הטעם, מצד המעלה דישראל, קיום התומ\"צ שלהם וכיו\"ב, כי אם, שכך בחר הקב\"ה בבחירתו (החפשית), כמ\"ש<sup data-n=\"2311\">90</sup> כי יעקב בחר לו י\"ה ישראל לסגולתו<sup data-n=\"2309\">88</sup>. דזה שישראל הם סגולתו ית' הוא מצד בחירתו, ולכן, זהו בהעצם דישראל. דכאו\"א מישראל (גם לפני שמקיים תומ\"צ<sup data-n=\"2312\">91</sup>) הוא סגולתו ית'. ועי\"ז נעשה בהם גם מעלה (בענין הגילויים), דע\"י קיום המצוות שלהם נעשה מצותיו דהקב\"ה. וזהו מה שבתפילין דמארי עלמא כתיב (לא הפסוק שמע ישראל גו' הוי' אחד, כי אם) ומי כעמך ישראל גו', כי עיקר תפארתו ושבחו של הקב\"ה הוא לא התוספת אור שנעשהלמעלה (קיום המצוות דהקב\"ה) שנעשה ע\"י קיום המצוות דישראל, כי אם, השבח דישראל גופא, שזה דוקא מגיע ב(בחירת) העצמות<sup data-n=\"2313\">92</sup>.\nיא) <b>ויש</b> לקשר (גם) ענין זה עם ח\"י אלול, כי נוסף על זה ש(גם) ענין זה (גודל העילוי דישראל ואהבת ישראל) הוא מהענינים העיקריים דתורת החסידות<sup data-n=\"2314\">93</sup>, הנה ח\"י אלול הוא יום התחלת העבודה דשנה הבאה<sup data-n=\"2315\">94</sup>, מתחיל מר\"ה שאז מכתירים ישראל את הקב\"ה למלך<sup data-n=\"2316\">95</sup>, דהכח שיש בישראל להכתיר אותו למלך הוא מפני שהם קשורים ומיוחדים עם עצמותו ית' (שלמעלה מבחי' מלך)<sup data-n=\"2317\">96</sup>, והקב\"ה מקבל את ההכתרה ונעשה מלך ישראל<sup data-n=\"2318\">97</sup>, ועי\"ז ועל ידם – (גם) מלך על כל הארץ<sup data-n=\"2319\">98</sup>, הוי' אלקי ישראל מלך ומלכותו בכל משלה<sup data-n=\"2320\">99</sup>, ונמשך בגילוי שיהי' מלך ישראל <i>וגואלו</i><sup data-n=\"2318\">97</sup>, ע\"י משיח צדקנו, שילחם מלחמות הוי' וינצח ויבנה מקדש במקומו ויקבץ נדחי ישראל<sup data-n=\"2321\">100</sup>, ומלאה הארץ דעה את הוי' גו'<sup data-n=\"2322\">101</sup> כל העולם<sup data-n=\"2323\">102</sup>, בגאולה האמיתית והשלימה, בקרוב ממש.\n**********",[["2221","*","יצא לאור ב<b>קונטרס ח\"י אלול – תשמ\"ז</b>, \"בסמיכות ליום הזך והבהיר ח\"י אלול, יום הולדת את שני המאורות הגדולים, הבעש\"ט (בשנת נח\"ת) ואדמו\"ר הזקן (בשנת קה\"ת) . . <i>עש\"ק תבוא חי אלול ה' </i><b>ת</b><i>הא </i><b>ז</b><i>ו </i><b>ש</b><i>נת </i><b>מ</b><i>שיח</i>\"."],["2222","1","פרשתנו (תבוא) כו, יז-יח."],["2223","2","ברכות ו, א. חגיגה ג, סע\"א. וכ\"ה גם בבמדב\"ר פי\"ד, ד (בתחילתה). יל\"ש עה\"פ ואתחנן ד, ז (רמז תתכה). ועה\"פ ישעי' מט, ג (רמז תסז)."],["2224","3","ואתחנן ו, ד."],["2225","4","דברי הימים-א יז, כא. ובבמדב\"ר שם הובא הכתוב דשמואל-ב ז, כג: ומי כעמך <i>כ</i>ישראל גוי אחד בארץ. וראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450598\" data-slug=\"or-hatorah-hb\" data-id=\"8316450598\">אוה\"ת</a> פרשתנו ד\"ה זה ע' תתרסח. שם ע' תתרעט. שם כרך ה ע' ב'סו. לקוטי לוי\"צ לזח\"ג ע' שכב ואילך."],["2226","5","כ\"ה ביל\"ש ישעי' שם."],["2227","6","בדה\"י שם. ועד\"ז הוא בשמואל שם."],["2228","7","בדה\"י שם."],["2229","8","וכדמוכח גם בפסוק וה' האמירך גו' להיות לו לעם סגולה <i>כאשר דיבר לך</i>, דזה שישראל הם עם סגולה נעשה ע\"י דיבור הקב\"ה \"והייתם לי סגולה\" (ראה פרש\"י עה\"פ)."],["2230","9","ברכות שם. יל\"ש ואתחנן שם."],["2231","10","בברכות וביל\"ש שם: דמרי. אבל באוה\"ת פרשתנו שם (ע' תתרנז. שם ריש ע' תתרסח. ועוד), וכן הובא בדא\"ח בכ\"מ: \"מארי\", כבפנים. וכ\"ה גם בע\"י ברכות שם."],["2232","11","יחזקאל כד, יז. ברכות יא, א."],["2233","12","ראה חדא\"ג מהרש\"א לברכות שם (ו, א) \"נקראים התפילין פאר והוא שהקב\"ה מניח תפילין כו' <i>ולהתפאר</i> בנחלתו ישראל\"."],["2234","13","רש\"י ברכות שם (ו, א)."],["2235","14","ולהעיר גם מזוהר (ח\"ב מג, א. ח\"ג מה, א) ומרשב\"א הובא בע\"י ברכות שם, שמביא שם לענין תפילין דהקב\"ה הפסוק (ישעי' שם) ישראל אשר בך אתפאר, דפירוש <i>בך</i> אתפאר הוא בישראל <i>עצמם</i>."],["2236","15","אוה\"ת שם ע' תתרנז."],["2237","16","הובא בע\"י ברכות שם."],["2238","17","שה\"ש ב, טז."],["2239","18","בחדא\"ג לברכות שם."],["2240","19","שה\"ש ו, ג."],["2241","20","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450586\" data-slug=\"or-hatorah-hb\" data-id=\"8316450586\">אוה\"ת שם ע' תתרנו</a>. וראה גם שם ע' תתרסו."],["2242","21","עה\"פ תרומה כה, ז."],["2243","22","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211153\" data-slug=\"likkutei-sichot\" data-id=\"1300211153\">לקו\"ש חכ\"א ע' 153</a> הערות 71-70."],["2244","23","ישעי' כו, ד."],["2245","24","\"כי כל רקיע ורקיע ת\"ק ובין רקיע ורקיע ת\"ק, הרי י\"ג פעמים ת\"ק, ויש למעלה מראשי החיות רקיע שהוא ת\"ק, הרי י\"ד פעמים ת\"ק בשמונה רקיעים, ורגלי החיות ת\"ק הרי ט\"ו, וזהו רמז ורגליהם ישרה (יחזקאל א, ז), הרי עם רגלי החיות ברום שלהם שהם ת\"ק הרי ט\"ו פעמים ת\"ק כו'\" – בחיי שם. וראה חגיגה יג, א. ירושלמי ברכות רפ\"ט. תוספות ד\"ה רגלי החיות – חגיגה שם. חדא\"ג מהרש\"א לחגיגה שם."],["2246","25","דב\"ר פי\"א, י. דעת זקנים מבעה\"ת עה\"פ."],["2247","26","אוה\"ת ואתחנן ס\"ע קיג ואילך. שם כרך ו ע' ב'קצג ואילך (ושם ע' קטז, ובכרך ו ע' ב'קצו, מביא: ופסוק את הוי' האמרת יש בו ט\"ו תיבות). <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091070\" data-slug=\"likkutei-sichot\" data-id=\"1300091070\">לקו\"ש ח\"ט ע' 70</a>."],["2248","27","דמזה מוכח שהם מחוברים ומיוחדים – ע\"ד דרשת רז\"ל (נדה סא, ב) בדין שעטנז."],["2249","28","וכמובן גם מהמשך הענינים באוה\"ת פרשתנו שם ע' תתרנו, דלאחרי שמביא שואתחנן בגימטריא תקט\"ו הוא מבאר דענין ט\"ו התיבות שבפסוק את ה' האמרת (וכן המספר ט\"ו בשאר המקומות שהובאו בבחיי שם) הוא \"להמשיך בחי' י\"ה שהם המוחין לז\"א . . וגם לחבר הכתר באו\"א\" – שני הפירושים דלקמן בענין החיבור דת\"ק עם ט\"ו."],["2250","29","זכרי' יד, ט. ל\"ת להאריז\"ל עה\"פ. הובא באוה\"ת פרשתנו שם ע' תתרסו."],["2251","30","אוה\"ת פרשתנו שם."],["2252","31","אוה\"ת שם ס\"ע תתרסה."],["2253","32","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380222\" data-slug=\"likkutei-torah\" data-id=\"4001380222\">לקו\"ת אמור לד, א</a>. אוה\"ת בראשית מז, ב."],["2254","33","לקו\"ת שם. וראה בארוכה סידור שער הל\"ג בעומר דש, א-ב. ובכ\"מ."],["2255","34","כ\"מ בלקו\"ת שם."],["2256","35","חגיגה שם."],["2257","36","אוה\"ת בראשית שם."],["2258","37","אוה\"ת ואתחנן ע' קיג ואילך."],["2259","38","וראה לקמן הערה 86."],["2260","39","זח\"ג רסב, א. הובא ונתבאר בארוכה בסידור שער התפילין ז, סע\"א ואילך. אמ\"ב שער התפילין פקל\"ה ואילך (הוצאת קה\"ת תשמ\"ה קיב, א ואילך). ובכ\"מ."],["2261","40","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370162\" data-slug=\"torah-or\" data-id=\"3901370162\">תו\"א מקץ לה, ב</a>-ג."],["2262","41","ראה בארוכה המשך תרס\"ו ע' רפט ואילך. ובכ\"מ."],["2263","42","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370260\" data-slug=\"torah-or\" data-id=\"3901370260\">תו\"א וארא נח, ב</a>."],["2264","43","ד\"ה תפילין דמארי עלמא תרנ\"ג ספ\"ז (סה\"מ תרנ\"ג ע' רמט). וראה סידור שם ז, ד."],["2265","44","ד\"ה הנ\"ל פ\"ט (סה\"מ שם ע' רנד)."],["2266","45","סידור שם יד, ד."],["2267","46","לכאורה, ענין הפאר דתפילין הוא שהם מפארים את מי שמניח אותם, ולא שהתפילין עצמם (המוחין) מפוארים ע\"י התוס' אור שנמשך בהם. אבל ראה ד\"ה הנ\"ל תרנ\"ג ספי\"א (סה\"מ שם ע' רנח) דהתוספת אור שנמשך באו\"א הוא הפאר דתפילין [ושם בפ\"ח (סה\"מ שם ע' רנ), דזה שתפילין נק' טוטפות לשון תכשיט הוא האורות דכתר שהם בחי' קישוטין]."],["2268","47","הובאה בד\"ה ואתה קדוש – בסה\"מ אידיש ע' 138 ואילך."],["2269","48","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380203\" data-slug=\"likkutei-torah\" data-id=\"4001380203\">לקו\"ת</a> ר\"פ קדושים (כט, סע\"ב ואילך). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071147\" data-slug=\"likkutei-sichot\" data-id=\"1300071147\">לקו\"ש ח\"ז ע' 135</a> ואילך ובהערות שם."],["2270","49","הבעש\"ט בשנת נח\"ת (ראה לקו\"ד כרך א לא, א ואילך. ספר השיחות ה'תש\"ג ע' 146. שם ע' 188) ורבינו הזקן בשנת קה\"ת (ראה ספר השיחות שם ע' 188) – ספר השיחות שם ע' 141 ואילך. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300241178\" data-slug=\"likkutei-sichot\" data-id=\"1300241178\">לקו\"ש חכ\"ד ע' 178</a> ואילך, ובהנסמן שם."],["2271","50","תהלים כב, ד."],["2272","51","המשך תרס\"ו ע' כב."],["2273","52","ראה שם ע' נב."],["2274","53","ראה שם ע' סב (בפירוש כל הנקרא בשמי)."],["2275","54","שמו\"ר פ\"ל, ט. וראה גם ירושלמי ר\"ה פ\"א ה\"ג."],["2276","55","תהלים קמז, יט."],["2277","56","המשך תרס\"ו ריש ע' תיט. סד\"ה את הוי' האמרת תרע\"ח (סה\"מ תרע\"ח ע' תכ). ד\"ה איתא במדרש תלים תרנ\"ג בתחלתו (סה\"מ תרנ\"ג ע' רעט. סה\"מ תש\"ח ע' 271). וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370163\" data-slug=\"torah-or\" data-id=\"3901370163\">תו\"א מקץ לה, ג</a>*."],["2278","57","ואף שקיום המצוות דהקב\"ה ישנו גם לפני קיום המצוות דישראל, ומבואר בכ\"מ בפירוש מרז\"ל הנ\"ל, דזה שהוא עושה הוא נתינת כח לישראל לעשות – הרי המצוות דהקב\"ה שנעשות ע\"י קיום המצוות דישראל הם נעלים יותר מכפי שהם מצד עצמם – ראה ד\"ה פדה בשלום תשל\"ח ס\"ד (לעיל ח\"ב ע' קמה). ובכ\"מ."],["2279","58","קדושת לוי פ' נשא (עד, א). נעתקה בכתר שם טוב (הוצאת תשנ\"ט) בהוספות סי' עח. וראה גם שם פ' בשלח טו, א (ד\"ה או יבואר אז ישיר הא' וד\"ה והנה ידוע – ח\"א מב, סע\"ג. מג, ג). ח\"ב קדושה שני' קרוב לסופה (ט, סע\"ג). סה\"מ תרכ\"ז ע' שב (בשם הבעש\"ט. ושם \"ונמצא פי' זה במדרש שמואל ג\"כ\" – מד\"ש לאבות פ\"ג מי\"ז)."],["2280","59","תהלים קכא, ה.\n*) <i>בכ\"מ מבואר</i>,<i> דעל ידי שהוא עושה</i>,<i> זהו נתינת כח לישראל לקיים המצוות</i>.<i> וראה הערה הבאה</i>."],["2281","60","קידושין לה, א. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061287\" data-slug=\"likkutei-sichot\" data-id=\"1300061287\">לקו\"ש ח\"ו ע' 277</a> בהערה."],["2282","61","שו\"ע או\"ח הל' תפילין סכ\"ה ס\"ה. שו\"ע אדה\"ז שם סי\"א. <a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא פמ\"א (נו, ב</a>)."],["2283","62","ב\"ח או\"ח ס\"ח (ד\"ה ונקראים ציצית). וכ\"ה גם בב\"ח או\"ח ר\"ס תרכה. ובב\"ח או\"ח הל' תפילין סכ\"ה ד\"ה ויכוין בהנחתן כו' כתב: ע\"ל בהלכות ציצית בסימן ח' אצל ויכוין בהנחתם וכו'."],["2284","63","ברכות יג, א (במשנה)."],["2285","64","תניא שם."],["2286","65","בתחילת הענין בתניא שם \"ליבטל ולכלול בחי' הדעת שבנפשו הכולל חו\"ג שהן יראה ואהבה שבלבו\", דמלשון זה משמע, שמשעבד את <i>הדעת</i> שלו (שהוא (הדעת) כולל אהוי\"ר שבלבו), אבל בסיום הענין שם \"לשעבד <i>הלב</i> כו'\"."],["2287","66","ראה גם ד\"ה תפילין דמארי עלמא תרנ\"ג פ\"ח (סה\"מ תרנ\"ג ע' רנ), דהמשכת האורות מעצמות אוא\"ס (שלמעלה מהאורות המלובשים בע\"ס) הוא ע\"י <i>השעבוד</i> שבתפילין. אלא שהביאור שם הוא באופן אחר."],["2288","67","וראה סה\"מ תרל\"ו ח\"א ע' ריט: וישעבד להקב\"ה הנשמה שהיא במוח וגם הלב . . וגם הם ראשי אברים לכן כשמשעבדן להקב\"ה עי\"ז משתעבד כל האדם כו'."],["2289","68","בטושו\"ע (ודאדה\"ז) או\"ח הל' תפילין סכ\"ז סי\"א (ס\"כ) \"שיגיעו עד הטבור\". אבל בכ\"מ בדא\"ח (סה\"מ קונטרסים ח\"א רכג, א. סה\"מ תרצ\"ט ע' 159. סה\"מ תש\"ג ע' 43) דרצועות של ראש \"מגיעים עד הרגלים\". ויש לומר שהוא ע\"פ מ\"ש בטור שם \"ויש אומרים . . עד המילה\".\nוממ\"ש בפע\"ח שער ד (שער התפילין) פ\"י (ועד\"ז הוא בשער הכוונות ענין התפילין דרוש ה. שו\"ע האריז\"ל הל' תפילין סט\"ו (וראה הגהת צמח שם)) \"טוב שישים כו' כדי שלא יגיעו לארץ כו'\" – משמע, שהדרך לילך ברצועות ארוכות עוד יותר."],["2290","69","סנהדרין לט, א. וראה הערה הבאה."],["2291","70","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381282\" data-slug=\"likkutei-torah\" data-id=\"4001381282\">לקו\"ת שה\"ש</a> ד\"ה ששים המה מלכות ס\"א (לח, ג) (הובא ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450588\" data-slug=\"or-hatorah-hb\" data-id=\"8316450588\">אוה\"ת</a> <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381320\" data-slug=\"likkutei-torah\" data-id=\"4001381320\">פרשתנו ד</a>\"ה את ה' האמרת ע' תתרנח), ד\"מפלגך לתתא\" קאי על עלמא דפרודא. ובאוה\"ת שם, דענין \"עשיתוני חטיבה אחת\" הוא – שגם בעולמות התחתונים הוא אחד, לאפוקי מדעת האומרים מפלגך כו'.\nובאוה\"ת שם, דזהו גם מה שפירש הבחיי (פרשתנו עה\"פ) שהאמרת הוא לשון מעלה וגובה, מלשון בראש אמיר (ישעי' יז, ו) – כי מה שהוא ית' משגיח גם בארץ (\"המגביהי גו' המשפילי לראות בשמים ובארץ\") הוא \"מפני שהוא ית' <i>מגביהי</i>\" (לקו\"ת שם מח, רע\"א. עיי\"ש בארוכה)."],["2292","71","דנוסף לזה שק\"ש היא רק במחשבה ודיבור ותפילין הם במעשה האדם, ההמשכה דתפילין היא גם בקלף וכו' הגשמי שמחוץ לאדם."],["2293","72","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380480\" data-slug=\"likkutei-torah\" data-id=\"4001380480\">לקו\"ת שלח מב, סע\"א</a>."],["2294","73","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380475\" data-slug=\"likkutei-torah\" data-id=\"4001380475\">לקו\"ת שם מ, סע\"ד</a>."],["2295","74","פרשתנו כח, י."],["2296","75","ברכות ו, א."],["2297","76","פרדס שער יב (שער הנתיבות) פ\"ב. ר\"ח שער התשובה פ\"ו ד\"ה והמרגיל (קכא, ב). וראה שם שער האהבה ספ\"א ד\"ה וכדי להבין (נב, ד). של\"ה פט, א (כדאיתא בזוהר); קפט, א (וכמרומז בזוהר); שח, ב. שו\"ת חכם צבי סי\"ח. שער היחוד והאמונה רפ\"ו."],["2298","77","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370188\" data-slug=\"torah-or\" data-id=\"3901370188\">שמות ה, ב</a>. וראה תו\"א מקץ מא, סע\"ד. אוה\"ת וארא ס\"ע רג ואילך. ובכ\"מ."],["2299","78","ראה סהמ\"צ להצ\"צ מצות אחדות ה' ספ\"ג (דרמ\"צ סב, ג). ובארוכה דרוש תער השכירה – נדפס ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650038\" data-slug=\"or-hatorah-hb\" data-id=\"8316650038\">אוה\"ת נ\"ך כרך ב ע' תשסז</a> ואילך."],["2300","79","תהלים קיט, פט."],["2301","80","ר\"פ אחרי (כה, סע\"ג). פ' קדושים כט, ד."],["2302","81","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081365\" data-slug=\"likkutei-sichot\" data-id=\"1300081365\">לקו\"ש ח\"ח ע' 354</a> הערה 21."],["2303","82","פרשתנו כו, יט. ובא בהמשך ל\"וה' האמירך גו'\"."],["2304","83","לקו\"ת פרשתנו מב, ב. שם, ג.ולהעיר שבלקו\"ת שם (מב, ב) דתפארת \"הוא בחי' דעת שהוא כולל חסד וגבורה\" – דעפ\"ז שם תהלה ותפארת הם <i>ד'</i> מוחין, דוגמת ד' מוחין דתפילין."],["2305","84","שעהיוה\"א רפ\"ב. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091159\" data-slug=\"likkutei-sichot\" data-id=\"1300091159\">לקו\"ש ח\"ט ע' 159</a>."],["2306","85","פרשתנו שם. וראה לקו\"ת שם מב, ב."],["2307","86","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450588\" data-slug=\"or-hatorah-hb\" data-id=\"8316450588\">אוה\"ת פרשתנו ע' תתרנח</a> <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450590\" data-slug=\"or-hatorah-hb\" data-id=\"8316450590\">\"ע\"י</a> תפילין ממשיכים ישראל תפילין דמארי עלמא\", ומבאר שם ענין <i>האמרת</i>. וראה גם שם ע' תתרנט סעיף ד'."],["2308","87","ראה גם ד\"ה את ה' האמרת תר\"ל פי\"ב (סה\"מ תר\"ל ע' שא)."],["2309","88","ד\"ה זה תרע\"ח (סה\"מ תרע\"ח ע' תיא ואילך)."],["2310","89","סד\"ה הנ\"ל (סה\"מ שם ע' תכ ואילך)."],["2311","90","תהלים קלה, ד."],["2312","91","ראה פרש\"י עה\"פ (יתרו יט, ה) והייתם לי סגולה מכל העמים \"אוצר חביב . . שהמלכים <i>גונזים</i> אותם\". וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300241162\" data-slug=\"likkutei-sichot\" data-id=\"1300241162\">לקו\"ש חכ\"ד ע' 162</a> ואילך, שהעילוי והיוקר דאוצרות <i>הגנוזים</i> הוא <i>בעצם מציאותם</i>. עיי\"ש בארוכה."],["2313","92","אלא <i>שגילוי</i> ענין זה הוא ע\"י קיום התומ\"צ דישראל. וי\"ל, דזהו מה שמהפסוק האמרת למדים (נתגלה) ש\"משתבח קוב\"ה בשבחייהו דישראל\"."],["2314","93","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091156\" data-slug=\"likkutei-sichot\" data-id=\"1300091156\">לקו\"ש ח\"ט ע' 156</a> ובהערה 23 שם."],["2315","94","ראה ספר השיחות ה'תש\"ג ע' 177. שם ע' 179."],["2316","95","ר\"ה טז, א. שם לד, ב. וראה תרגום ירושלמי עה\"פ \"את ה' האמרת היום\": ומימרא דה' <i>אמליך</i> עליכון כו' (הובא בפי' בעלי התוס' כאן. ועוד). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300241164\" data-slug=\"likkutei-sichot\" data-id=\"1300241164\">לקו\"ש חכ\"ד ע' 164</a> ובהנסמן שם בהערות 47, 50."],["2317","96","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300241164\" data-slug=\"likkutei-sichot\" data-id=\"1300241164\">לקו\"ש שם ע' 164</a>. ובארוכה לקו\"ש ח\"ד ע' 1145 ואילך."],["2318","97","תפלת מוסף דר\"ה (ברכת מלכיות), מישעי' מד, ו."],["2319","98","תפלת העמידה דר\"ה (חתימת ברכת \"אלקינו כו' מלוך כו'\"), וכן בקידוש ובברכת ההפטורה."],["2320","99","תפלת העמידה דר\"ה שם."],["2321","100","רמב\"ם הל' מלכים ספי\"א."],["2322","101","ישעי' יא, ט."],["2323","102","רמב\"ם סוף הל' מלכים (וסיום וחותם ונשלם \"החיבור כולו\")."]]],[1500390035,"<h3>בס\"ד. ש\"פ תבוא, ח\"י אלול ה'תשל\"ג<sup data-n=\"2324\">*</sup></h3>\n<b>קומי</b> אורי כי בא אורך גו'<sup data-n=\"2325\">1</sup>, הנה, כי בא אורך הוא טעם על קומי אורי. שהקב\"ה אומר לישראל<sup data-n=\"2326\">2</sup>, דכיון שכבר בא אורך, האור שלך (של ישראל), לכן צריכה את לקום ולהאיר. וצריך להבין מהו ענינם של שני אורות אלה, האור של ישראל עצמם והאור שצריכים להאיר. ויובן זה ע\"פ מה דאיתא בילקוט<sup data-n=\"2327\">3</sup>, אמרו ישראל לפני הקב\"ה, עשינו לך מנורה בימי משה וכבתה, בימי שלמה וכבתה, מכאן ואילך אין אנו ממתינין אלא לאורך, שנאמר<sup data-n=\"2328\">4</sup> כי עמך מקור חיים באורך נראה אור, וכך אמר הקב\"ה קומי אורי כי בא אורך. ומזה שמדמין קומי אורי כי בא אורך לבאורך נראה אור, מובן, ששני הענינים שבפסוק קומי אורי כי בא אורך הם דוגמת שני הענינים שבפסוק באורך נראה אור.\nב) <b>ויובן</b> זה בהקדים מה שמבאר כ\"ק מו\"ח אדמו\"ר במאמרו ד\"ה כי עמך מקור חיים באורך נראה אור<sup data-n=\"2329\">5</sup>, שבפסוק זה יש ד' ענינים. חיים, מקור חיים, אורך ואור. וד' ענינים אלו הם בסדר מלמטה למעלה. חיים הוא החיות אלקי שמתלבש בעולמות, ממלא כל עלמין. [ויש להוסיף ביאור, דזה שנק' בשם חיים לשון רבים הוא, כי החיות המתלבש בעולמות ונבראים הוא בריבוי התחלקות, בכלנברא לפי ענינו]. מקור חיים הוא אור הסובב כל עלמין. אורך הוא תורה, תורה אור<sup data-n=\"2330\">6</sup>, שלמעלה גם מסובב. והאור שנראה ע\"י אורך הוא למעלה גם מאורך, ועד שאורך אינו אלא הכנה להאור שנראה על ידו.\nג) <b>והנה</b> בכדי לבאר העילוי דאורך, שעי\"ז יובן גודל מעלת האור שנראה ע\"י אורך (שהוא למעלה גם מאורך), יובן זה בהקדים הביאור דבחי' מקור חיים, שיש בזה שני פירושים. דזה שנק' בשם מקור חיים הוא, כי גם אור הסובב, להיותו הארה בלבד, הוא מקור (עכ\"פ) (לאור הממלא ועי\"ז, גם) להחיות המתלבש בעולמות<sup data-n=\"2331\">7</sup>. ושמקור חיים קאי על האור שלמעלה מבחי' מקור להחיות דממכ\"ע, וזה שנק' בשם מקור חיים הוא כי ממנו נמצא החיות [וע\"ד מ\"ש בלקו\"ת<sup data-n=\"2332\">8</sup> בענין מה שהקב\"ה נקרא צור חיינו, דפירוש צור הוא מקור ושרש כל שרשי ההתהוות<sup data-n=\"2333\">9</sup>, דאין הכוונה בזה שהוא מקור ח\"ו לההתהוות, אלא שכל שרשי ההתהוות נמצאו ממנו<sup data-n=\"2334\">10</sup>]. וזהו מ\"ש כי עמך מקור חיים, דבתיבת עמך שני פירושים<sup data-n=\"2335\">11</sup>. שההדגשה בעמך היא שהוא רק עמך ולא אתה, דבר הטפל ובטל לך. ושההדגשה בעמך היא שאינו ענין לעצמו אלא עמך, מיוחד עמו ית'. וע\"ד מ\"ש במדרש<sup data-n=\"2336\">12</sup> עה\"פ<sup data-n=\"2337\">13</sup> אם כסף תלוה את עמי, אם כסף תלוה כו' את עמי, מה אני כו' אף אתה כו'. ויש לומר, דשני פירושים אלו הם בהתאם לשני הפירושים (דלעיל) במקור חיים. דלהפירוש שמקור חיים הוא בחי' מקור לחיים, הפירוש דכי עמך מקור חיים הוא שענין מקור חיים הוא רק עמך ולא אתה, טפל ובטל לך. ולהפירוש שמקור חיים הוא שהחיים נמצאים ממנו (אבל לא שהוא בחי' מקור), פירוש כי עמך מקור חיים הוא שהמשכת החיים היא רק מעמך, מבחינת האור שמיוחד עמו ית'<sup data-n=\"2338\">14</sup>.\nד) <b>והנה</b> גם להפירוש שהכוונה במקור חיים היא שממנו נמצאו החיים (ולא שהוא בבחי' מקור להם), מ\"מ, מזה שנקרא בשם מקור חיים (חיות העולמות), מוכח שיש לו שייכות לעולמות. וזהו מה שלאחרי שאומר כי עמך מקור חיים מוסיף באורך גו' (שסדר הענינים שבהפסוק הוא מלמטה למעלה, כנ\"ל), דאורך הוא למעלהמשייכות לעולמות. ולכן נקרא בשם אור (אורך), דענין האור הוא שהוא דבוק בהמאור ומעין המאור<sup data-n=\"2339\">15</sup>. היינו, שאינו בבחי' מציאות, ובמילא אין שייך שיהי' מקור לאיזה דבר, וכל ענינו הוא שהוא גילוי המאור. ומדייק באורך, דנוסף על זה שאור בכלל (גם כמו שהוא מתפשט מחוץ להמאור) כל ענינו הוא התפשטות וגילוי המאור כנ\"ל, הנה באור גופא הוא אורך, אור שלך, אור הכלול בעצמותו. דבכללות הוא אוא\"ס שלפני הצמצום (כמבואר בכ\"מ<sup data-n=\"2340\">16</sup> דכללות האור שלפני הצמצום הוא אור הכלול בעצמותו). דאור זה הוא למעלה משייכות לעולמות, ולכן, בכדי שתהי' התהוות העולמות צ\"ל סילוק האור<sup data-n=\"2341\">17</sup>. ועל זה ארז\"ל<sup data-n=\"2342\">18</sup> עד שלא נברא העולם הי' הוא ושמו בלבד, דהאור שלפני הצמצום (דהתחלת הבריאה היא הצמצום, ועד שלא נברא העולם הוא לפני הצמצום<sup data-n=\"2343\">19</sup>) נקרא שמו, דכמו ששמו של האדם אינו מציאות כלל (גם לא כהמציאות דאור) וכל ענינו הוא מה <i>שהאדם</i> פונה להקוראים אותו בשמו<sup data-n=\"2344\">20</sup>, עד\"ז הוא בהאור שלפני הצמצום, שאינו בבחי' מציאות וכל ענינו הוא רק שהוא שמו, הוא ושמו בלבד<sup data-n=\"2345\">21</sup>.\nה) <b>והנה</b> ידוע<sup data-n=\"2346\">22</sup> דבאוא\"ס שלפני הצמצום יש (בכללות) ב' מדריגות. עצם האור והתפשטות האור. ובהתפשטות האור גופא ישנן ב' מדריגות בכללות. גילוי לעצמו, והוא השרש דאור הסובב<sup data-n=\"2347\">23</sup>. והגילוי השייך לעולמות (דעם היות שכללות האור שלפני הצמצום הוא כלול בעצמותו כנ\"ל, הנה בעצמותו גופא הוא גילוי השייך לעולמות), והוא השרש דאור הממלא<sup data-n=\"2347\">23</sup>. וע\"פ הידוע, דהמשכת האור למעלה אינה בדרך הכרח ח\"ו<sup data-n=\"2348\">24</sup>, וגם המשכת האור שלפני הצמצום (גם הגילוי לעצמו שלמעלה מהגילוי השייך לעולמות) הוא בשביל איזו כוונה לצורך העולמות<sup data-n=\"2349\">25</sup>,נמצא, דזה שב' הבחינות דסובב וממלא שלאחרי הצמצום נמשכים מב' הגילויים (גילוי לעצמו וגילוי השייך לעולמות) שלפני הצמצום הוא באופן שהגילויים שלפני הצמצום <i>שייכים</i><sup data-n=\"2350\">26</sup> להבחינות שלאחרי הצמצום. ומזה מובן, שגם האור שלפני הצמצום נכלל במקור חיים<sup data-n=\"2351\">27</sup>, ואורך (שהוא למעלה ממקור חיים) הוא נעלה יותר גם מהאור שקודם הצמצום. וי\"ל שזהו מה שמבאר בהמאמר דאורך קאי על תורה (תורה אור), דהתורה אינה בשביל העולמות, אדרבא, התהוות כל העולמות (כולל גם הגילויים שלפני הצמצום, שהוא לצורך העולמות) הוא בשביל התורה<sup data-n=\"2352\">28</sup>.\nו) <b>וממשיך</b> בכתוב נראה אור, שהוא למעלה גם מאורך, ועד שאורך אינו אלא הכנה להאור הנראה על ידו (כנ\"ל מהמאמר). ויש לומר הביאור בזה ע\"פ הידוע<sup data-n=\"2353\">29</sup> בענין תורה ונש\"י, דשרש ישראל הוא למעלה משרש התורה<sup data-n=\"2354\">30</sup>, כדאיתא בתדב\"א<sup data-n=\"2355\">31</sup> שני דברים קדמו לעולם תורה וישראל, ואיני יודע איזה מהם קודם, כשהוא אומר צו את בני ישראל דבר אל בני ישראל, אומר אני ישראל קדמו. אלא שנש\"י נמשכו וירדו בבחינת מציאות בפ\"ע, כמו הבן (בנים אתם לה' אלקיכם<sup data-n=\"2356\">32</sup>) שעם היותו מעצמות האב, הוא מציאות נבדל<sup data-n=\"2357\">33</sup>, והתורה גם כמו שנמשכה למטה היא מיוחדת עמו ית', אורייתא וקוב\"ה כולא חד<sup data-n=\"2358\">34</sup>. וזהו הטעם שמעלתן של ישראל (שקדמו לתורה) נתגלתה ע\"י התורה (שבתורה נאמר צו את בני ישראל, דבר אל בני ישראל), כי הנשמות, כמו שהן מצד עצמן, להיותן מציאות נבדל, השרש שלהם הוא בהעלם, משא\"כ תורה, שהיא חד עם הקב\"ה, היא בחי' גילוי (ותורה אור), וע\"י התורה מתגלה (גם) השרש דישראל. ועפ\"ז יש לומר ששני הענינים דבאורך נראה אור הם תורה וישראל. אורך היא תורה (כנ\"ל), והאור שנראה ע\"י אורך הוא השרש דישראל שמתגלה ע\"י התורה<sup data-n=\"2359\">35</sup>.\nז) <b>וזהו</b> קומי אורי כי בא אורך, דשני ענינים אלו (אורי ואורך) הם דוגמת שני הענינים דבאורך נראה אור (כנ\"ל בתחלת המאמר). אורך, האור של ישראל עצמם, הוא ע\"ד באורך (אור שלך), וקומי אורי, האור שישראל מאירים, הוא ע\"דהאור שנראה ע\"י אורך (שלמעלה מאורך). ויובן זה ע\"פ המבואר במק\"א<sup data-n=\"2360\">36</sup> בענין נשמה וגוף, דבנשמות כתיב&lt;32&gt; בנים אתם להוי' אלקיכם<sup data-n=\"2361\">37</sup>, ולכן, האהבה וההתקשרות דהקב\"ה לישראל מצד נשמתם היא כמו אהבה <i>טבעית</i> כביכול (ע\"ד אהבת אב לבנו). היינו, ששרש אהבה זו היא ממדריגה ששייכת שם תפיסת מקום דהנאהב, ואינה מעצמותו ממש. משא\"כ האהבה וההתקשרות דהקב\"ה לישראל מצד הגוף שלהם, היא (לא מצד מעלת הגוף, גם לא המעלה ד\"בן\", מעלה עצמית, אלא) מצד זה שהקב\"ה <i>בחר</i> בהגוף דישראל<sup data-n=\"2362\">38</sup>, בבחירתו חפשית, שבחירה זו היא מעצמותו ממש. אלא, שמעלת הנשמה (שהיא בן להקב\"ה) היא בגילוי, משא\"כ מעלת הגוף (שבו הוא בחירת העצמות) היא בהעלם. וע\"י שהנשמה עובדת עם הגוף, מתגלה בו מעלתו, בחירת העצמות.\n<b>ועפ\"ז</b> יש לומר פירוש קומי אורי כי בא אורך, שאורך הוא האור דהנשמה, וקומי אורי הוא שע\"י האור דהנשמה (בא אורך) היא צריכה לעבוד בהגוף ולהאיר אותו, שעי\"ז נתגלה ענין נעלה יותר מהאור של הנשמה (אורך), ע\"ד שנת\"ל (סעיף ב) בענין באורך נראה אור, דהאור שנראה ע\"י אורך הוא נעלה יותר מאורך.\nח) <b>והנה</b> מבאר כ\"ק מו\"ח אדמו\"ר במאמרו ד\"ה כי עמך מקור חיים הנ\"ל, שהפסוק כי עמך מקור חיים גו' הוא מאמר כנס\"י להקב\"ה בזמן הגלות<sup data-n=\"2363\">39</sup>. דהנה בזמן הגלות, הצמאון לאלקות הוא יותר מבזמן הבית, וכתורת הבעש\"ט (בעל יום ההולדת דח\"י אלול) עה\"פ<sup data-n=\"2364\">40</sup> צמאה לך נפשי כמה לך בשרי בארץ צי' ועיף בלי מים, כן בקודש חזיתיך, דצמאה לך נפשי גו' הוא בזמן הגלות (בארץ צי' ועיף בלי מים), וע\"ז נאמר כן בקודש חזיתיך – הלואי בקודש חזיתיך. ובזמן הגלות אומרת כנס\"י להקב\"ה, רבש\"ע כי עמך מקור חיים באורך נראה אור, מיט דיר רבש\"ע איז דער קוואַל פון לעבן, מיט דיין ליכטיקייט זעען מיר ליכט. וע\"פ המבואר לעיל סעיף א (ע\"פ דרשת הילקוט) שקומי אורי כי בא אורך הוא ע\"ד באורך נראה אור, יש לומר, שגם מאמר הקב\"ה לכנס\"י קומי אורי כי בא אורך [הגם שמפשטות הלשון כי בא אורך (שכבר בא) משמע שמדבר בזמן הגאולה], הוא (גם) בזמן הגלות. היינו, שגם בזמן הגלות, ובפרט בימים האחרונים דהגלות, אפשרי וצריך להיות הענין דקומי אורי כי בא אורך, הן בנוגע לאור הנשמה (אורך) והן בנוגע לזה שהנשמה מאירה את הגוף (קומי אורי).<b>וע\"י</b> מעשינו ועבודתינו בזמן הגלות<sup data-n=\"2365\">41</sup>, ובפרט בהענין דקומי אורי כי בא אורך, מקרבים וממהרים עוד יותר את הגאולה העתידה, שאז יהי' קומי אורי כי בא אורך כפשוטו (שכבר בא), ובאופן של זריזות, כסיום וחותם ההפטורה<sup data-n=\"2366\">42</sup> – אחישנה<sup data-n=\"2367\">43</sup>.\n**********",[["2324","*","יצא לאור ב<b>קונטרס ח\"י אלול – תשמ\"ט</b>, \"לקראת יום הבהיר ח\"י אלול, יום הולדת את שני המאורות הגדולים, הבעש\"ט (בשנת נח\"ת) ואדמו\"ר הזקן (בשנת קה\"ת) . . <i>מוצש\"ק פ' כי תבוא ה'תשמ\"ט</i>\"."],["2325","1","ישעי' ס, א. – התחלת וראש ההפטורה דש\"פ תבוא, דמיני' מתברכין כל שיתא יומין שלאחריו (זח\"ג סג, ב. פח, א), כולל (ובמיוחד) יום ח\"י אלול, שחל בשנה זו (תשמ\"ט*) ביום השני שלאחריו**.\nוראה תורת הבעש\"ט עה\"פ שנאמרה ביום ההולדת שלו, בש\"פ תבוא ח\"י אלול (כהקביעות דשנה זו – ה'תשל\"ג) תרנ\"ב (בג\"ע) – נדפס בכתר שם טוב (הוצאת קה\"ת) הוספות סי' ג. ספר השיחות תרצ\"ז ע' 207.\nולהעיר מהשייכות ד\"קומי אורי\" לח\"י אלול – ראה שיחת ח\"י אלול ה'תש\"ה סי\"ד (לקו\"ד כרך ג תפ, סע\"ב. ספר השיחות ה'תש\"ה ע' 129), שבח\"י אלול תק\"ה (שאז נולד רבינו הזקן) – שהקביעות דח\"י אלול אז היתה ביום הרביעי – אמר הבעש\"ט לתלמידיו, אשר \"ביום הרביעי וואָס בו נתלו המאורות, איז אין דעם יום הרביעי פון <i>קומי אורי</i> אַראָפּגעקומען אַ נשמה חדשה וועלכע וועט באַלייכטן די וועלט אין תורה הנגלית והחסידות\"."],["2326","2","בתרגום (וכ\"ה ברד\"ק ובמצודת דוד שם) \"קומי אנהרי <i>ירושלים</i>\". אבל בילקוט (הובא לקמן בפנים) שזהו מאמר הקב\"ה <i>לישראל</i>."],["2327","3","שמעוני עה\"פ (רמז תצט בתחלתו) [והוא ממדרש תהלים על הפסוק (תהלים לו, י) כי עמך מקור חיים גו'. פסיקתא פכ\"א]. – הובא ונתבאר באוה\"ת (יהל אור) לתהלים שם (ס\"ע קלח)."],["2328","4","תהלים שם."],["2329","5","דשנת ה'ש\"ת (נדפס בסה\"מ ה'ש\"ת ע' 11 ואילך). בהמובא לקמן בפנים – ראה שם בתחלת המאמר (ע' 11) ובסופו (ע' 19).\n*) <i>וכן היתה הקביעות בשנת נח\"ת – שנת הולדת הבעל שם טוב (ספר השיחות ה'תש\"ג ע' 141)</i>.\n**) <i>בתוך השלשה ימים דבתר שבתא – ראה פסחים קו</i>,<i> סע\"א</i>.<i> שו\"ע אדה\"ז או\"ח סרצ\"ט ס\"ח</i>.<i> ועוד</i>.<i> וראה גם פע\"ח שער ח\"י (שער השבת) פ\"א</i>.<i> סהמ\"צ להצ\"צ ח</i>,<i> א</i>.<i> ולהעיר גם מהדין (שו\"ע אדה\"ז או\"ח סשמ\"ה ס\"ג</i>.<i> ובכ\"מ) שפחות משלשה (במקום) כלבוד דמי</i>."],["2330","6","משלי ו, כג."],["2331","7","ולהעיר מ<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380213\" data-slug=\"likkutei-torah\" data-id=\"4001380213\">לקו\"ת אמור לא, ד</a>, ש\"מקור חיים\" \"הוא בחי' המקור חיים <i>המתלבש</i> בבחי' ממכ\"ע\"."],["2332","8","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380308\" data-slug=\"likkutei-torah\" data-id=\"4001380308\">אחרי כו, ג</a>. וראה גם יהל אור לתהלים שם אות ו (ע' קלח), דפירוש \"מקור\" בפסוק זה הוא \"ע\"ד הנז' בענין ונצבת על הצור, שהצור מקור מוצא האש\".\nוביהל אור שם (לפני זה) מבחיי ר\"פ וישלח (הובא גם בלקו\"ת ויקרא בהוספות נד, א) \"ומפני זה נק' הקב\"ה מקור לפי שכחו אינו פוסק לעולם ולעולמי עד . . כי עמך מקור חיים\"."],["2333","9","ראה מו\"נ ח\"א פט\"ז. ספר הליקוטים – דא\"ח צ\"צ ערך צור."],["2334","10","המשך תער\"ב ח\"ג ע' א'שלד."],["2335","11","יהל אור שם אות ד (ע' קלז)."],["2336","12","שמו\"ר ס\"פ לא – הובא ביהל אור שם אות ו לענין כי עמך מקור חיים."],["2337","13","משפטים כב, כד."],["2338","14","ויש לומר, דזהו גם המשך הענינים שביהל אור שם, דלאחרי שמבאר שפירוש \"מקור\" כאן הוא \"שכחו אינו פוסק כו'\" או שהוא ע\"ד צור (כנ\"ל הערה 8) – הוא מבאר (באותו האות) דפירוש \"עמך\" כאן הוא ע\"ד \"אתה עמי\". ועפ\"ז יומתק גם מה שבאות זה מובא רק פירוש השני ד\"עמך\" – כי זה בא בהמשך להפירוש \"מקור\" שבתחילת האות."],["2339","15","סה\"מ ה'תש\"ג ע' 164. ובכ\"מ."],["2340","16","המשך תרס\"ו ע' קפ ואילך. שם ע' רכה. ועוד."],["2341","17","ע\"ח שער א (דרוש עיגולים ויושר) ענף ב. אוצרות חיים ומבוא שערים בתחלתם."],["2342","18","פרקי דר\"א פ\"ג. – יש שם גירסאות אחרות, דיוק גירסא זו דוקא מבואר בהקדמת השל\"ה בתחילתה (ג, ב), הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381187\" data-slug=\"likkutei-torah\" data-id=\"4001381187\">לקו\"ת שה\"ש יד, ג</a>. וכ\"ה גם בפרדס שער ג (שער אם הא\"ס הוא הכתר) פ\"א. וראה ג\"כ תקו\"ז תיקון יט (מ, ב)."],["2343","19","סה\"מ תרנ\"ד ע' רצט. המשך תרס\"ו ס\"ע קפג ואילך. ועוד."],["2344","20","ראה סה\"מ תקס\"ב ע' רפא בענין הי' הוא ושמו בלבד, ש\"אור\" הוא \"<i>התפשטות</i>\" משא\"כ \"שם\" הוא \"גילוי\". דהחילוק בין \"התפשטות\" ל\"גילוי\" הוא, דהתפשטות הוא (ראה שם ע' רפ) שמתפשט חוץ למקומו, וכמו האור שמתפשט בחלל העולם מחוץ להשמש, שהוא כמו חידוש והוספה על הדבר המתפשט, משא\"כ \"גילוי\" הוא במקומו של הדבר המתגלה (ולא חוץ ממנו)*, ולכן אינה הוספה אמיתית על הדבר המתגלה (ראה סה\"מ שם ע' רפ. סידור (עם דא\"ח) ד\"ה זכר רב טובך – מח, א ואילך)."],["2345","21","ראה גם המשך תרס\"ו ע' קפו, דהטעם שנק' \"שמו\" ולא \"אור\" הוא, כי \"שם\" מיוחד יותר מ\"אור\". אלא שהביאור שם הוא באו\"א."],["2346","22","ראה בארוכה המשך תרס\"ו ע' תקי ואילך. ובכ\"מ."],["2347","23","שם ס\"ע תקטו ואילך. וראה גם שם ע' קפה. ובכ\"מ."],["2348","24","ראה בארוכה המשך הנ\"ל ע' קעח. קפ. ובכ\"מ."],["2349","25","המשך תער\"ב ח\"א פקכ\"ח (ע' רמז ואילך). סה\"מ ה'תש\"ג ס\"ע 124.\n*) <i>ועד\"ז הוא מה שהאדם פונה כשקוראין אותו בשמו</i>,<i> שענינו הוא (רק זה) </i><b>שהוא</b><i> פונה</i>.<i> משא\"כ באור</i>,<i> כמו אור השמש לדוגמא – נוגע בזה מה שנעשה </i><b>אור</b><i> לארץ ולדרים עלי'</i>,<i> ולא זה </i><b>שהשמש</b><i> מתגלה</i>."],["2350","26","ראה גם המשך תרס\"ו ס\"ע תקטו \"להיות שהוא בבחי' המשכה וגילוי . . הוא בבחי' מקור עכ\"פ\"."],["2351","27","וכ\"מ ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380300\" data-slug=\"likkutei-torah\" data-id=\"4001380300\">לקו\"ת ויקרא בהוספות נב, א</a>-ב."],["2352","28","ראה פרש\"י ר\"פ בראשית. וראה ד\"ה החודש הזה ה'תשמ\"ז ס\"ד (לעיל ח\"ב ע' קיב ואילך)."],["2353","29","ראה בארוכה סה\"מ ה'ש\"ת ע' 61 ואילך. ה'תש\"ד ע' 129 ואילך. ה'תש\"ה ע' 121 ואילך. ובכ\"מ."],["2354","30","להעיר, דענין זה (שישראל קדמו לתורה) שייך לענין ביכורים דריש פרשתנו – ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450564\" data-slug=\"or-hatorah-hb\" data-id=\"8316450564\">אוה\"ת</a> פרשתנו (ע' תתרלד. שם ע' תתרלט) דתרומה (אותיות תורה מ' – זח\"ג קעט, א) היא תורה, וביכורים שקודמים לתרומה הם ישראל שקדמו לתורה."],["2355","31","כ\"ה במקומות שבהערה 29. וראה תדבא\"ר פי\"ד. ב\"ר פ\"א, ד. וראה לקו\"ש חל\"ד ע' 222 הערה 48."],["2356","32","ראה יד, א."],["2357","33","ולהעיר מהמבואר בד\"ה כי עמך ה'ש\"ת ע' 18, דגם זה שישראל עלו במחשבה \"היא המחשבה עצמית כמו שחושב כביכול בדבר הנבדל\"."],["2358","34","הובא ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא</a> פ\"ד ורפכ\"ג בשם הזהר. וראה זהר ח\"א כד, א. ח\"ב ס, סע\"א. תקו\"ז ת\"ו (כא, ב). תכ\"ב (סד, א). ועוד."],["2359","35","ויש לומר, דזה שבתורה כתיב \"אור<i>ך</i>\" ובישראל \"אור\" – הוא, כי תורה היא מיוחדת וישראל נעשו מציאות נבדל."],["2360","36","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111005\" data-slug=\"likkutei-sichot\" data-id=\"1300111005\">לקו\"ש חי\"ח ע' 409</a>. וראה לקו\"ש חי\"א ע' 5 ואילך."],["2361","37","וב<a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a> שזה קאי על הנשמה."],["2362","38","<a class=\"ft-cite\" href=\"#/read/tanya/3401310054\" data-slug=\"tanya\" data-id=\"3401310054\">תניא פמ\"ט (סט, סע\"א</a> ואילך). וראה ספר השיחות תורת שלום ע' 120."],["2363","39","לכאורה מוכרח כן גם ממ\"ש בילקוט (הובא לעיל ס\"א) \"אין אנו ממתינין אלא לאורך . . באורך נראה אור\", שהרי זה ש\"ממתינין\" הוא לפני הגאולה. אלא שהפירוש בילקוט בפשטות הוא שעכשיו רק <i>ממתינין</i> לאורך שיהי' לע\"ל, ואז \"נראה אור\", \"נראה\" לשון עתיד. והחידוש בהמאמר הוא, שפירוש \"נראה אור\" הוא \"זעען מיר\" (לשון הוה), כדלקמן בפנים. היינו, שגם עכשיו \"רואים\" ישראל האור (דלע\"ל)."],["2364","40","תהלים סג, ב-ג."],["2365","41","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא רפל\"ז</a>."],["2366","42","ישעי' ס, כב."],["2367","43","כי ע\"י מעשינו ועבודתינו נעשה \"זכו\", שאז – \"אחישנה\" (סנהדרין צח, א)."]]],[1500390036,"<h3>בס\"ד. אור ליום ב' פ' נצבים-וילך, ח\"י אלול ה'תשל\"ט<sup data-n=\"2368\">*</sup></h3>\n(הנחה)\n<b>אתם</b> נצבים היום כולכם לפני ה' אלקיכם ראשיכם שבטיכם גו' לעברך בברית ה' אלקיך גו'<sup data-n=\"2369\">1</sup>, ואח\"כ ממשיך<sup data-n=\"2370\">2</sup> (בפ' שני, שיעור לימוד החומש דיום זה) (ולא אתכם לבדכם אנכי כורת את הברית הזאת גו' כי את גו' אשר איננו פה עמנו היום) ושב<sup data-n=\"2371\">3</sup> ה' אלקיך גו'. והנה פרשה זו קורין לעולם קודם ראש השנה (כמ\"ש רבינו הזקן בלקו\"ת<sup data-n=\"2372\">4</sup>), וידועה תורת הבעש\"ט<sup data-n=\"2373\">5</sup> שאתם נצבים זהו ברכתו של הקב\"ה שמברך את עמו בני ישראל בשבת מברכים שהוא השבת האחרון דחודש אלול בברכת החודש דחודש השביעי, ובכח זה ישראל מברכים את החדשים דכל השנה, שמזה מובן שענין זה (דאתם נצבים גו') הוא ענין כללי. והענין הוא, דהנה הכתוב מבאר דזה שאתם נצבים היום כולכם גו', כל עשר המדריגות<sup data-n=\"2374\">6</sup> מראשיכם שבטיכם עד חוטב עציך ושואב מימיך, לאחדים כאחד<sup data-n=\"2374\">6</sup>, הוא בכדי לעברך בברית ה' אלקיך גו' שקודם שנכנסו לארץ (שאז נאמרה פרשה זו בפעם הראשונה) הי' כריתת ברית על קבלת התורה מלבד הברית אשר כרת אתם בחורב<sup data-n=\"2375\">7</sup>, היינו שמדובר כאן על כריתת ברית מיוחדת שלפני הכניסה לארץ. ומכיון שלא אתכם לבדכם אנכי כורת את הברית הזאת (כ\"א גם) את אשר איננו פה עמנו היום, מובן שענין הכריתת ברית שלפני כניסת הארץ שייך בעבודת כל אחד ואחד.\nב) <b>ויובן</b> זה בהקדם ביאור ענין הכניסה אל הארץ בעבודה. דהנה כתיב (בפרשת השבוע דשבת שעברה<sup data-n=\"2376\">8</sup>, שמיני' מתברכין כולהו יומין שלאחרי'<sup data-n=\"2377\">9</sup>, כולל יום זה, יום ח\"י אלול) והי' כי תבוא אל הארץ אשר ה' אלקיך נותן לך וגו'. ומבאר הבעש\"ט נ\"ע<sup data-n=\"2378\">10</sup> (בהתורה שנאמרה ע\"י כ\"ק מו\"ח אדמו\"ר נשיא דורנו ששמעה מאביו כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע ששמעה מהבעש\"ט): והי' כי תבוא אל הארץ – אַז דו וועסט צוקומען צו דעם רצון [העליון] ומרוצה, אשר ה' אלקיך נותן לך נחלה וירשתה – וואס דאס איז א מתנה מלמעלה בירושה בכל אחד מישראל, דארף זיין די עבודה אין דעם, וישבת בה – דאס זאל זיין בהתיישבות, ולקחת גו' ושמת בטנא– מלביש זיין די אורות אין כלים, והלכת אל המקום – הוא ענין השגחה פרטית, אשר יבחר ה' אלקיך – אַז אַ איד גייט אין אַן אָרט, איז דאָס ניט וואָס ער גייט נאָר מ'פירט אים, די השגחה העליונה. איז אַז ער קומט אין אַן אָרט איז די כוונה – לשכן שמו שם – לפרסם אלקות בעולם. ואח\"כ אמר הבעש\"ט עוד הפעם התורה הקודמת והוסיף שענין לשכן שמו שם הוא \"מיט אַ ברכה ופסוק תהלים\". והרב המגיד נ\"ע (תלמידו וממלא מקומו של הבעש\"ט) פירש<sup data-n=\"2379\">11</sup>: והי' כי תבוא אל הארץ, פירוש כו' כאשר תרצו לבוא אל הארץ העליונה (עולם הבא) אשר ה' אלקיך נותן לך, כי כל ישראל יש להם חלק לעולם הבא<sup data-n=\"2380\">12</sup>, וירשת, ליורשה ירושת עולם בכדי שלא יצטרך להתגלגל (ח\"ו) רק וישבת בה ישיבה עולמית ונצחית, ככה תתנהג ותזכה: ולקחת מראשית גו' ר\"ל ראשית לקיחתך מעינוגי העולם הזה יהי' מראשית שהיא החכמה שנאמר<sup data-n=\"2381\">13</sup> ראשית חכמה וגו', פירוש שכל עניני עולם הזה מעורב בם ניצוץ קדוש שהוא החכמה כו', לכן כל לקיחתך ועשיתך כו' יהי' הכל עיקר השגחתך ומגמתך על הראשית שבו שהיא החכמה הקדושה שבו. ולכן אמר מראשית ולא כל ראשית<sup data-n=\"2382\">14</sup>, כי כולו גשמיות הוא רק שיש בו קצת קדושה שהיא ראשית כו', וז\"ש מראשית כל פרי האדמה שהם הניצוצות שבתוך הצומח. ולא מבעי שתראה לברר מתוך הצומח אלא אפילו אשר תביא מארצך, פירוש אפילו מדבר שהוא ארציות גמור שהוא הדומם שהוא גשמי יותר מצומח. ולא הזכיר כאן הניצוצות שבתוך בע\"ח, מפני שבקל יוכל להעלותם אל הקדושה כמ\"ש בכתבי האר\"י זלה\"ה. והדר אמר לא תימא שאני מזהירך רק בדברים גשמיים שהם דומם צומח (חי), אלא אפילו בדברים הרוחניים, שהם דברי תורה. וז\"ש אשר ה\"א נותן לך כו' יהי' כוונתך רצוי' ומחשבתך זכה ודיבורך שלם כו', שיהי' ניכר בכל דיבור ודיבור היוצא מפיך כל אות ואות ונקודיו וטעמיו שבו. וז\"ש ושמת בטנא, כי טנ\"א ר\"ת <i>ט</i>עמים <i>נ</i>קודות <i>א</i>ותיות. ולא הזכיר כאן תגין, מפני שאינם במבטא כו' וכאשר תתנהג כן [פירוש, שבכל ענינים אלו יהי' ענין ולקחת מראשית, בחי' החכמה, אז יהי'] והלכת אל המקום כו' ותעלה הכל אל הקדושה. וזהו אשר יבחר ה' אלקיך כו' וזהו לשכן שמו שם. וזהו שפתח הכתוב בלשון והי' שהוא לשון שמחה<sup data-n=\"2383\">15</sup> כו'. ורבינו הזקן פירש (בלקו\"ת פ' תבוא<sup data-n=\"2384\">16</sup>) דכמו שיש בחי' ארץ ישראל בעולם כך יש בשנה והוא בראש השנה, וקודם לזה צ\"ל כריתת ברית וכו'.\nג) <b>ולהבין</b> כ\"ז הנה ידוע דכל הענינים שבעולם מקורם הוא בתורה, וכן הוא בענין א\"י (והכניסה לא\"י) שיש בחי' זו בתורה. וכמו שמבאר רבינו הזקן בארוכה (בתו\"א בתחלתו<sup data-n=\"2385\">17</sup> ובלקו\"ת שם) דארץ ישראל היא בחי' תושבע\"פ, כי ארץהוא לשון רצון ומרוצה (כמובא בתורת הבעש\"ט הנ\"ל) וכמאמר<sup data-n=\"2386\">18</sup> למה נקרא שמה ארץ שרצתה לעשות רצון קונה, וגילוי רצון העליון הוא ע\"י תושבע\"פ דוקא<sup data-n=\"2387\">19</sup>. דבכדי לקיים את רצון העליון אינו מספיק הלימוד בתושב\"כ, כי הגם דליכא מידי דלא רמיזא באורייתא<sup data-n=\"2388\">20</sup>, ה\"ז באופן דרמז בלבד ויכול להיות מזה ב' דעות, דאלו ואלו דברי אלקים חיים<sup data-n=\"2389\">21</sup>, ודוקא ע\"י ההלכה פסוקה ופסק דין ברור בתושבע\"פ אפשר לדעת ולקיים את הרצון העליון.\nד) <b>ובזה</b> יובן ענין הכריתת ברית שלפני הכניסה לארץ ישראל, שהיא תושבע\"פ. כי הנה ענין תושבע\"פ הוא חיבור המעלה מעלה עם המטה מטה, דההלכה מקורה מרצון העליון שלמעלה מעלה מבחי' חכמה (שהו\"ע התורה בפשטות), והיא בחי' והוי' עמו<sup data-n=\"2390\">22</sup> שהלכה כמותו<sup data-n=\"2391\">23</sup> (שלמעלה לא רק מבחי' אלקים אלא גם מבחי' אלו ואלו דברי אלקים חיים, דאלקים חיים הוא בחי' הבינה, כמבואר בדרושי כ\"ק אדמו\"ר הצ\"צ<sup data-n=\"2392\">24</sup> וכ\"ק אדמו\"ר מהר\"ש<sup data-n=\"2393\">25</sup> והנשיאים שלאחריהם ממלאי מקומם<sup data-n=\"2394\">26</sup> המבארים ענין אלקים חיים), ומשם נמשכה בפס\"ד להלכה למעשה בעוה\"ז. וכמו שמבאר רבינו הזקן באגה\"ק<sup data-n=\"2395\">27</sup> המשל לקיום המצוות כעמוד המחבר את הגג עם הרצפה. ובלשון הקבלה והחסידות הוא חיבור סובב כל עלמין וממלא כל עלמין. וידוע שבשביל חיבור זה צ\"ל המשכה ממקום שלמעלה משניהם, וזהו ענין הברית.\nה) <b>ומזה</b> יובן ענין הכריתת ברית בבחי' נפש, דכשם שענין הברית כפשוטו הוא שממשיך מענין שלמעלה מטעם ודעת, דלכן אין שייך בו שום שינוי כלל וכן יקום, דעי\"ז מאחדים הפכים, וכמבואר בלקו\"ת<sup data-n=\"2396\">28</sup> דע\"י שעוברים בין הבתרים נעשים לאחדים כאחד ממש<sup data-n=\"2397\">29</sup>, עד\"ז יובן בענין הכריתת ברית בנפש שבשביל איחוד הסתים וגליא שבנפש צ\"ל ענין הברית שהוא ההמשכה ממקום עליון ביותר בנפש (ע\"ד הנ\"ל בתורה).\nו) <b>וזהו</b> גם ענין הכריתת ברית בבחי' עולם שלפני הכניסה לארץ כפשוטה, כי תבוא אל הארץ גו' וירשתה וישבת בה. דהנה מבואר בכ\"מ<sup data-n=\"2398\">30</sup> שעניןהכניסה לארץ ישראל הי' הירידה מעולם המחשבה או מעולם הדיבור לעולם המעשה, ירידה למטה מטה לארץ אוכלת יושבי'<sup data-n=\"2399\">31</sup>, וכיון שהי' צריך להיות החיבור דמעלה מעלה עם המטה מטה, לכן הי' צריך להיות לפנ\"ז כריתת ברית מיוחדת לבד הברית אשר כרת אתם בחורב, כי גם אחרי הברית שבחורב היו עדיין דור דעה<sup data-n=\"2400\">32</sup> (בחי' מחשבה או בחי' דיבור), משא\"כ כאן הי' צריך להיות הירידה למטה מטה, עד שפעלו שתהי' טובה הארץ מאד מאד<sup data-n=\"2401\">33</sup>, הנה לזה הי' צ\"ל כריתת ברית מיוחדת<sup data-n=\"2402\">34</sup>.\nז) <b>והנה</b> כשם שיש ענין הכריתת ברית בנפש ובעולם כן הוא גם בשנה, דבראש השנה הוא בחי' כניסה לארץ ישראל בשנה<sup data-n=\"2403\">35</sup> ובכל שנה קודם ראש השנה צריך כריתת ברית מחדש. והענין הוא, דהנה בראש השנה הוא שלימות עבודת האדם, דאז הקב\"ה אומר תמליכוני עליכם<sup data-n=\"2404\">36</sup> [דההחלטה על בריאת העולם היא ע\"י נשמות ישראל וכמאמר<sup data-n=\"2405\">37</sup> במי נמלך בנשמותיהן של צדיקים, ועמך כולם צדיקים<sup data-n=\"2406\">38</sup>, וכמבואר בארוכה בתורת הרב המגיד באור תורה ובלקו\"א בתחלתו<sup data-n=\"2407\">39</sup> דע\"י שעלה לפניו ית' התענוג מעבודת הצדיקים כו' וכמשל האב המצייר לעצמו את בנו הקטן כו'. וכן הוא בכל ראש השנה דההמלכה היא ע\"י ישראל דוקא], ועי\"ז היא ההחלטה להיות מלך על כל העולם. ומההחלטה שבראש השנה נמשך לכל ימות השנה, דלכן נקרא ראש השנה ולא תחלת השנה, כמבואר בארוכה בעטרת ראש בתחלתו<sup data-n=\"2408\">40</sup> שהוא בדוגמת הראש הכולל את כל האברים, וגם אח\"כ כאשר האברים נמצאים כל אחד במקומו הנה הראש הוא המנהיג אותם, דכן הוא בראש השנה שהוא המנהיג את כל ימות השנה, ועד שנמשך במעשה בפועל. שזהו ענין המשכה מן הקצה אל הקצה. וגם כללות ענין ההחלטה להיות מלך נמשך ע\"י הכתרת נשמות ישראל שהם עצמם שרשם למעלה אפילו מתורה, ומשם נמשך למטה דוקא ע\"י פסק דין בתורה, היינו ההוראות שבתורה בנוגע למעשה בפועל, אשר כדי לבוא לפסק דין אמיתי צריך להתייגע כדי לבוא אל האמת לאמיתו (כמבואר בהמשך יו\"ט של ראש השנה שחל להיות בשבת מכ\"ק אדמו\"ר נ\"ע<sup data-n=\"2409\">41</sup> ובדרושי כ\"ק מו\"ח אדמו\"ר נשיא דורנו ממלא מקומו), הנה כל זה הוא המשכה מן הקצה הכי עליון אל הקצה הכי תחתון. ולכן צריך להיות לפנ\"ז ענין הכריתת ברית במיוחד, שע\"י הכריתת ברית נעשים כל בני ישראל (ועמך כולם צדיקים) חד עם עצמות ומהות, בדוגמת הברית כפשוטו בגשמיות.ח) <b>ומהכריתת</b> ברית בכללות נמשכות ההחלטות טובות בנוגע ללימוד התורה וקיום המצוות ועבודת התפלה, דעי\"ז ישראל וקוב\"ה כולא חד. ומזה באה כתיבה וחתימה טובה לשנה טובה ומתוקה, והתחלתה לפנ\"ז בחודש ההכנה הוא חודש אלול שהוא ר\"ת אני לדודי ודודי לי<sup data-n=\"2410\">42</sup>, ובפרט מח\"י אלול שהוא יום הולדת שני המאורות הגדולים<sup data-n=\"2411\">43</sup> שאז מזלם גובר<sup data-n=\"2412\">44</sup>, והרי תכליתם וכוונתם היתה שיהי' יפוצו מעינותיך חוצה, עד להחוצה שאין חוצה מחוץ הימנו. ועי\"ז אתי מר<sup data-n=\"2413\">45</sup> דא מלכא משיחא בקרוב ממש, ובעגלא דידן.\n**********",[["2368","*","יצא לאור בשעתו, \"<i>עש\"ק פ' נצבים-וילך</i>,<i> ה'תשל\"ט</i>\"."],["2369","1","פרשתנו (נצבים) כט, ט-יא."],["2370","2","שם, יג-יד. שם ל, ג."],["2371","3","והשיב לא נאמר כו' (מגילה כט, א הובא בפרש\"י עה\"ת)."],["2372","4","ריש פרשתנו."],["2373","5","היום יום ע' צ [כה אלול]."],["2374","6","לקו\"ת שם."],["2375","7","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380883\" data-slug=\"likkutei-torah\" data-id=\"4001380883\">לקו\"ת תבוא מא, ג</a>."],["2376","8","תבוא כו, א-ב."],["2377","9","ראה זח\"ב סג, ב. פח, א."],["2378","10","כתר שם טוב (הוצאת קה\"ת) הוספות אות ג. היום יום ע' פח [חי אלול]."],["2379","11","או\"ת נו, א ואילך."],["2380","12","סנהדרין צ, א במשנה."],["2381","13","תהלים קיא, י."],["2382","14","מנחות פד, ב. פרש\"י עה\"פ תבוא שם, ב."],["2383","15","ב\"ר פמ\"ב, ג (בסופו). ויק\"ר פי\"א, ז (בסופו). אסת\"ר פתיחתא יא."],["2384","16","שם."],["2385","17","א, ריש ע\"ב."],["2386","18","ב\"ר פ\"ה, ח."],["2387","19","אגה\"ק ס\"א. סכ\"ט (קנ, ב). לקו\"ת שם."],["2388","20","ראה תענית ט, א."],["2389","21","עירובין יג, ב."],["2390","22","שמואל-א טז, יח."],["2391","23","סנהדרין צג, ב."],["2392","24","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316460075\" data-slug=\"or-hatorah-hb\" data-id=\"8316460075\">אוה\"ת יתרו ע' תתצ</a> ואילך."],["2393","25","ד\"ה וידבר אלקים תרכ\"ז."],["2394","26","המשך תרס\"ו ע' תלא ואילך. סה\"מ: עטר\"ת ע' תמט ואילך. תרפ\"ח ע' קכט ואילך. ובכ\"מ."],["2395","27","סכ\"ט (קמט, סע\"ב ואילך). וראה סה\"מ תש\"י ע' 123."],["2396","28","פרשתנו מד, ב."],["2397","29","ראה סה\"מ תש\"ב ע' 25, דזה שכורתין דבר אחד לשנים [אף שמורה על הפירוד והתחלקות, היפך האחדות], הוא להיות דהכוונה היא לאחד שני גופים, דכורתי הברית הם ב' גופים נפרדים וע\"י הכר\"ב הם מתאחדים."],["2398","30","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380461\" data-slug=\"likkutei-torah\" data-id=\"4001380461\">לקו\"ת שלח לז, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380464\" data-slug=\"likkutei-torah\" data-id=\"4001380464\">לח, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380465\" data-slug=\"likkutei-torah\" data-id=\"4001380465\">לח, ב</a>."],["2399","31","שלח יג, לב."],["2400","32","ראה ויק\"ר פ\"ט, א. במדב\"ר פי\"ט, ג."],["2401","33","שלח יד, ז. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380461\" data-slug=\"likkutei-torah\" data-id=\"4001380461\">לקו\"ת שם לז, ב</a>. לח, ג."],["2402","34","להעיר ממארז\"ל (ברכות מט, א) כל שאינו אומר ברית כו' בברכת הארץ כו' לא יצא ידי חובתו (וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380773\" data-slug=\"likkutei-torah\" data-id=\"4001380773\">לקו\"ת עקב יד, ד</a>. אוה\"ת תבוא ע' תתרנא)."],["2403","35","לקו\"ת תבוא שם. ושם: שר\"ה הוא ענין אחד עם תורה שבע\"פ כי ר\"ה הוא בחי' שתמליכוני עליכם ומלכות פה תורה שבע\"פ קרינן לה."],["2404","36","ר\"ה טז, א. לד, ב."],["2405","37","ב\"ר פ\"ח, ז. רות רבה רפ\"ב."],["2406","38","ישעי' ס, כא."],["2407","39","וראה גם או\"ת ב, ג ואילך."],["2408","40","וראה גם לקו\"ת שם."],["2409","41","המשך תרס\"ו ע' שצ ואילך."],["2410","42","שה\"ש ו, ג. אבודרהם סדר תפלת ר\"ה. פע\"ח שער ר\"ה פ\"א. שעה\"פ עה\"פ."],["2411","43","סה\"ש תש\"ג ע' 141 ואילך."],["2412","44","ראה קה\"ע לירושלמי ר\"ה פ\"ג ה\"ח."],["2413","45","אגה\"ק דהבעש\"ט – נדפסה בריש ספר כתר שם טוב הוצאת קה\"ת."]]],[1500390037,"<h3>בס\"ד. ש\"פ נצבים-וילך, כ\"ג אלול ה'תשל\"ט<sup data-n=\"2414\">*</sup></h3>\n<b>אתם</b> נצבים היום כולכם לפני הוי' אלקיכם ראשיכם שבטיכם גו' מחוטב עציך עד שואב מימיך<sup data-n=\"2415\">1</sup>. ואיתא בלקו\"ת<sup data-n=\"2416\">2</sup> דפרשה זו קורין לעולם קודם ר\"ה<sup data-n=\"2417\">3</sup> ומרומז במלת היום דקאי על ר\"ה<sup data-n=\"2418\">4</sup> כי זה<sup data-n=\"2419\">5</sup> היום תחלת מעשיך זכרון ליום ראשון. וזהו מ\"ש אתם נצבים היום <i>כולכם</i> גו', שכל בני ישראל מראשיכם שבטיכם גו' עד חוטב עציך ושואב מימיך הם מתאחדים יחד להיות לאחדים כאחד<sup data-n=\"2420\">6</sup>, כי הכלי להברכות וההמשכות שלמעלה הוא ענין האחדות, כמ\"ש<sup data-n=\"2421\">7</sup> ברכנו אבינו (כאשר) כולנו כאחד דוקא (כמבואר בארוכה בתניא פרק לב, לקו\"ת ד\"ה החלצו<sup data-n=\"2422\">8</sup>, ובסהמ\"צ להצ\"צ מצות אהבת ישראל). ובהיות שבר\"ה היא המשכת החיות על כל השנה, כידוע (ומבואר בארוכה בעט\"ר<sup data-n=\"2423\">9</sup>, וברמז בלקו\"ת<sup data-n=\"2424\">10</sup>) דנקרא ראש השנה (ולא תחלת השנה) כי הוא בדוגמת הראש שכולל בתוכו כל אברי הגוף, וגם כמו שהאברים הם במקומם נמצא בהם הראש ועד שהוא המנהיג אותם (שכל האברים נשמעים לרצונו), עד\"ז הוא בהיום דר\"ה, שבו נמשך כל החיות של כל ימי השנה, וגם הנהגתם אח\"כ היא כפי אופן המשכתם בר\"ה (ועד\"ז הוא בעבודת האדם, שהנהגתו בכל ימי השנה היא כפי אופן ההחלטות בר\"ה). וזהו אתם נצבים היום כולכם גו', כי ההכנה והכלי להמשכה זו הוא כולכם, ההתאחדות דבני ישראל להיות לאחדים כאחד, שעי\"ז הם כלים להשראת יחודו ית'.\nב) <b>ומפרט</b> הכתוב עשר מדריגות (ראשיכם שבטיכם גו' מחוטב עציך עד שואב מימיך), שכמו שיש עשר מדריגות בנפש האדם דהיינו ג' שכלים וז' מדות, כך כל ישראל הם קומה אחת שלימה שנחלקת לעשר מדריגות<sup data-n=\"2425\">11</sup>. והענין הוא, שהאחדות דבני ישראל מה שהם מתאחדים להיות לאחדים כאחד שעי\"ז הם נעשים כלים להשראת יחודו ית', הוא לא באופן שאין בהם חילוקי מדריגות (גם לא שמצד הגילוי דבחינת יחיד הם מתבטלים ממציאותם), כי אם, דכמו שהם בבחינת מציאותונחלקים לעשר מדריגות, מכל מקום הם מתאחדים בהתאחדות גמורה. דהתאחדות זו (התאחדות של פרטים) היא כמו ההתאחדות דבחינת אחד (שלמטה מבחינת יחיד). וכידוע<sup data-n=\"2426\">12</sup> ההפרש בין אחד ליחיד, דיחיד הוא למעלה מהתחלקות משא\"כ אחד הוא שישנם דברים מחולקים אלא שהם מתאחדים. וכמרומז גם בהאותיות דתיבת אחד, שהח' והד' מורים לז' רקיעים וארץ וד' רוחות העולם<sup data-n=\"2427\">13</sup>, והם בטלים להאל\"ף. והאל\"ף אינו שולל את מציאות העולם, שהאל\"ף עצמו פירושו אלופו של עולם<sup data-n=\"2427\">13</sup>, והאל\"ף הוא הראש דתיבת אחד שכולל<sup data-n=\"2428\">14</sup> (כנ\"ל בענין ראש) את הח' (ז' רקיעים וארץ) והד' (ד' רוחות העולם), וע\"י התאחדות זו דבני ישראל [שהם בבחינת מציאות ונחלקים לעשר מדריגות וביחד ע\"ז לאחדים כאחד] הם נעשים רשות היחיד ליחודו ית', היינו לבחינת יחיד (שלמעלה מבחינת אחד)<sup data-n=\"2429\">15</sup>, גילוי דבחינת יחיד שנמשך בבחינת חי העולמים מלך, ועד להמציאות והתחלקות המדריגות<sup data-n=\"2430\">16</sup> עד לבחינת חוטב עציך ושואב מימיך. ואדרבה, ע\"י ההתאחדות דבני ישראל גם כמו שהם נחלקים לעשר מדריגות עד לבחינת חוטב עציך ושואב מימיך, עי\"ז נעשים חד עם עצמותו ית'.\nג) <b>וזהו</b> מה שממשיך בכתוב<sup data-n=\"2431\">17</sup> לעברך בברית [שלעברך בברית הוא ביאור על מ\"ש לפנ\"ז אתם נצבים היום כולכם גו', וכדאיתא בלקו\"ת<sup data-n=\"2432\">18</sup> שבזה מבאר איך הוא דרך היחוד ומהו ענין התשובה ולמה דוקא בראש השנה], וכמבואר בלקו\"ת<sup data-n=\"2432\">18</sup> שהוא כמו שני אוהבים שכורתים ברית ביניהם שהם מתקשרים זה עם זה כאילו נעשו לבשר אחד. דזהו מה שאופן הכריתת ברית הוא כמ\"ש<sup data-n=\"2433\">19</sup> אשר כרתו את העגל ויעברו בין בתריו, היינו דמה ששניהם עוברים בתוך גוף אחד מורה<sup data-n=\"2434\">20</sup> על שנעשו לבשר אחד. ומדייק בלקו\"ת שנעשו <i>לבשר</i> אחד, וכן שניהם עוברים בתוך <i>גוף</i> אחד, כי היחוד דהקב\"ה עם בני ישראל הוא גם מצד הגוף הגשמי, ואדרבה, מצד הכוונה דדירה בתחתונים הדירה לעצמותו ומהותו היא דוקא בתחתונים. וכמ\"ש<sup data-n=\"2435\">21</sup> באתי לגני וארז\"ל<sup data-n=\"2436\">22</sup> לגנוני כו' דעיקר שכינה בתחתונים היתה, דדוקא בתחתונים היא בחינת גני וגנוני, שענין הגן מורה על התענוג והשעשוע שלו כביכול, ותענוג ושעשועים זההוא בתחתונים דוקא. והענין הוא, דהנה מבואר באגה\"ק ד\"ה איהו וחיוהי חד איהו וגרמוהי חד<sup data-n=\"2437\">23</sup> שהתהוות היש הנברא הוא בכח העצמות שמציאותו הוא מעצמותו ואינו עלול מאיזה עילה שקדמה לו ח\"ו, שלכן גילוי העצמות הוא (לא בחיוהי וגם לא בגרמוהי כי אם) דוקא בהיש הנברא. וכמבואר בביאוה\"ז<sup data-n=\"2438\">24</sup> שאמיתית מציאותו של היש הנברא (מה שנראה ליש) הוא יש האמיתי. ולכן הכריתת ברית וההתקשרות דהקב\"ה עם ישראל הוא בעיקר בהגוף דישראל, וכמבואר בשיחה הידועה<sup data-n=\"2439\">25</sup> השייכות דעצמות לגוף הגשמי דוקא.\n<b>וזהו</b> אמרו לפני מלכיות שתמליכוני עליכם<sup data-n=\"2440\">26</sup>, שעצמותו ית' בעט זיך כביכול ביי אַלע אידן און ביי יעדער אידן, שתמליכוני עליכם. דהגם אשר נמלך בנשמותיהן של צדיקים<sup data-n=\"2441\">27</sup>, שעלה לפניו ית' התענוג שיתענג כביכול בעבודת הנשמות<sup data-n=\"2442\">28</sup>, ותענוג זה הי' עוד לפני הבריאה כתורת הרב המגיד בלקוטי אמרים ובאור תורה בתחלתם ובראשיתם<sup data-n=\"2443\">29</sup>, אעפ\"כ הוא מבקש שתמליכוני עליכם, כי נמלך הוא בנשמותיהן של צדיקים, ותכלית הכוונה היא העבודה דנשמות בגופים, שעי\"ז נעשה תמליכוני עליכם, לעורר<sup data-n=\"2444\">30</sup> התגלות פנימיות מלכותו ית' מעצמותו ומהותו.\nד) <b>וזהו</b> לעברך בברית גו', שבכל שנה קודם ר\"ה צ\"ל כריתת ברית מחדש על קבלת התורה שהוא בדוגמת הברית שהי' לפני הכניסה לארץ ישראל בפעם הראשונה, מלבד הברית אשר כרת אתם בחורב<sup data-n=\"2445\">31</sup>, כי בעת הברית אשר כרת אתם בחורב היו ישראל צדיקים, ולאחרי הירידה (שע\"י החטא), הוצרך להיות לעברך בברית הוי' אלקיך, בחינת תשובה<sup data-n=\"2446\">32</sup>. וברית זה (דלעברך בברית) שבא לאחרי הירידה כנ\"ל, ירידה צורך עלי', הוא נעלה יותר מהברית אשר כרת אתם בחורב, כי \"לעברך בברית\" הוא<sup data-n=\"2447\">33</sup> מה שכורתי הברית עוברים בין הבתרים \"בתוך גוף אחד\" שהו\"ע ההתקשרות דהקב\"ה עם ישראל שנעשו חד ממש, ועד שגם הגוף דישראל הוא מתייחד עם עצמותו ית' (כנ\"ל), שמצד התקשרות זו נעשה בקשו פני את פניך הוי' אבקש<sup data-n=\"2448\">34</sup>[ובאופן שפני (דישראל) ופניך הוי' נעשו אחד], עבודת התשובה<sup data-n=\"2449\">35</sup> (שלמע' מעבודת הצדיקים). דענין התשובה הוא למעלה ממדידה והגבלה, למעלה מההגבלה דזמן שלכן תשובה היא בשעתא חדא וברגעא חדא<sup data-n=\"2450\">36</sup>, ולמעלה מההגבלה דמקום כולל גם ההגבלה דמקום רוחני שענין המקום ברוחניות הוא מעלה ומדריגה<sup data-n=\"2451\">37</sup>, שלכן אפילו כשהוא בדרגא הכי תחתונה (מצד החטאים כו'), מועלת תשובה. וזהו מה שממשיך בכתוב<sup data-n=\"2452\">38</sup> ושב ה' אלקיך את שבותך, והשיב לא נאמר אלא ושב<sup data-n=\"2453\">39</sup>, כי מצד הכריתת ברית דהקב\"ה עם ישראל שנעשו חד ממש, וגם מצד הגוף דישראל שהוא גוי קדוש ובתכלית הקדושה<sup data-n=\"2454\">40</sup>, הרי בכל מקום שישראל נמצא, גם אם יהי' נדחך בקצה השמים<sup data-n=\"2455\">41</sup>, נמצא שם עצמותו ומהותו ית', מכיון שהם חד ממש, ולכן לא נאמר והשיב אלא ושב.\nה) <b>וזהו</b> אתם נצבים היום כולכם גו', שכל ניצוצי נשמות (מראשיכם שבטיכם עד חוטב עציך ושואב מימיך) נצבים ומתעלים במקורם הראשון עד לפני הוי'&lt;11&gt; ועד שהם נעשים חד ממש עם (בחינת) לפני הוי' (כנ\"ל בענין לעברך בברית), ישראל ומלכא בלחודוהי<sup data-n=\"2456\">42</sup>, ועי\"ז הם גם נצבים (כפירוש הבעש\"ט<sup data-n=\"2457\">43</sup>) קיימים ועומדים היינו שזוכים בדין, ולא רק בנוגע לענינים רוחניים (משפט לאלקי יעקב<sup data-n=\"2458\">44</sup>) אלא גם בנוגע לענינים גשמיים (חק לישראל<sup data-n=\"2458\">44</sup>), ואדרבה עיקר הדין בר\"ה (ומה שזוכים בדין) הוא בנוגע לענינים גשמיים<sup data-n=\"2459\">45</sup>, שלכאו\"א מישראל יהי' כתיבה וחתימה טובה לשנה טובה ומתוקה בטוב הנראה והנגלה, בבני חיי ומזוני, ובכולם רויחי.\n**********",[["2414","*","הוגה בשעתו, ונתגלה ויצא לאור לקראת ש\"פ נצבים ה'תשנ\"ד."],["2415","1","פרשתנו (נצבים) כט, ט-יו\"ד."],["2416","2","ריש פרשתנו."],["2417","3","תוס' – מגילה לא, סע\"ב. רמב\"ם הל' תפלה פי\"ג ה\"ב. טושו\"ע או\"ח סתכ\"ח ס\"ד."],["2418","4","ראה רמ\"ז לזח\"ב לב, ב (הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380883\" data-slug=\"likkutei-torah\" data-id=\"4001380883\">לקו\"ת תבוא מא, ג</a>). וראה גם זח\"ג רלא, א. פענח רזא ס\"פ נצבים. \"היום יום\" כה אלול (נעתק גם בכתר שם טוב (הוצאת תשנ\"ט) בהוספות סי' מא)."],["2419","5","תפלת מוסף דר\"ה, מר\"ה כז, א."],["2420","6","לקו\"ת פרשתנו שם. וראה לקו\"ש ח\"ד ע' 1141 ואילך."],["2421","7","ברכת \"שים שלום\" בסיום וחותם שמו\"ע."],["2422","8","מטות פה, ד ואילך."],["2423","9","בתחלתו."],["2424","10","תבוא מא, ג. פרשתנו מז, סע\"א ואילך. ר\"ה נח, א-ב."],["2425","11","לקו\"ת ריש פרשתנו."],["2426","12","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370248\" data-slug=\"torah-or\" data-id=\"3901370248\">תו\"א וארא נה, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380174\" data-slug=\"likkutei-torah\" data-id=\"4001380174\">לקו\"ת תזריע כג, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380598\" data-slug=\"likkutei-torah\" data-id=\"4001380598\">בלק ע, א</a>. אמרי בינה שער הק\"ש פ\"ח. ספר המצות להצ\"צ שרש מצות התפלה פי\"ח (קכד, א-ב). סה\"מ תרנ\"ד ע' נו. ובכ\"מ."],["2427","13","סמ\"ק הובא בב\"י או\"ח סס\"א (ד\"ה כתב בסמ\"ק). שו\"ע (ואדה\"ז) או\"ח סס\"א ס\"ו. לקו\"ת תזריע שם. סהמ\"צ להצ\"צ שם."],["2428","14","להעיר משעהיוה\"א פי\"ב: שכל אות הקודמת כו' והשאר כו' נכללות באורה."],["2429","15","כדיוק הלשון (בלקו\"ת ריש פרשתנו – מד, סע\"א) \"רשות <i>היחיד ליחודו</i> ית'\", וכן לפנ\"ז \"להשראת <i>יחודו</i> ית'\". וראה המשך ר\"ה תש\"ב פ\"י [בפירוש הכתוב ויהי בישורון מלך בהתאסף ראשי עם יחד שבטי ישראל – הובא בלקו\"ת ריש פרשתנו לענין אתם נצבים היום כולכם גו']: שע\"י ההתאחדות בבחינת אחד נמשך בחינת יחיד (וראה שם בסוף הפרק)."],["2430","16","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370183\" data-slug=\"torah-or\" data-id=\"3901370183\">תו\"א מקץ מ, ג</a>. ובכ\"מ."],["2431","17","פרשתנו כט, יא."],["2432","18","פרשתנו שם מד, ריש ע\"ב."],["2433","19","ירמי' לד, יח (בשינוי לשון)."],["2434","20","ראה בארוכה המשך ר\"ה הנ\"ל פי\"ג. ובכ\"מ."],["2435","21","שה\"ש ה, א."],["2436","22","שהש\"ר עה\"פ. נתבאר בארוכה בד\"ה באתי לגני השי\"ת (סה\"מ תש\"י ע' 111 ואילך)."],["2437","23","ס\"כ (קל, סע\"א ואילך)."],["2438","24","לאדהאמ\"צ בשלח מג, ג. וראה גם ד\"ה ולקחתם לכם תרס\"א (סה\"מ תרס\"א ע' קצה ואילך). מצה זו עזר\"ת (תש\"ז) פ\"ב (סה\"מ עזר\"ת ע' קנ. תש\"ז ע' 238)."],["2439","25","סה\"ש תורת-שלום ע' 11-12. שם ע' 120 ואילך."],["2440","26","ר\"ה טז, א. שם לד, ב."],["2441","27","ב\"ר פ\"ח, ז. רות רבה רפ\"ב."],["2442","28","המשך ר\"ה תש\"ג פ\"ג (סה\"מ תש\"ג ריש ע' 9). ובכ\"מ."],["2443","29","וראה גם או\"ת (הוצאת קה\"ת) ב, ג ואילך."],["2444","30","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380898\" data-slug=\"likkutei-torah\" data-id=\"4001380898\">לקו\"ת</a> פרשתנו ד\"ה אתם נצבים רפ\"ה (מד, ד)."],["2445","31","לשון הכתוב תבוא כח, סט – לענין \"אלה דברי הברית גו'\" דפ' תבוא. וב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380883\" data-slug=\"likkutei-torah\" data-id=\"4001380883\">לקו\"ת תבוא (מא, ג</a>) שהו\"ע הכריתת ברית שקודם ר\"ה, ושם (מב, א) מקשר זה עם \"לעברך בברית גו'\" (דפרשתנו)."],["2446","32","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010098\" data-slug=\"or-hatorah-hb\" data-id=\"8159010098\">אוה\"ת פרשתנו ע' א'רו</a>."],["2447","33","ראה פרש\"י עה\"פ (פרשתנו כט, יא) שזהו פירוש <i>לעברך</i> בברית."],["2448","34","תהלים כז*, ח. וראה לקו\"ת פרשתנו מד, ב ואילך.\n*) <i>והוא פסוק במזמור </i>\"<i>לדוד ה' אורי וישעי</i>\"<i> שנוהגים לומר מר\"ח אלול עד הושענא רבה – סידור אדה\"ז אחר שיר של יום</i>.<i> ועוד</i>.<i> וראה לקמן ע' רפא הערה 1</i>.<i> לעיל ח\"א ע' רלה הערה 94</i>."],["2449","35","להעיר גם מלקו\"ת ד\"ה אתם נצבים ספ\"ב: כריתת ברית . . לעורר את האהבה וסלחת כו'."],["2450","36","זח\"א קכט, סע\"א."],["2451","37","רמב\"ם הל' יסוה\"ת פ\"ב ה\"ו. מו\"נ ח\"א פ\"ח (הובא בס' החקירה להצ\"צ עד, סע\"ב)."],["2452","38","פרשתנו ל, ג."],["2453","39","מגילה כט, א. וראה גם פרש\"י עה\"פ."],["2454","40","ראה גם שו\"ע אדה\"ז או\"ח מהדו\"ב סוס\"ד. <a class=\"ft-cite\" href=\"#/read/tanya/3401310054\" data-slug=\"tanya\" data-id=\"3401310054\">תניא פמ\"ט (סט, סע\"ב</a> ואילך)."],["2455","41","לשון הכתוב – פרשתנו שם, ד."],["2456","42","ראה זח\"ג לב, א."],["2457","43","\"היום יום\" שבהערה 4."],["2458","44","תהלים פא, ה. וראה סה\"מ ה'תש\"י ע' 15 (ובכ\"מ), ש\"חק לישראל\" קאי על שפע גשמי, ו\"משפט לאלקי יעקב\" על שפע רוחני."],["2459","45","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380956\" data-slug=\"likkutei-torah\" data-id=\"4001380956\">לקו\"ת ר\"ה נט, ב</a> (מהגהות מיימוניות לרמב\"ם הל' תשובה פ\"ג ה\"ג (אות א) בשם הרמב\"ן בשער הגמול)."]]],[1500390038,"<h3>בס\"ד. ליל ג' דסליחות, ה'תש\"כ<sup data-n=\"2460\">*</sup></h3>\n<b>לך</b> אמר לבי בקשו פני גו'<sup data-n=\"2461\">1</sup>, ומביא כ\"ק מו\"ח אדמו\"ר במאמרו ד\"ה זה<sup data-n=\"2462\">2</sup> פירוש רש\"י עה\"פ, דבלך שני פירושים. בשבילך בשליחותך ובמקומך. וממשיך בהמאמר, שגם בבקשו פני שני פירושים. שבקשו הוא בקשה ותחינה, ושבקשו הוא בקשה וחיפוש. ומבאר, דשני ענינים אלה (בקשה ותחינה, בקשה וחיפוש) הם בתפלה. דתפלה היא בקשה ותחינה, והבקשה היא שיצליח בעבודתו לחפש ולמצוא דרכי התיקון בכל עניניו. וזהו מ\"ש לך אמר לבי בקשו פני (לבי דוקא), כי שני הענינים דבקשו פני הם בתפלה (כנ\"ל), ותפלה היא עבודה שבלב<sup data-n=\"2463\">3</sup>. ומוסיף בהמאמר, דבעבודה שבלב שני ענינים. בתוך הלב ועם הלב. ויש לומר, דשני ענינים אלה הם בהתאם לשני הפירושים (דלעיל) בבקשו פני. דהבקשה ותחינה שבתפלה באה ע\"י העבודה בתוך הלב, שבכדי שהבקשה והתחינה שלו תהי' באמת, הוא ע\"י שמעורר את לבו, עבודה בהלב עצמו. והחיפוש שבתפלה (איך לתקן כל עניניו) הוא עבודה עם הלב. היינו, שהעבודה היא (לא בהלב, אלא) בכל עניניו, אלא שעבודה זו היא ע\"י הלב<sup data-n=\"2464\">4</sup>.\nב) <b>ולבאר</b> זה, מקדים בהמאמר מ\"ש<sup data-n=\"2465\">5</sup> ומבשרי אחזה אלוקה, דצריך להבין הרי העיקר הוא הנפש ולמה אומר <i>ומבשרי</i> אחזה. ומבאר, דבראי' ישנם שני אופנים, ראי' שכלית וראי' מוחשית. דראי' שכלית מתייחסת יותר אל הנפש, וראי' מוחשית מתייחסת יותר אל הגוף. וחילוק זה הוא גם בנוגע להדבר הנראה. דבכל דבר יש גוף ונפש. שגם בדברים גשמיים יש הנפש שבהם<sup data-n=\"2466\">6</sup>, וגם בדברים רוחניים יש הגוף שבהם. ולכן אומר <i>ומבשרי</i> אחזה אלוקה, כי הכוונה באחזה אלוקה היא לראי' מוחשית באלקות, דישנם עניני אלקות, כמו השגחה פרטית, שאפשר לראותם במוחש. וממשיך בהמאמר<sup data-n=\"2467\">7</sup> בפירוש הכתוב ומבשרי אחזה אלוקה, דכחות נפש האדםמשתלשלות מהספירות שלמעלה<sup data-n=\"2468\">8</sup> כמ\"ש<sup data-n=\"2469\">9</sup> נעשה אדם בצלמנו כדמותנו, ולכן, מכחות נפש האדם אפשר להבין הספירות שלמעלה.\n<b>וממשיך</b> בהמאמר<sup data-n=\"2470\">10</sup> (לאחרי שמבאר באריכות הענין דמבשרי אחזה אלוקה), שבכדי שתהי' התעוררות המדות שבלב, צריכה להיות הכנה לזה. דהגם שהתעוררות המדות שבלב היא ע\"י התבוננות, מ\"מ, בכדי שאור המוחין יאיר בלבו לעורר את המדות, צריך להיות הכנה לזה גם מצד הלב. וההכנה לזה היא המרירות שקודם התפלה. דע\"י שמתבונן בתכלית ירידת נשמתו למטה שהיא ירידה צורך עלי', שע\"י עבודתה בתומ\"צ תתעלה למדריגה נעלית יותר מכמו שהיתה קודם ירידתה, ואיך שהוא מתנהג בפועל, דלא זו בלבד שאינו עוסק בתומ\"צ כדבעי (שלכן העלי' דהנשמה שע\"י הירידה אינה בשלימות), הנה ע\"י מעשיו הבלתי רצויים הוא מוריד את נשמתו למטה עוד יותר, ובפרט כשמתבונן בהמשל דהאוחז ראשו של מלך כו'<sup data-n=\"2471\">11</sup>, יבוא למרירות גדולה. וע\"י מרירות זו נעשה החרישה בקרקע לבבו, שנעשה מוכן להתעוררות (ע\"י התבוננות) אמיתית במדות שבלב.\n<b>וממשיך</b> בהמאמר<sup data-n=\"2470\">10</sup>, דכ\"ז הוא גם בכל ימות השנה, ובפרט בחודש אלול שהוא זמן התגלות י\"ג מדות הרחמים<sup data-n=\"2472\">12</sup>, והגילוי די\"ג מדות הרחמים דחודש אלול הוא לכל, גם להרחוקים ביותר. וכהמשל דמלך בשדה<sup data-n=\"2473\">13</sup> שאז רשאים ויכולים<sup data-n=\"2474\">14</sup> כל מי שרוצה להקביל פניו (ולמסור לו את בקשותיהם), והוא מקבל את כולם בסבר פנים יפות ומראה פנים שוחקות לכולם. [ויש להוסיף, דהגם שהביאור (בהמאמר) בהמעלה דחודש אלול בא בהמשך לענין המרירות, דכיון שבאלול הוא הגילוי די\"ג מדות הרחמים גם להרחוקים לכן הוא זמן מסוגל ביותר לעשות חרישה בקרקע לבבו ע\"י המרירות, הגילוי די\"ג מדות הרחמים שבאלול צריך להוסיף גם בענין השמחה. דמכיון שבאלול מראה המלך פנים שוחקות לכולם, ה\"ז צריך לעורר (כמים הפנים לפנים<sup data-n=\"2475\">15</sup>) תוספות שמחה בעבודת המלך]. ומסיים בהמאמר, דהפירוש לך אמר לבי בשבילך ובשליחותך, הוא, שהלב הוא בשבילו ית' להשלים רצונו ית' לעשות את המטה דירה לו ית', והפירוש לך אמר לבי במקומך הוא ענין נקודת היהדות שישנה בכאו\"א מישראל שמקושרת בהעצמות.\nג) <b>ולהבין</b> הביאור בשני הפירושים בלך אמר לבי, והשייכות שלהם להענינים המבוארים בהמאמר [הענין דמבשרי אחזה אלוקה, ושבכדי שתהי'התעוררות מדות שבלב צריכה להיות הכנה לזה, וכו'] יש להקדים מ\"ש הרב המגיד<sup data-n=\"2476\">16</sup> בשם הבעש\"ט שבכל תיבה<sup data-n=\"2477\">17</sup> מתיבות התפלה ישנם ג' בחינות, עולמות נשמות ואלקות. ועפ\"ז יש לומר גם בנוגע לבקשו פני, שהעבודה דבקשו פני היא בתפלה, שהיא בג' בחינות אלו. דבתיבת פני (שבפסוק זה), ג' פירושים. דלפירוש רש\"י בלך אמר לבי, שהלב אומר בשליחותו או במקומו של הקב\"ה, פני קאי על פניו ית', פנימיות דאלקות. ואדמו\"ר הזקן מפרש<sup data-n=\"2478\">18</sup>, דזה שהלב אומר בקשו פני קאי על הפנימיות שלו, פנימיות הלב, הפנימיות דנשמות. ועוד פירוש בבקשו פני<sup data-n=\"2479\">19</sup>, שפני קאי על אצילות, כי ד' המדריגות פנים ואחור ימין ושמאל הם ד' העולמות אבי\"ע [אחור – עשי', שמאל – יצירה, ימין – בריאה, ופנים – אצילות], פנימיות העולמות.\nד) <b>והנה</b> בהענין דפני, בכל אחת מג' בחינות אלה, יש ב' מדריגות, בכללות. פנימיות שיש לה שייכות להחיצוניות, ופנימיות ממש שמובדלת מהחיצוניות. דבענין העולמות הוא אצילות ולמעלה מאצילות. וכמ\"ש הצ\"צ<sup data-n=\"2480\">20</sup> בפירוש הכתוב בקשו פני את פניך הוי' אבקש, דבקשו פני הוא להמשיך החכמה, אצילות, ואת פניך הוי' אבקש הוא להמשיך הפנים של הוי', האורות דאריך ועתיק. דהחילוק בין אצילות ולמעלה מאצילות הוא, דאצילות הוא בכלל ד' העולמות אלא שהוא ה\"פנים\" שלהם, פנימיות ששייך לחיצוניות, ולמעלה מאצילות הוא למעלה מעולמות, פנימיות שמובדל מחיצוניות. ועד\"ז הוא בפנימיות הלב, פנים דהנשמות, שיש בו דוגמת ב' מדריגות אלה. וכמבואר בלקו\"ת ד\"ה כי תצא למלחמה על אויביך<sup data-n=\"2481\">21</sup>, דבפנימיות הלב יש שתי מדריגות, הארת נקודת הלב ועצמות נקודת הלב, דשתי המדריגות הם מאצילות [דזהו החילוק שבין חיצוניות הלב לפנימיות הלב, שחיצוניות הלב הוא מבי\"ע ופנימיות הלב הוא מאצילות. וזהו מה שחיצוניות הלב הוא ע\"פ טעם ודעת ופנימיות הלב הוא למעלה מטעם ודעת, כי בבריאה הוא ענין ההשגה, אימא מקננא בכורסיא<sup data-n=\"2482\">22</sup>, ואצילות בכלל הוא חכמה, דאמיתית ענין החכמה הוא למעלה מהשכל], אלא שהארת נקודת הלב היא מאצילות שבפנימיות בי\"ע ועצמות נקודת הלב היא מאצילות עצמו. וכמו שלמעלה, בחינת האצילות שבבי\"ע היא רק הארת האצילות, עד\"ז הוא בנשמת האדם, שבחינה זו היא רק <i>הארת</i> נקודתהלב. ונמצא, שהארת נקודת הלב הוא מה שמאיר מפנימיות הלב לחיצוניות הלב (ע\"ד הארת האצילות בבי\"ע), ועצמות נקודת הלב הוא הפנימיות כמו שהוא במקומו.\n<b>ועד\"ז</b> הוא גם בהפנימיות דאלקות, שיש בו דוגמת ב' מדריגות הנ\"ל. ויובן זה ע\"פ מ\"ש בתניא<sup data-n=\"2483\">23</sup> בענין ב' השמות הוי' ואלקים, דאלקים הוא חיצוניות והוי' הוא פנימיות. [ויש לקשר זה עם המבואר בלקו\"ת שם<sup data-n=\"2484\">24</sup>, דהאהבה שבחיצוניות הלב באה ע\"י ההתבוננות באור הממלא, והאהבה (רעו\"ד שלמעלה מטו\"ד) שבפנימיות הלב נמשכת מאור הסובב, כי הוי' ואלקים הם (בד\"כ) סובב וממלא<sup data-n=\"2485\">25</sup>. ולכן, אור הממלא (אלקים), חיצוניות<sup data-n=\"2486\">26</sup>, הוא שרש להאהבה דחיצוניות הלב, ואור הסובב (הוי'), פנימיות, הוא שרש להאהבה דפנימיות הלב]. ועפ\"ז יש לומר, דפירוש פניך הוי' הוא העצם דהוי' שלמעלה מהתלבשות באלקים. דזה שהוי' (בכלל) הוא פנימיות, הוא גם לאחרי שמתלבש באלקים. ופניך הוי' הוא העצם דהוי' שלמעלה מהתלבשות באלקים.\nה) <b>ויש</b> לומר דבחינת פניך הוי', הפנימיות דהוי', הוא למעלה גם מהוי' שלמעלה מהתלבשות באלקים. [וע\"ד המבואר במקום אחר<sup data-n=\"2487\">27</sup> בפירוש הכתוב<sup data-n=\"2488\">28</sup> ואמת הוי' לעולם, דגם שם הוי' שלמעלה מהתלבשות באלקים הוא הוי' (סתם), ואמת הוי' (האמיתית דהוי') הוא עצמות אוא\"ס שלמעלה משם הוי', למעלה גם מהוי' שלמעלה מהתלבשות באלקים]. ויובן זה ע\"פ הידוע<sup data-n=\"2489\">29</sup> דהפנימיות של כל דבר הוא הדבר עצמו, וזה שהוא מקור לאיזה ענין אחר, הוא החיצוניות שלו. ועפ\"ז יש לבאר החילוק בין שתי הדרגות בהפנימיות שלמעלה (הוי' ואוא\"ס שלמעלה מהוי'), דהוי' הוא לשון מהווה<sup data-n=\"2490\">30</sup>, אלא שההתהוות שמשם הוי' היא באופן דבדרך ממילא. וכידוע<sup data-n=\"2491\">31</sup> דההתהוות שמשם אלקים היא בדרך התלבשות (בראשית ברא אלקים<sup data-n=\"2492\">32</sup>), וההתהוות משם הוי' היא באופן דבדרך ממילא (יהללו את שם הוי' כי הוא צוה ונבראו<sup data-n=\"2493\">33</sup>). ולכן, בכללות, שם הוי' הוא פנימיות, כי זה שההתהוות ממנו היא באופן דבדרך ממילא, מורה על זה שהוא מופלא מענין ההתהוות<sup data-n=\"2494\">34</sup> (ואינו מקור ממש). אבל בפרטיות, זה שמשםהוי' נעשה ההתהוות, הוא מפני שהוא מקור לההתהוות<sup data-n=\"2495\">35</sup>, ולכן, עיקר ענין הפנימיות הוא בעצמות אוא\"ס שלמעלה מהוי'.\n<b>ועפ\"ז</b> יש לומר שעד\"ז הוא בשתי המדריגות דפנימיות הלב, דזה שהארת נקודת הלב אינה בבחינת פנימיות כ\"כ כהפנימיות דעצמות נקודת הלב הוא גם כמו שהיא בעצמותה, לפני שהיא מאירה בחיצוניות הלב<sup data-n=\"2496\">36</sup>. דמזה שממנה נמשך להאיר בחיצוניות הלב, מוכח, שאינה אמיתית ענין הפנימיות. ואמיתית ענין הפנימיות הוא בעצמות נקודת הלב שהיא מובדלת מחיצוניות הלב. וע\"ד שנת\"ל (סוף סעיף ד) בענין פניך הוי', שהוא למעלה גם מהוי' שלמעלה מהתלבשות באלקים.\nו) <b>ויש</b> להוסיף ביאור בהשייכות דשתי הדרגות שבפנימיות הלב (הארת נקודת הלב ועצמות נקודת הלב) לשתי הדרגות בהפנימיות שלמעלה (הוי' ואוא\"ס שלמעלה מהוי'), ע\"פ המבואר בלקו\"ת שם בפירוש הכתוב<sup data-n=\"2497\">37</sup> כי תצא למלחמה על אויביך, דכי תצא למלחמה קאי על מלחמת נפש האלקית עם נפש הבהמית<sup data-n=\"2498\">38</sup>, דמלחמה זו היא בכחות הנשמה המלובשים בגוף (שכל ומדות), משא\"כ פנימיות הלב (הארת נקודת הלב) הוא על אויביך, למעלה מאויביך, שאין להאויב שליטה ואחיזה שם. וע\"י הגילוי דהארת נקודת הלב, על אויביך, עי\"ז ושבית שביו<sup data-n=\"2497\">37</sup>, שנהפך הרע לטוב. אלא שהפיכת הרע לטוב שע\"י גילוי הארת נקודת הלב הוא רק בהלבושים מחשבה דיבור ומעשה, ובכדי להפוך המדות מרע לטוב הוא ע\"י גילוי עצמות נקודת הלב<sup data-n=\"2499\">39</sup>. וזהו וראית בשבי' אשת יפת תואר<sup data-n=\"2500\">40</sup>, אשת יפת תואר היא הנשמה המלובשת בגוף, ובכדי להוציא אותה [את עצמותה ומהותה, היינו השכל והמדות שלה] מהשבי', הוא ע\"י גילוי עצמות נקודת הלב<sup data-n=\"2501\">41</sup>.<b>ויש</b> לומר, דזה שבנוגע להפיכת הלבושים (שע\"י גילוי הארת נקודת הלב) כתיב <i>ושבית</i> שביו, ובנוגע להפיכת המדות (שע\"י גילוי עצמות נקודת הלב) כתיב <i>וראית</i> בשבי' וגו', הוא, כי לגבי הארת נקודת הלב ישנו מנגד. וזהו שבנוגע לדרגא זו כתיב על אויביך, כי לגבי הארת נקודת הלב ישנו מציאות האויב, אלא שהוא באופן דעל אויביך, למעלה מאויביך, שאין להאויב שליטה ואחיזה. ולכן, הוצאת הענינים דקדושה (מחשבה דיבור ומעשה דהנשמה) מהשבי', שע\"י גילוי הארת נקודת הלב, היא באופן של פעולה, <i>ושבית</i> שביו [אלא שהפעולה אינה באופן דמלחמה, כי לגבי דרגא זו אין להאויב שליטה]. משא\"כ עצמות נקודת הלב הוא [ע\"ד] בחינת היחידה<sup data-n=\"2502\">42</sup> שאין כנגדה לעומת זה, בבואה דבבואה לית להו<sup data-n=\"2503\">43</sup>. ולכן הביטול דלעו\"ז שע\"י גילוי עצמות נקודת הלב הוא (לא שע\"י גילוי עצמות נקודת הלב <i>נעשה</i> ביטול הלעו\"ז, כי אם) שע\"י גילוי זה, אין מקום מלכתחילה להמציאות דלעו\"ז<sup data-n=\"2504\">44</sup>. וזהו <i>וראית</i> בשבי' אשת יפת תואר, דכאשר ישנו הגילוי דעצמות נקודת הלב, אזי הדרגא דהנשמה (אשת יפת תואר) שהיתה תחלה בשבי', מתגלית מעצמה, <i>וראית</i> (ואין צריך <i>להוציא</i> אותה מהשבי').\n<b>ועד\"ז</b> הוא למעלה, דבשם אלקים אפשר להיות (ע\"י ריבוי צמצומים) יניקה לחיצונים, ועד לאלקים אחרים<sup data-n=\"2505\">45</sup>. וע\"פ המבואר בכ\"מ<sup data-n=\"2506\">46</sup> דשם אלקים הוא לא רק המגן ונרתק שמעלים ומסתיר על האור דשם הוי', אלא שגם האור דשם הוי' כמו שנמשך ומתצמצם ע\"י שם אלקים להיות מקור לנבראים, שבכללות הוא אור הממלא, נקרא אלקים, יש לומר שעד\"ז הוא באור הממלא. דמכיון שההתהוות משם אלקים (אור הממלא) היא בדרך התלבשות, הנבראים שמתהווים ממנו הם תופסים מקום, והביטול שלהם הוא רק ביטול היש<sup data-n=\"2507\">47</sup>, ולכן אפשר להשתלשל מזה ישות ממש<sup data-n=\"2508\">48</sup>, ועד להישות דע\"ז (אלקים אחרים). ובכדי שלא יהי' נתינת מקום לישות ולעו\"ז, הוא דוקא ע\"י הגילוי דשם הוי' (אור הסובב), שההתהוות ממנו היא באופן דבדרך ממילא, והנבראים אינם תופסים מקום לגבי', ביטול במציאות<sup data-n=\"2507\">47</sup>. וע\"פ המבואר לעיל (סעיף ה) שגם שם הוי' הוא מקור להתהוות, בהכרח שגם לגבי שם הוי' יש איזה תפיסת מקום להנבראים<sup data-n=\"2509\">49</sup>, ואמיתית הביטול הוא דוקא לגבי עצמותאוא\"ס שלמעלה מהוי' שאינו בגדר מקור לעולמות. ועפ\"ז יש לומר שבכדי לשלול <i>בתכלית</i> שלא תהי' נתינת מקום לישות, הוא דוקא ע\"י הגילוי דעצמות אוא\"ס שלמעלה מהוי'. וזהו מ\"ש<sup data-n=\"2510\">50</sup> לא יהי' לך אלקים אחרים על פני, שבכדי שלא יהי' שום נתינת מקום לאלקים אחרים הוא ע\"י על פני, דאמיתית הענין דפני הוא עצמות אוא\"ס שלמעלה מהוי'.\nז) <b>ויש</b> לומר, דשני הפירושים בלך אמר לבי בקשו פני (שלך הוא בשבילך ובשליחותך, ושלך הוא במקומך), וגם שני הפירושים (בהמאמר) בבקשו (בקשה ותחינה, בקשה וחיפוש), הם בהתאם לשתי הדרגות בפני. דבהפנימיות דשם הוי' (שהוא בחי' פנימיות לגבי שם אלקים), שדוגמתו באדם הוא הארת נקודת הלב, פירוש לך הוא בשבילך ובשליחותך. היינו שהלב הוא שלוחו של הקב\"ה, דענינו של שליח הוא ששולחים אותו <i>לעשות</i> איזה דבר. והשליחות שבדרגא זו שבפנימיות הלב הוא להאיר בחיצוניות הלב כדי לנצח המלחמה עם הנפש הבהמית, דעיקר הנצחון (שע\"י גילוי דרגא זו) הוא בהלבושים מחשבה דיבור ומעשה, אלא שבכדי שהמחשבה דיבור ומעשה יהיו בשלימות הוא ע\"י המדות שבלב<sup data-n=\"2511\">51</sup>, עבודה <i>עם</i> הלב. ועפ\"ז פירוש בקשו פני הוא בקשה וחיפוש, לחפש בכל עניניו שיהיו בהתאם לבחי' פני (פני הוי'). ובהפנימיות דאוא\"ס שלמעלה מהוי', שדוגמתו באדם היא עצמות נקודת הלב, פירוש לך הוא במקומך, וכמובא לעיל (סוף סעיף ב) מהמאמר שהוא נקודת היהדות שבכל אחד מישראל שמקושרת בהעצמות (במקומך). דבדרגא זו אין שייך ענין השליחות, כי נקודת היהדות אינה אמצעי לענין אחר (מילוי השליחות), והתכלית הוא בה עצמה<sup data-n=\"2512\">52</sup>. והעבודה בנוגע לדרגא זו היא – עבודה בהלב עצמו, שיהי' בגילוי. דפנימיות הלב כמו שהוא מצד עצמו הוא בהעלם<sup data-n=\"2513\">53</sup>, והעבודה בו היא לעורר אותו שיהי' בגילוי. ועפ\"ז פירוש בקשו פני הוא בקשה ותחינה, דבקשה ותחינה היא (כהלשון בהמאמר) בהתעוררות גדולה.\nח) <b>והנה</b> מבואר במק\"א<sup data-n=\"2514\">54</sup>, שבהעלי' דהנשמה שע\"י ירידתה למטה, שני ענינים. שע\"י שגם בהיותה מלובשת בגוף ונה\"ב היא עובדת את ה', מתגלה תוקף ההתקשרות שלה עם הקב\"ה, שגם ההעלם וההסתר דהגוף ונה\"ב אינו יכול לעשות גרעון בההתקשרות שלה. ושע\"י עבודתה למטה נעשה ענין חדש, הבירור והזיכוך דהגוף ונה\"ב וחלקו בעולם. וכיון שענין זה (הבירור והזיכוך דהגוף וכו')הוא התחדשות (ולא גילוי ההעלם), הוא נעלה יותר מגילוי תוקף ההתקשרות דהנשמה. וע\"פ הידוע<sup data-n=\"2515\">55</sup> שבירור וזיכוך הגוף ונה\"ב (שבשביל זה ירדה הנשמה למטה<sup data-n=\"2516\">56</sup>) הוא דוקא ע\"י אהבה ויראה שבהתגלות הלב, חיצוניות הלב, יש לומר, שיש יתרון בהשליחות דהארת נקודת הלב לחיצוניות הלב, על העבודה דגילוי נקודת היהדות.\nט) <b>ויש</b> לומר, דזהו שמבאר בהמאמר מ\"ש מבשרי אחזה אלוקה, מבשרי דוקא, שהכוונה בזה היא לראי' מוחשית (באלקות) שמתייחסת להגוף, כי תכלית הכוונה דירידת הנשמה למטה הוא (לא שעניני הנשמה יהיו בגילוי בהיותה מלובשת בגוף, כי אם) <i>שהגוף</i> יראה אלקות. [ולהעיר שיש עוד פירוש במבשרי אחזה אלוקה, שבהבשר עצמו רואים את האלקות שבו. וכתורת אדמו\"ר הזקן<sup data-n=\"2517\">57</sup> עה\"פ מבשרי אחזה אלוקה שצריך שייערין דעם בשר אַז מי זאָל דערזעהען געטליכקייט. דמזה שאומר שצריך שייערין דעם בשר (הסרת הדברים המכסים) מובן שעי\"ז רואים האלקות שבהבשר עצמו. וכמובן גם ממאמר אדמו\"ר (מהורש\"ב) נ\"ע<sup data-n=\"2518\">58</sup> עה\"פ מבשרי אחזה אלוקה, קוק ניט וואָס ער איז אַ גולם, דעם גולם האָט מהוה גיווען עצמות א\"ס ב\"ה, דהוא לבדו בכחו ויכלתו לברוא יש מאין ואפס המוחלט<sup data-n=\"2519\">59</sup>. ויש לומר, דזה שבהמאמר מבאר דפירוש מבשרי אחזה אלוקה הוא ראי' מוחשית, אף שראיית האלקות שבהבשר עצמו הוא לכאורה ענין נעלה יותר (ובפרט לפירוש אדמו\"ר נ\"ע שקאי על כח העצמות שבהגוף), הוא, כי ראיית האלקות שבהבשר (כח העצמות שבו) היא ראי' שכלית שמתייחסת להנפש, ותכלית הכוונה דירידת הנשמה למטה הוא <i>שהגוף</i> יראה אלקות].\nיו\"ד) <b>והנה</b> ידוע<sup data-n=\"2520\">60</sup>, דכמו שירידת הנשמה למטה היא לצורך עלי', כמו\"כ הוא גם בנוגע לירידת האור האלקי להוות ולהחיות את הנבראים, שהיא ירידה צורך עלי'. ועפ\"ז יש לומר, שע\"י ששם הוי' יורד ומתלבש בשם אלקים (בכדי להוות ולהחיות את הנבראים), נעשה עלי' בהאור, למעלה יותר גם מכמו שהוא בשרשו באוא\"ס שלמעלה מהוי'<sup data-n=\"2521\">61</sup>. והעלי' היא, שנעשה<sup data-n=\"2522\">62</sup> בו ענין חדש<sup data-n=\"2523\">63</sup> – גילוי אלקות בעוה\"ז הגשמי. וכמובא לעיל (סעיף ב) מהמאמר, דישנם עניני אלקות, כמו השגחה פרטית, שהם בגילוי ממש, עד שאפשר לראותם במוחש. ויש לומר, דזהו מ\"ש בהמאמר דזה שראי' מוחשית מתייחסת להגוף הוא הן בנוגע להאדם הרואה והן בנוגע להדבר הנראה, שהיתרון בהפנימיות השייכת לחיצוניות וירידתה בחיצוניות הוא הן בנוגע להאדם, <i>שהגוף</i> רואה אלקות (כנ\"ל סעיף ט), והן בנוגע להאור שלמעלה, שהגילוי שלו הוא בעוה\"ז הגשמי.יא) <b>והנה</b> עד\"ז הוא בעבודת האדם, שעל ידי ירידת המוחין [העליון שבאדם<sup data-n=\"2524\">64</sup>, דטבע המוחין הוא עלי' למעלה] בהמדות [התחתון שבאדם<sup data-n=\"2524\">64</sup>, דטבע המדות הוא ירידה למטה], נעשה עלי' בהמוחין. ועיקר העלי' הוא לא זה שאור השכל מאיר גם בלב, אלא שעי\"ז נעשה ענין חדש – התעוררות <i>המדות</i>. ויש לומר, שזהו הטעם על זה שבכדי שתהי' התעוררות המדות שבלב צריכה להיות הכנה גם מצד הלב, כי <i>עיקר</i> החידוש שבהתעוררות המדות הוא כשההתעוררות היא (גם) מצד ענין המדות.\n<b>ויש</b> לומר, שעד\"ז הוא בנוגע למלך בשדה (אלול), דהגם שזוהי ירידה לגבי כמו שהוא בהיכל מלכותו (ר\"ה ויוהכ\"פ), דבהיותו בהיכל מלכותו הוא בכתר מלכות ולבושי מלכות משא\"כ בהיותו בשדה, הנה עי\"ז נעשה עלי' כביכול בהמלך<sup data-n=\"2525\">65</sup>, כי ע\"י ירידתו לשדה נעשה ענין חדש, שגם הרחוקים ביותר באים להקביל את פניו. אלא שאעפ\"כ, מכיון שבענין הגילויים, זה שנמצא בשדה הוא ירידה לגבי כמו שהוא בהיכל מלכותו, צריכה להיות העבודה בשדה באופן דללכת (אח\"כ) אחרי המלך להיכל מלכותו<sup data-n=\"2526\">66</sup>, וכמ\"ש בהמאמר<sup data-n=\"2527\">67</sup> שהעבודה דאלול היא הקדמה להעבודה דר\"ה ויוהכ\"פ. וזהו גם הקשר דשני הפירושים<sup data-n=\"2528\">68</sup> בלך אמר לבי בקשו פני, שהעבודה דלך אמר לבי להפירוש שלך הוא בשבילך בשליחותך, להשלים רצונו ית' לעשות את המטה דירה לו ית', צריכה להיות באופן שעי\"ז יגיעו להפירוש שלך הוא במקומך, גילוי נקודת היהדות שמקושרת בהעצמות.\nיב) <b>וממשיך</b> בהמאמר (בסיום וחותם המאמר), שע\"י התעוררות נקודת הלב נעשה כלי טהורה לקבל השפע ברכה על כל השנה. ויש לומר, שבזה ישנם ב' המעלות, המעלה דלך בשליחותך והמעלה דלך במקומך. דכאשר המשכת השפע הוא ע\"פ סדר ההשתלשלות, מעיינים בדינו אם הוא ראוי לזה, וישנם מקטריגים שמקטרגים ואומרים שאינו ראוי לזה. ויש לומר, דענין זה הוא גם כשההמשכה היא משם הוי' (כיון שגם שם הוי' הוא מקור להתהוות, כנ\"ל סעיף ה), כמ\"ש<sup data-n=\"2529\">69</sup> ויבואו בני האלקים להתייצב על הוי'. וזה שנמשך שפע ברכה (בריבוי מופלג) הוא לפי שע\"י גילוי עצמות נקודת הלב ההמשכה היא מאוא\"ס שלמעלה מהוי', ואין שייך שם הקטרוג דבני האלקים (וכנ\"ל סוף סעיף ו בפירוש הכתוב לא יהי' לך אלקים אחרים על פני), ויתירה מזו, שאין שם גם המדידות וההגבלות דשם אלקים (דקדושה), ולכן השפע שנמשך משם הוא בריבוי מופלג. וזה שהמשכת השפע הוא בענינים גשמיים, ומכש\"כ זה שהמשכת השפע הוא לא רק מצד למעלהאלא (כנ\"ל מהמאמר) שהאדם נעשה כלי מתאימה לקבל השפע, הוא לפי שע\"י העבודה בהארת נקודת הלב וחיצוניות הלב לעשות את <i>המטה</i> דירה לו ית', נרגש מעלת הגשמיות (כנ\"ל סעיף י בענין <i>מבשרי</i> אחזה אלוקה) ומעלתן של ישראל העושים את הדירה.\n<b>ומכיון</b> שבהעבודה דאלול ישנם שני הענינים, שהעבודה (עצמה) היא בשדה ובאופן דללכת אחרי המלך להיכל מלכותו (כנ\"ל סעיף יא), לכן, גם בהמשכת השפע שני הענינים, שנמשך רב טוב (במלופם<sup data-n=\"2530\">70</sup>) שלמעלה ממדידה והגבלה, וזה בא בטוב הנראה והנגלה (גם) בענינים הגשמיים, לשנה טובה ומתוקה, בבני חיי ומזוני כפשוטם, ובכולם – רויחי.\n**********<i>הוספות</i><i>עמוד ריק</i>",[["2460","*","יצא לאור ב<b>קונטרס ג' דסליחות – תשמ\"ט</b>, \"לקראת ג' דסליחות* . . <i>מוצש\"ק כ\"ג אלול ה'תשמ\"ט</i>\"."],["2461","1","תהלים כז, ח. – והוא פסוק במזמור \"לדוד ה' אורי וישעי\" שנוהגים לומר מר\"ח אלול עד הושענא רבה – סידור אדה\"ז אחר שיר של יום. ועוד. – נסמנו לעיל ח\"א ע' רלה הערה 94. ובמאמרי אדהאמ\"צ דברים ח\"ב ע' תקו: שאו' לדוד ה' אורי . . והעיקר הוא בפסוק לך אמר לבי בקשו פני כו'."],["2462","2","דליל ג' לפני ערב ר\"ה ה'תש\"א – נדפס בסה\"מ ה'ש\"ת ע' 163 ואילך. ה'שי\"ת ע' 281 ואילך (ושם הכותרת: ג' דסליחות)."],["2463","3","תענית ב, א. רמב\"ם הל' תפלה בתחלתו. רבינו יונה לאבות פ\"א מ\"ב."],["2464","4","ראה סה\"מ תרפ\"ח ע' קד, דפירוש עבודה <i>עם</i> הלב הוא כי התפלה צריכה גם לפעול בכל היום במחשבה דיבור ומעשה, וזהו <i>ע\"י</i> הלב."],["2465","5","איוב יט, כו."],["2466","6","שעהיוה\"א פ\"א, מהאריז\"ל. וראה ע\"ח שער לט (שער מ\"ן ומ\"ד) פ\"ג. שער נ (שער קיצור אבי\"ע)."],["2467","7","פ\"ב.\n*) <i>ראה סה\"מ ה'תש\"ה ע' 266</i>."],["2468","8","ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא רפ\"ג</a>."],["2469","9","בראשית א, כו."],["2470","10","פ\"ד."],["2471","11","<a class=\"ft-cite\" href=\"#/read/tanya/3401310029\" data-slug=\"tanya\" data-id=\"3401310029\">תניא ספכ\"ד</a>."],["2472","12","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380844\" data-slug=\"likkutei-torah\" data-id=\"4001380844\">לקו\"ת</a> פ' ראה ד\"ה אני לדודי הא' ס\"א (לב, א). וראה מאמרי אדהאמ\"צ דברים ח\"ב ס\"ע תכב ואילך, ובהנסמן שם בהערה ד\"ה הנזכר בספרי הקבלה."],["2473","13","לקו\"ת שם (לב, ב)."],["2474","14","בלקו\"ת שם \"רשאין\". ובהמאמר מוסיף \"רשאים ויכולים\"."],["2475","15","משלי כז, יט."],["2476","16","או\"ת להה\"מ (הוצאת קה\"ת) ז, ב (בהוצאת קה\"ת ה'תש\"מ ואילך – סי' יח). ועיין ג\"כ שם ז, סע\"א (סי' יז). הובא ג\"כ בצוואת הריב\"ש (הוצאת קה\"ת) סי' עה (יב, א-ב). הובא ונתבאר ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560295\" data-slug=\"or-hatorah-hb\" data-id=\"8316560295\">אוה\"ת נח כרך ג תריד, א</a>. וראה ג\"כ אגה\"ק המפורסמת דהבעש\"ט שנדפסה בריש ספר כתר שם טוב. ועיין ג\"כ בהנעתק בס' בעש\"ט עה\"ת ח\"א פ' נח עמוד התפלה בהערה לאות טו."],["2477","17","כ\"ה באוה\"ת שם. ובאו\"ת וצוואת הריב\"ש שם \"בכל אות\"."],["2478","18","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380896\" data-slug=\"likkutei-torah\" data-id=\"4001380896\">לקו\"ת נצבים מד, ב</a> ואילך. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380862\" data-slug=\"likkutei-torah\" data-id=\"4001380862\">לקו\"ת תצא</a> (המובא לקמן בפנים) לו, ב. וראה מאמרי אדהאמ\"צ דברים ח\"ב ע' תפט. שם ע' תצב. תקז."],["2479","19","אוה\"ת לתהלים (יהל אור) עה\"פ (כז, ח) אות א' (ע' קד), ע\"פ רמ\"ז לזח\"ג צג, ב."],["2480","20","אוה\"ת שם."],["2481","21","תצא לו, א. וראה ג\"כ מאמרי אדהאמ\"צ שם."],["2482","22","<a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תיקו\"ז ת\"ו (כג, א</a>). עץ חיים שער מז (שער סדר אבי\"ע) פ\"ג. שער מב (שער דרושי (כללות) אבי\"ע) פי\"ג. תניא פל\"ט (נב, א)."],["2483","23","אגה\"ת פ\"ד (צד, א)."],["2484","24","לה, ד."],["2485","25","ראה לקמן הערה 46."],["2486","26","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380897\" data-slug=\"likkutei-torah\" data-id=\"4001380897\">לקו\"ת נצבים מד, ג</a>, שההתבוננות בגדולתו ית' שממנה באה האהבה דחיצוניות הלב היא בבחי' \"<i>אחרי</i> הוי'\"."],["2487","27","המשך תרס\"ו ע' רכד."],["2488","28","תהלים קיז, ב."],["2489","29","ראה סה\"מ עת\"ר ע' ו ואילך. ולהעיר גם מאגה\"ק סי\"ט (קכח, א) \"אחוריים שבספירות הן מדריגות החיצונות כו' שיוכלו לירד ולהתפשט למטה\"."],["2490","30","שעהיוה\"א רפ\"ד. וראה גם זח\"ג רנז, סע\"ב (ברע\"מ). פרדס שער א (שער עשר ולא תשע) פ\"ט."],["2491","31","המשך תרס\"ו שם. סה\"מ תרע\"ח ע' שפ. קונטרסים ח\"א קצג, ב ואילך."],["2492","32","בראשית א, א."],["2493","33","תהלים קמח, ה."],["2494","34","סה\"מ קונטרסים שם קצד, רע\"א. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381187\" data-slug=\"likkutei-torah\" data-id=\"4001381187\">לקו\"ת שה\"ש יד, ג</a>: צוה ונבראו ממילא, שאין להם ערך ויחוס כלל אליו ית'."],["2495","35","המשך תרס\"ו שבהערה 27. ולהעיר ממ\"ש \"אתה הוא עד שלא נברא העולם ואתה הוא משנברא העולם\", דלכאורה, מכיון שבמאמר זה עצמו הלשון הוא \"נברא העולם\", נברא בדרך ממילא (כמבואר בארוכה ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381161\" data-slug=\"likkutei-torah\" data-id=\"4001381161\">לקו\"ת</a> שבהערה הקודמת), מהו החידוש בזה שהבריאה אינה פועלת שינוי בו ית'*? והביאור בזה, כי גם פעולה הבאה בדרך ממילא מורה שהדבר שממנו באה הפעולה הוא בגדר מקור להפעולה (שלכן באה ממנו פעולה זו דוקא), דפעולה שבאה מ\"מקור\" (גם כשהיא באופן דבדרך ממילא) עושה שינוי (בדקות עכ\"פ) בו, ובזה <i>מחדש</i> \"אתה הוא עד שלא נברא העולם ואתה הוא משנברא העולם\" בשוה <i>ממש</i>. והטעם על זה הוא, כי הבריאה (גם הבריאה באופן דבדרך ממילא) היא רק מבחינת שמו, הארה בלבד (לקו\"ת שה\"ש ח, א. ובכ\"מ)."],["2496","36","להעיר, שבנוגע להארת נקודת הלב מבואר ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380860\" data-slug=\"likkutei-torah\" data-id=\"4001380860\">לקו\"ת (תצא לה, ד</a>) ששרשה הוא מאור הסובב, ובנוגע לעצמות נקודת הלב מבואר שם (לו, ב) ששרשה הוא בבחינת \"פניך הוי'\" שנמשך ע\"י תומ\"צ. ומזה משמע שהחילוק שבין שתי הבחינות הוא גם בעצם מהותם."],["2497","37","תצא כא, י."],["2498","38","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380859\" data-slug=\"likkutei-torah\" data-id=\"4001380859\">לקו\"ת שם לה, ג</a>."],["2499","39","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380861\" data-slug=\"likkutei-torah\" data-id=\"4001380861\">לקו\"ת שם לו, א</a>."],["2500","40","תצא כא, יא."],["2501","41","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380862\" data-slug=\"likkutei-torah\" data-id=\"4001380862\">לקו\"ת שם לו, ב</a>.\n*) <i>ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310025\" data-slug=\"tanya\" data-id=\"3401310025\">תניא רפ\"כ (כה</i>,<i> סע\"ב</a> ואילך)</i>,<i> דפירוש </i>\"<i>אתה הוא עד שלא נברא העולם ואתה הוא משנברא העולם</i>\"<i> הוא</i>,<i> שהבריאה אינה פועלת </i>\"<i>שום שינוי </i><b>באחדותו</b><i> ית'</i>\".<i> אבל ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380212\" data-slug=\"likkutei-torah\" data-id=\"4001380212\">לקו\"ת אמור (לא</i>,<i> ג</a>)</i>,<i> שאינו </i><b>נתפס</b><i> בזה</i>.<i> וכ\"מ ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381161\" data-slug=\"likkutei-torah\" data-id=\"4001381161\">לקו\"ת שה\"ש ח</i>,<i> א</a></i>.<i> ובכ\"מ</i>.<i> וראה לקמן הערה 49</i>."],["2502","42","כן משמע מהמשך הענינים ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381275\" data-slug=\"likkutei-torah\" data-id=\"4001381275\">לקו\"ת שם לו, ד</a> ואילך."],["2503","43","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381278\" data-slug=\"likkutei-torah\" data-id=\"4001381278\">יבמות קכב, א</a>. וש\"נ. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381274\" data-slug=\"likkutei-torah\" data-id=\"4001381274\">לקו\"ת שם לז, ג</a>. וראה גם שם לו, ג. מאמרי אדהאמ\"צ שם ס\"ע תקמב ואילך."],["2504","44","ראה עד\"ז ד\"ה פדה בשלום ה'תשל\"ט סוף ס\"ה (לעיל ח\"ב ע' מב)."],["2505","45","סהמ\"צ להצ\"צ מצות מילה פ\"ג (ו, ב). ובכ\"מ."],["2506","46","המשך תרס\"ו ע' רכב. ובכ\"מ. וראה גם סהמ\"צ להצ\"צ (סב, א), דהוי' הוא סובב ואלקים ממלא."],["2507","47","המשך תרס\"ו וסה\"מ תרע\"ח שבהערה 31."],["2508","48","להעיר מקונטרס עץ החיים פ\"ז, שבהעבודה דיחו\"ת, להיותה רק ביטול היש, \"בנקל הוא שיפול ממדריגתו ח\"ו ויהי' יש גמור\"."],["2509","49","ראה גם ד\"ה שובה ישראל ה'תשמ\"א (לעיל ח\"א ע' קטו ואילך). ולהעיר מ<a class=\"ft-cite\" href=\"#/read/tanya/3401310025\" data-slug=\"tanya\" data-id=\"3401310025\">תניא רפ\"כ</a> (נעתק לעיל בשוה\"ג להערה 35) דפירוש \"אתה הוא עד שלא נברא העולם ואתה הוא משנברא העולם\" הוא, שהעולמות אינם פועלים שינוי <i>באחדותו</i> ית'. דמזה מוכח, שגם עולמות שנבראו באופן דבדרך ממילא (\"<i>נברא</i> העולם\") יש להם תפיסת מקום, ולכן צריך <i>לחדש</i> שהעולמות אינם פועלים שינוי באחדותו ית'.\nועפ\"ז יש לבאר זה ש\"בנוסחא הישנה הי' כתוב אתה הוא עד שלא בראת ועתה הוא הנוסחא עד שלאנברא\" (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381187\" data-slug=\"likkutei-torah\" data-id=\"4001381187\">לקו\"ת שה\"ש יד, ג</a>) – כי בדורות הראשונים הי' מקום לקס\"ד שישנה גם מציאות ממש, והי' צריך לשלול קס\"ד זה. אבל לאחרי שנתגלתה תורת הקבלה, שזה הי' גם הקדמה לגילוי תורת החסידות שבה מודגש ענין אחדותו ית' – בנוגע למציאות ממש, אין מקום לקס\"ד כזה, וזה שצריך לשלול הוא שלא ישנו אפילו \"מציאות\" שבתכלית הדקות, \"אתה הוא עד שלא <i>נברא</i> כו' אתה הוא <i>משנברא</i> כו'\"."],["2510","50","יתרו כ, ג."],["2511","51","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא רפ\"ד</a> \"ובלעדה אין להן קיום אמיתי\". ובפרט בנדו\"ד – נצחון המלחמה, דהנצחון הוא כשמקבץ עניני הנשמה שנתפזרו בהלבושים (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380861\" data-slug=\"likkutei-torah\" data-id=\"4001380861\">לקו\"ת תצא לו, א</a>), שזהו ע\"י עקירת <i>הרצון</i> (שם לז, א)."],["2512","52","ראה בארוכה לקו\"ש ח\"ג ע' 817."],["2513","53","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381151\" data-slug=\"likkutei-torah\" data-id=\"4001381151\">לקו\"ת שה\"ש ה, ג</a>-ד. וראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310024\" data-slug=\"tanya\" data-id=\"3401310024\">תניא פי\"ט (כה, א</a>)."],["2514","54","לעיל ע' קצ. שם ע' קמט."],["2515","55","סה\"מ עת\"ר ע' יד. ה'תש\"י ע' 32."],["2516","56","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, ב</a>)."],["2517","57","לקו\"ד כרך ב שלד, א. ספר השיחות תרצ\"ז ע' 171."],["2518","58","לקו\"ד שם שלו, א. ספר השיחות שם ע' 173."],["2519","59","אגה\"ק ס\"כ (קל, ריש ע\"ב)."],["2520","60","סה\"מ תרפ\"ה ע' קנ (וראה שם ע' קמח ואילך כמה ענינים בירידת האור)."],["2521","61","ע\"ד שנת\"ל ס\"ח בהדרגות דנשמה."],["2522","62","נוסף להעלי' שעי\"ז נשלמת הכוונה דדירה בתחתונים ע\"י עבודת האדם."],["2523","63","ראה לעיל ס\"ח."],["2524","64","להעיר מזה שארז\"ל (ב\"ר פ\"ח, יא. ועוד) שהאדם נברא מן העליונים ומן התחתונים. וראה בארוכה לעיל ח\"ב ע' שיא."],["2525","65","ראה <i>עד\"ז</i> <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041343\" data-slug=\"likkutei-sichot\" data-id=\"1300041343\">לקו\"ש ח\"ד ע' 1344</a>."],["2526","66","ראה בארוכה לקו\"ש שם."],["2527","67","בסופו – סה\"מ ה'ש\"ת ע' 167."],["2528","68","כמו כל הפירושים שבפסוק אחד ששייכים זה לזה, כידוע הראי' לזה מ\"שעטנז\" (נדה סא, ב) – ראה לקו\"ש ח\"ג ע' 782."],["2529","69","איוב ב, א."],["2530","70","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381172\" data-slug=\"likkutei-torah\" data-id=\"4001381172\">לקו\"ת שה\"ש י, ד</a>."]]],[1500390039,"<h3>בס\"ד. ש\"פ מטות-מסעי, מבה\"ח מנחם-אב<sup data-n=\"2531\">*</sup>, ה'תשי\"ג</h3>\n(הנחה בלתי מוגה)\n<b>אלה</b> מסעי בני ישראל אשר יצאו מארץ מצרים גו' ויכתוב משה את מוצאיהם למסעיהם גו' ואלה מסעיהם למוצאיהם<sup data-n=\"2532\">1</sup>. וידוע הדיוקים<sup data-n=\"2533\">2</sup> שבזה, שאומר אלה מסעי, שהוא לשון רבים, ומסיים אשר יצאו מארץ מצרים אשר מארמ\"צ, הוא רק יציאה ונסיעה הראשונה. גם אינו מובן אומרו ויכתוב משה, שהרי כל התורה כולה כתבה משה רבינו, ומה משמיענו בזה. גם מהו הכפל דמוצאיהם למסעיהם ומסעיהם למוצאיהם, והיפך הסדר מרישא לסיפא. ובכללות הדברים צריך להבין, מה נוגע הספור והידיעה דסדר המסעות, ואף דבשביל דור ההוא מפרש במדרש<sup data-n=\"2534\">3</sup> משל למלך ובנו שהלכו כו' כשחזרו היו מונין כל המסעות והמאורעות שבהם, אבל הרי התורה היא נצחית, וע\"כ אשר ספור זה נוגע בכל הזמנים ובכל המקומות.\nב) <b>ולהבין</b> כ\"ז צריך להקדים תחילה ביאור בקשת כנסת ישראל זכור הוי' מה הי' לנו הביטה וראה את חרפתינו<sup data-n=\"2535\">4</sup>, ופירש הבעש\"ט<sup data-n=\"2536\">5</sup> געדענק ג-ט וואָס עס איז געוואָרען פון אונזער מ\"ה שבנשמה, קוק זיך צו און מאַך אונז זעענדיק אונזער אייגענע שאַנדע, דזהו בקשת כנסת ישראל מהקב\"ה. וכמו כן יש בקשת זכירה מהקב\"ה לישראל, וכדאיתא בזהר ר\"פ בחוקותי ע\"פ זה שהבקשה מלמעלה<sup data-n=\"2537\">6</sup> מכנסת ישראל היא ג\"כ בלשון זכור, וכמ\"ש<sup data-n=\"2538\">7</sup> עמי זכר נא מה יעץ בלק מלך מואב ומה ענה אותו בלעם בן בעור גו', ומסיים<sup data-n=\"2539\">8</sup> מה ה' דורש ממך גו' עשות משפט ואהבת חסד והצנע לכת עם אלקיך, וכתיב<sup data-n=\"2540\">9</sup> זכור את בוראך בימי בחרותיך גו' עד אשר לא תחשךהשמש גו', ואיתא במדרש<sup data-n=\"2541\">10</sup> אמר להם הנביא לישראל זכרו את בוראכם עד שביהמ\"ק קיים שנקרא בית הבחירה, עד שברית כהונה קיימת, שנאמר<sup data-n=\"2542\">11</sup> ובחור אותו מכל שבטי ישראל לי לכהן, עד שברית לוי' קיימת, שנאמר<sup data-n=\"2543\">12</sup> כי בו בחר ה' אלקיך מכל שבטיך<sup data-n=\"2544\">13</sup>. וזהו עד אשר לא תחשך השמש, דתחשך השמש קאי על חורבן ביהמ\"ק, וצ\"ל זכור את בוראיך בימי בחרותיך, בזמן הבית שנקרא בית הבחירה<sup data-n=\"2545\">14</sup>. וכיון שבזמן הבית לא קיימו בנ\"י הבקשה מלמעלה זכור את בוראך גו', זכר נא גו' עשות משפט ואהבת חסד והצנע לכת עם אלקיך, הנה זה הי' סיבת החורבן, ובגלל זה מבקשים אנו בזמן הגלות זכור הוי' מה הי' לנו הביטה וראה את חרפתינו.\n<b>וצריך</b> להבין מהו ענין הזכרון למעלה שעל זה מבקשים זכור הוי' מה הי' לנו. דהנה, זכרון ושכחה הוא ענין בלי גבול וגבול, דענין השכחה הוא מצד הגבלה, דכיון שהאדם הוא מוגבל, ומצד זה כל עניניו הם בהגבלה, לכן גם הרושם שעשה עליו הדבר שראה או ששמע הוא בהגבלה ומשום זה נפסק אח\"כ, שזהו\"ע השכחה. משא\"כ ענין הזכרון הוא בלי גבול, וכמו שרואים גם באדם, שדבר שנוגע לו תוך תוכו ופנימיות נפשו, היינו, שהוא למעלה מהגבלותיו, הרי הוא זוכר אותו תמיד. ולפי זה אינו מובן מהו תוכן הבקשה זכור הוי' גו', הרי למעלה הוא בלי גבול, ולמה צריך לבקש למעלה ענין הזכרון.\nג) <b>אך</b> הענין הוא, דהנה, זכרון ושכחה הו\"ע פנים ואחור<sup data-n=\"2546\">15</sup>, פנימיות וחיצוניות, וכמו שהוא באדם למטה, שדבר שנוגע לו בפנימיות הוא זוכר אותו תמיד, משא\"כ דבר שנוגע לו רק בחיצוניות (שהו\"ע אחור) שייך שם ענין השכחה. וכמו\"כ יש גם למעלה בחינות פנים ימין שמאל ואחור, כדאיתא ברמ\"ז<sup data-n=\"2547\">16</sup> שהם כנגד ד' עולמות אבי\"ע. דהנה, עולם האצילות נקרא פנים, דכשם שבפנים שבאדם ישנו פנימיות החיות, כמו\"כ באצילות הוא פנימיות אוא\"ס, ועד שאיהו וחיוהי וגרמוהי חד<sup data-n=\"2548\">17</sup>. והיינו, דאף שאצילות הוא לאחר הצמצום, וכללות האור שלאחר הצמצום הוא בבחי' קו קצר ומצומצם, מ\"מ, הרי זה אותו מהות האור. וזהו ההפרש בין בי\"ע ואצילות, דהתהוות בי\"ע היא ע\"י הפרסא, משא\"כ התהוות האצילות היא לא ע\"י הפרסא אלא רק ע\"י הצמצום<sup data-n=\"2549\">18</sup>, כמ\"ש בע\"ח<sup data-n=\"2550\">19</sup>. וההפרש בין צמצום ופרסא הוא כמשל ההפרששאנו רואים למטה בין האור שמאיר דרך חלון או דרך נקב<sup data-n=\"2551\">20</sup>, דאף שהאור הוא במיעוט וצמצום, שמאיר רק במדה כזו שהחלון או הנקב יכולים להכיל, מ\"מ הרי הוא אותו מהות האור, משא\"כ כאשר האור מאיר דרך מסך, אזי האור הוא בשינוי המהות, עד שהאור שבא אחרי המסך נקרא אור של תולדה. וכמו\"כ הוא למעלה, שהתהוות בי\"ע שע\"י הפרסא הוא בשינוי המהות, משא\"כ התהוות האצי' שע\"י צמצום, הנה אף שהאור שם הוא בצמצום, מ\"מ הרי הוא אותו מהות אור כמו קודם הצמצום. ואף שגם באצילות יש פרסאות<sup data-n=\"2552\">21</sup>, כידוע שיש פרסא בין כתר לחכמה, בין בינה לז\"א ובין ז\"א למל', מ\"מ<sup data-n=\"2553\">22</sup>, אינו דומה הפרסא שבאצילות להפרסאות דבי\"ע, שהפרסאות דבי\"ע ענינם הוא להעלים והם מעלימים על האור, משא\"כ הפרסאות שבאצילות הם מגלים את האור. דהנה, פרסא הוא כמו עור, ואמרו חז\"ל<sup data-n=\"2554\">23</sup> אלו שעורותיהן כבשרן עור האדם כו' (שאינו כמו עור בהמה שהוא עור גס), ודוגמתו למעלה הו\"ע הפרסאות שמגלים את האור. וזהו ההפרש בין אותיות דמ\"ה<sup data-n=\"2555\">24</sup> לאותיות דב\"ן (וענינם בעבודה הוא ההפרש בין אותיות התורה לאותיות התפילה<sup data-n=\"2556\">25</sup>), דאותיות דב\"ן הם מעלימים על האור, ומצד זה נעשים הנבראים בבחי' יש ודבר נפרד, משא\"כ אותיות דמ\"ה אינם מעלימים על האור, ואדרבה, מגלים את האור, ולכן הם פועלים ביטול בנבראים. וזהו שעורותיהן כבשרן עור האדם, כי אדם בגימטריא מ\"ה<sup data-n=\"2557\">26</sup>, והו\"ע הפרסאות שמגלים את האור, שהם הפרסאות שבאצילות, שנקרא בשם מ\"ה, כמ\"ש בפתח אלי'<sup data-n=\"2558\">27</sup> שם מ\"ה דאיהו אורח אצילות. וזהו שאצילות נקרא פנים לפי שמאיר שם גילוי אוא\"ס. ועיקר בחי' פנים הוא בחי' חכמה, וע\"ד<sup data-n=\"2559\">28</sup> מ\"ש חכמת אדם תאיר פניו, והיינו, שבאצילות מאיר אור החכמה, כמאמר<sup data-n=\"2560\">29</sup> אבא עילאה מקננא באצילות, ובחכמה מאיר אוא\"ס, כמ\"ש רבינו הזקן בתניא<sup data-n=\"2561\">30</sup> בשם מורו הה\"מ שמדריגת החכמה ענינה שהוא לבדו הוא ואין זולתו, ולמעלה יותר, שבאצילות מאיר אור הכתר, שזהו\"ע שם מ\"ה שהוא במילוי אלפין, ואל\"ף הוא ספי' הכתר<sup data-n=\"2562\">31</sup>. וכיון שאצילות הוא בחי' פנים, לא שייך שם ענין השכחה, משא\"כ בבי\"ע שהוא בחי' אחור, שייך שם ענין השכחה. והנה, כל זה הוא ההפרש בעולמות, משא\"כ נשמות ישראל הנה גםכמו שהם למטה הם בבחי' פנימיות, דנשמות ישראל עלו במחשבה<sup data-n=\"2563\">32</sup>, היינו במדריגה היותר עליונה שבמחשבה<sup data-n=\"2564\">33</sup>, וכתיב<sup data-n=\"2565\">34</sup> פנים בפנים דיבר הוי' עמכם, דעי\"ז שדיבר הוי' עמכם נעשה הפנימיות דישראל הפנימיות שלמעלה. אמנם, כל זה הוא מצד הנשמה עצמה, אבל מצד ירידתה למטה והתלבשותה בגוף ונה\"ב ובפרט בזמן הגלות, הנה בזמן הגלות כתיב<sup data-n=\"2566\">35</sup> ואנכי הסתר אסתיר פני, והיינו, דכיון שפנו אלי עורף ולא פנים<sup data-n=\"2567\">36</sup>, היינו, שהעבודה היתה בבחי' אחור, לכן נעשה גם למעלה הסתר אסתיר פני, ומצד זה צריך לבקש על ענין הזכרון, זכור ה' מה הי' לנו.\nד) <b>ולהבין</b> בעומק יותר מה שנשמות ישראל הם בבחי' פנימיות, הנה כתיב<sup data-n=\"2568\">37</sup> ועתה ישראל מה הוי' אלקיך שואל מעמך כי אם ליראה גו', ואמרו רז\"ל<sup data-n=\"2569\">38</sup> אטו יראה מילתא זוטרתי היא, אין לגבי משה מילתא זוטרתי היא. והנה, מ\"ש כי אם ליראה, קאי על יראה תתאה, שזהו אומרו <i>כי אם</i> ליראה, היינו שהיא יראה היותר פחותה, ולכן לגבי משה מילתא זוטרתי היא. והענין בזה, דהנה כתיב<sup data-n=\"2570\">39</sup> כי א-ל דעות הוי', ב' דעות<sup data-n=\"2571\">40</sup>, דעת עליון ודעת תחתון<sup data-n=\"2572\">41</sup>. דעת עליון הוא שלמעלה יש ולמטה אין, היינו, שרואים בראי' חושית שלמעלה הוא היש האמיתי ולמטה אין, ודעת תחתון הוא שהבריאה היא יש מאין, היינו שלמטה יש ולמעלה אין, דכיון שהוא רואה רק את היש הנברא, לכן קורא להמטה בשם יש ולהמעלה בשם אין. ומצד ההפרש בין ב' דעות אלו יש הפרש גם בביטולם, שהביטול שמצד דעת תחתון הוא ביטול היש בלבד, דכיון שהוא רואה את היש, הרי הוא במציאות, אלא שאעפ\"כ יש בו גם ענין של ביטול, ביטול היש, משא\"כ הביטול שמצד דעת עליון הוא ביטול במציאות, דכיון שרואה שלמטה הוא אין, לכן הביטול הוא ביטול במציאות. וזהו שלגבי משה יראה תתאה מילתא זוטרתי היא, דהנה משה הוא בבחי' דעת עליון, כמאמר רז\"ל<sup data-n=\"2573\">42</sup> כל הנביאים נתנבאו בכה ומשה נתנבא בזה, דזה הוא ראיית המהות, בחי' דעת עליון, שמצד זה הי' בבחינת ביטול במציאות, ולכן לגבי משה שהוא בבחי' דעת עליון, ביטול במציאות, הנה יראה תתאה שהיא בבחי' ביטול היש בלבד, מילתא זוטרתי היא. והנה<sup data-n=\"2574\">43</sup>, אף שיראה תתאה היא מדריגה תחתונה, מילתא זוטרתי, שעל זה אמרו כי אם ליראה, מ\"מ, תובעים (מאָנט מען) יראה תתאה דוקא, לפי שתכלית המכווןועיקר התענוג הוא ביראה תתאה יותר מאשר ביראה עילאה, וכמ\"ש<sup data-n=\"2575\">44</sup> צחוק עשה לי אלקים, שדוקא עי\"ז שפועלים ענין הביטול בהדברים שבאים משם אלקים דוקא שהם בבחי' יש, ביטול היש לאין, אזי נעשה עיקר ענין הצחוק והתענוג למעלה, וכמו\"כ כתיב<sup data-n=\"2576\">45</sup> לויתן זה יצרת לשחק בו, דלויתן הוא מלשון חבור, כמ\"ש<sup data-n=\"2577\">46</sup> ילוה אישי, וענין החבור שייך דוקא כאשר יש ב' דברים נבדלים זה מזה, וענין זה הוא בהעבודה דביטול היש דוקא, שהיש והאין הם ב' דברים נבדלים זמ\"ז, ומ\"מ פועלים ביטול היש לאין, ועי\"ז דוקא נעשה ענין השחוק, לשחק בו. והיינו, דעם היות שהעבודה דאתהפכא היא למעלה יותר מהעבודה דאתכפיא, הנה זהו רק בענין הגילויים, אבל עיקר התענוג הוא בעבודה דאתכפיא דוקא.\n<b>אך</b> עדיין צריך להבין מ\"ש אין לגבי משה מילתא זוטרתי היא, דלכאורה אינו מובן, הרי שואל מעמך כתיב. אך הענין הוא, כמבואר בתניא<sup data-n=\"2578\">47</sup> שכל נפש ונפש מבית ישראל יש בה מבחי' משה רבינו, ניצוץ מנשמת משה, והוא בחי' מ\"ה שבכל אחד מישראל, שהו\"ע ביטול במציאות (כנ\"ל), והיינו לפי ששרש הנשמות הוא מבחי' חכמה, כמ\"ש<sup data-n=\"2579\">48</sup> בנים אתם להוי' אלקיכם, וכתיב<sup data-n=\"2580\">49</sup> בני בכורי ישראל, וכמו הבן שנמשך מעצמות מוח האב, כמו\"כ הנשמות הם מעצמות בחי' החכמה, שהיא בחי' מ\"ה. ולכן הנשמות הם בתכלית הביטול, ביטול במציאות, כמ\"ש<sup data-n=\"2581\">50</sup> חי הוי' אלקי ישראל אשר עמדתי לפניו, שזה קאי על כל הנשמות, שהם באופן של עמידה, שהו\"ע הביטול. וזהו ועתה ישראל מ\"ה הוי' אלקיך שואל מעמך כי אם ליראה, דכיון שכל ישראל הם בבחי' מ\"ה, מצד הניצוץ משה שבכל אחד מישראל, הנה מה הוי' אלקיך שואל מעמך כי אם ליראה, שיראה היא מילתא זוטרתי לגבי הניצוץ משה שבכל אחד מישראל. ובכדי לגלות בחי' מ\"ה שבנפש, הנה על זה תקנו מאה ברכות, כמאמר רז\"ל<sup data-n=\"2582\">51</sup> אל תקרי מה אלא מאה, שמזה למדו שחייב אדם לברך מאה ברכות בכל יום, דמאה ברכות הוא ע\"ד מ\"ש<sup data-n=\"2583\">52</sup> ויזרע יצחק בארץ ההיא וימצא גו' מאה שערים ויברכהו ה', והיינו, שע\"י עבודת הצדקה, זורע צדקות<sup data-n=\"2584\">53</sup>, נעשית הברכה וההמשכה מלמעלה שנתגלה בחי' מ\"ה שבנפש.\n<b>אמנם</b> בזמן הגלות אין העבודה בבחי' מ\"ה שהיא פנימיות הנפש, כי אם בבחי' חיצוניות ואחוריים בלבד, שלכן נעשה גם למעלה הסתר אסתיר פני (כנ\"ל), ולכן אנו מבקשים זכור ה' מה הי' לנו, וואָס איז געוואָרען מיט אונזער מ\"ה, שהמ\"ההוא בהעלם והסתר. ועם היותו בהעלם, מ\"מ שייך ענין הזכירה, שהרי סוכ\"ס עיקרה שרשה ועצמותה של הנשמה היא בבחי' מ\"ה. וממשיך בכתוב הביטה גו', דהנה, ההפרש בין ראי' והבטה הוא<sup data-n=\"2585\">54</sup> שראי' היא בקירוב, כמ\"ש<sup data-n=\"2586\">55</sup> וירא כי לא יכול לו, והבטה הוא בריחוק, כמ\"ש<sup data-n=\"2587\">56</sup> הבט משמים וראה, ולכן, ענין הראי' שבקירוב אי אפשר להיות בזמן הגלות, ולזה אנו מבקשים הביטה, שזהו הגילוי שבבחי' מקיף, ועם היותו בבחי' מקיף, הרי זה פועל גם בפנימיות, ובפרט בנוגע לפעולה על הקליפות, דאור מקיף מסמא עיני החיצונים<sup data-n=\"2588\">57</sup>.\nה) <b>וביאור</b> הענין, דהנה, כשם שיש בחי' מ\"ה בקדושה כמו\"כ יש בחי' מ\"ה בלעו\"ז, והוא ענין ופלגשו ושמה ראומה<sup data-n=\"2589\">58</sup>, ראו מ\"ה<sup data-n=\"2590\">59</sup>. והענין בזה, דהנה, האפשרות לענינים דלעו\"ז היא מפני שיש להם נתינת מקום בקדושה, וכמו שרואים בעבודה בנפש, דכאשר עובד עבודתו בביטול, אבל באופן שמרגיש את הביטול, הרי זה נתינת מקום שיבוא מזה לבחי' ישות, והיינו, שתחילה יהי' הביטול באופן של ישות, שזהו\"ע קליפת ראומה, ראו מ\"ה, ואח\"כ יבוא לישות לגמרי, שהוא רע גמור. וכמו\"כ הוא גם בהשתלשלות העולמות, דע\"י קליפת ראו מה שהיא כנגד עולם האצילות, הנה בריבוי השתלשלות מסתעף מזה רע גמור, בחי' מ\"ה דלעו\"ז. ועז\"נ<sup data-n=\"2591\">60</sup> שופך<sup data-n=\"2592\">61</sup> דם האדם באדם, דאדם בגימטריא מ\"ה, הנה ע\"י העוונות הוא שופך דם האדם דקדושה, בחי' מ\"ה דקדושה, באדם בליעל, שהוא בחי' מ\"ה דלעו\"ז. והענין בזה, דהנה, רמ\"ח מ\"ע ושס\"ה מל\"ת הם כנגד רמ\"ח אברים ושס\"ה גידים<sup data-n=\"2593\">62</sup>, דענין האברים הוא שהם ממשיכים את החיות, ומגבילים את החיות שלא יומשך לחוץ, וכאשר חותכים את האבר אזי נמשך החיות לחוץ, ועד\"ז בנוגע לגידים שעל ידם הוא הילוך הדם, וכמו\"כ כשעובר על מ\"ע או על מל\"ת אזי גורם שנמשך החיות והדם דקדושה לחוץ. וזהו מ\"ש<sup data-n=\"2594\">63</sup> ונוקב שם הוי', דהנה כל המצוות תלוים בשם הוי'<sup data-n=\"2595\">64</sup>, וכשחטא ופגם והעביר את הדרך עי\"ז שעובר על א' ממצוות הוי', הרי הוא נוקב את שם הוי', ועי\"ז שופך דם האדם דקדושה באדם בליעל. וזהו ג\"כ מה שאמרורז\"ל<sup data-n=\"2596\">65</sup> גידר טיטוס את הפרוכת ויצא ממנו דם, והיינו, שהראו לו איך אפשר להיות ענין החורבן, שאין זה בכח עצמו, אלא רק ע\"י הפגם שנעשה עי\"ז ששפכו הדם, פנימיות החיות, דאדם דקדושה, באדם בליעל. ועפ\"ז יש לפרש עוד פירוש במ\"ש זכור הוי' מ\"ה הי' לנו, אַז אונזער מ\"ה איז געוואָרן מ\"ה דלעו\"ז. וענין זה נעשה ע\"י פירוש הא' במה הי' לנו, שבחי' מ\"ה דקדושה הוא בהעלם והסתר, ומזה נשתלשל למטה יותר, שבחי' מ\"ה דקדושה נעשה בחי' מ\"ה דלעו\"ז, ע\"ד הענין דשופך דם האדם באדם.\nו) <b>וממשיך</b> בכתוב הביטה וראה את חרפתינו. והענין בזה, דהנה כתיב<sup data-n=\"2597\">66</sup> חרפת אלמנותיך לא תזכרי עוד, דבזמן הגלות נקראת כנס\"י בשם אלמנה, כמ\"ש<sup data-n=\"2598\">67</sup> היתה כאלמנה, ואמרו רז\"ל<sup data-n=\"2599\">68</sup> כאלמנה ולא אלמנה ממש, כאשה שהלך בעלה למדינת הים. דהנה, אשה היא כנס\"י ובעלה זה הקב\"ה, ואשה שהלך בעלה למדינת הים היינו שחסר היחוד דכנס\"י עם הקב\"ה, ובענין הספירות הוא יחוד זו\"ן, דאשה היא בחי' מלכות, ובעלה הוא בחי' ז\"א, ואשה שהלך בעלה למדינת הים היינו, שבחי' ז\"א (אינו נמשך למלכות, אלא) נסתלק לבחי' ים החכמה, וזהו שבזמן הגלות קוב\"ה סליק לעילא ולעילא<sup data-n=\"2600\">69</sup>, קוב\"ה הוא בחי' ז\"א, ובזמן הגלות סליק לעילא ולעילא, לעילא בחי' בינה ולעילא בחי' חכמה. וזהו\"ע אלמנה, כמ\"ש בפרדס<sup data-n=\"2601\">70</sup> שאלמנה הוא אל מנה, מנה הוא מאה זוזי, ב\"פ נו\"ן, והיינו נו\"ן שערי בינה כפי שהם מלמטה למעלה ומלמעלה למטה, שעל ידם נעשית העלאת המדות והמשכת אוא\"ס בבחי' המדות, שעי\"ז יומשך למטה בבחי' המלכות. וזהו ג\"כ ענין המסעות, מוצאיהם למסעיהם גו' מסעיהם למוצאיהם<sup data-n=\"2602\">71</sup>, שהו\"ע העלאה והמשכה<sup data-n=\"2603\">72</sup>. אך בזמן הגלות הוא אל מנה, שחסר ענין ההעלאה וההמשכה שע\"י הנו\"ן שערים, ולכן לא נמשך מבחי' ז\"א למלכות להיות יחוד זו\"ן, שזהו\"ע אלמנה. ועוד פירוש באלמנה, כמ\"ש בספר השרשים<sup data-n=\"2604\">73</sup> דאלמנה הוא מלשון אלם. דהנה<sup data-n=\"2605\">74</sup>, להפירוש שאלמנה הוא מלשון אל מנה, שכתובתה מנה, אינו מובן למה גם לזכר קוראים אלמן, ועכצ\"ל שלפי שאשה נקראת אלמנה, לכן גם זכר נקרא אלמן<sup data-n=\"2606\">75</sup>. אך להפירוש שאלמנה הוא מלשון אלם, אתי שפיר שגם זכר נקרא אלמן, לפי שחסר השמחה דיחוד בעל עם אשתו. והענין בזה, דכאשר מאיר גילוי הקול בדיבור אזי הדיבור מאיר בגילוי, וכאשר הדיבור מאירבגילוי אזי ידבר עמים תחתינו<sup data-n=\"2607\">76</sup> (דע\"י ידבר מלשון דיבור נעשה גם ידבר מלשון הנהגה), שישראל הם במעלה העליונה כו', אבל כאשר אין הקול בגילוי אזי הדיבור הוא בהעלם בגלות, וזהו\"ע אלמנה מלשון אלם. ועל זה אנו מבקשים הביטה וראה את חרפתינו, דאף שהבטה הוא בחי' מקיף, מ\"מ, הרי זה מועיל גם בפנימיות, כמ\"ש<sup data-n=\"2608\">77</sup> כי הוי' אלקיך מתהלך בקרב מחניך להצילך גו', להצילך היינו להיות צל על ראשך שהוא בחי' מקיף, ומ\"מ נעשה עי\"ז להצילך כפשוטו, מלשון הצלה, ובפרט בנוגע לפעולה על הקליפות, הרי אור מקיף מסמא עיני החיצונים (כנ\"ל).\n<b>וזהו</b> מ\"ש זכור הוי' מה הי' לנו וגו', דהנה, הקב\"ה תובע מישראל זכור את בוראך בימי בחרותיך, עד שביהמ\"ק קיים שנקרא בית הבחירה, עד שברית כהונה קיימת, ועד שברית לוי' קיימת, והתביעה היא עשות משפט ואהבת חסד והצנע לכת עם אלקיך, אך כאשר חסרה העבודה דהצנע לכת, שהיא היפך הענין דראו מ\"ה, אזי נעשה מ\"ה דלעו\"ז. ולזה אנו מבקשים זכור ה' מה הי' לנו, שהמ\"ה דקדושה הוא בהעלם והסתר, ועד שעי\"ז נעשה המ\"ה דלעו\"ז, ולכן הביטה וראה את חרפתינו, עד שחרפת אלמנותיך לא תזכרי עוד.\nז) <b>וזהו</b><sup data-n=\"2609\">78</sup> מש\"נ ואלה מסעי בני ישראל אשר יצאו מארץ מצרים, דהנה, כל הגליות<sup data-n=\"2610\">79</sup> נקראו מצרים, מצרים לשון מיצר וגבול, ועד שבאים<sup data-n=\"2611\">80</sup> לירדן ירחו, ירחו לשון ריח, עבודה שלמעלה מטעם ודעת, ה\"ז עדיין בחי' מיצר וגבול, ובגאולה העתידה ע\"י משיח צדקנו יתגלה בחי' זו, וכדכתיב<sup data-n=\"2612\">81</sup> עליו אשר לא למשמע אזניו יוכיח ואפילו לא למראה עיניו כ\"א והריחו ביראת הוי' דמורח ודאין<sup data-n=\"2613\">82</sup>, מקיפים שלמעלה מחו\"ב, ועד שבאין לזה הוא ענין המסעות. והעבודה שבהמסעות היינו בירידת הנשמה והתלבשותה במיצר הגוף בכלל, ובפרט בזמן המצרים ההעלמות וההסתרים שבהגליות, הנה הנתינת כח על זה הוא מבחי' מוצאיהם, לשון וכמוצא מים אשר לא יכזבו מימיו<sup data-n=\"2614\">83</sup>, שרש ועצם הנשמה, מ\"ה שבנשמה, וע\"י המשכה ממוצאיהם למסעיהם, שנעשה זה ע\"י בחי' משה שבכאו\"א מישראל, ויכתוב משה, נתגלה בחי' מ\"ה גם בהנשמה שבגוף ועי\"ז עובד עבודתו. והעבודה היא הנסיעה והעלאה ממטה למעלה, מסעיהם למוצאיהם. ואין מקרא יוצא מידי פשוטו, המסעות של דור המדבר במדבר העמים, כי מה שיש יכולת לאדם להמשיך מ\"ה דבנשמה בגילוי ולהתגבר על גופו ונפשו הבהמית, ובפרט בזמן הגלות ודרא דעקבתא דמשיחא, חשך כפול ומכופל, זמן הנסיונות וכו' כנ\"ל, הוא ע\"י מעשה אבות שהכניעומקור הקליפות ע\"י שנסעו וחנו במדבר העמים נחש שרף ועקרב, ויהי בנסוע גו' ויאמר משה גו' ויפצו אויביך וינוסו משנאיך גו'<sup data-n=\"2615\">84</sup>, לכן גם הענפים יהיו נכנעים אח\"כ ע\"י האדם במשך כל הדורות, ע\"י אשר ויכתוב משה שבכאו\"א את מוצאיהם למסעיהם ואלה מסעיהם למוצאיהם, והיינו ע\"ד כלל ופרט, עד אשר יבואו לירדן ירחו, מורח ודאין בעבודתו בפרט<sup data-n=\"2616\">85</sup>, ואח\"כ לגאולה הכללית ביאת משיח צדקנו אשר לא למשמע אזניו יוכיח ולא למראה עיניו ישפוט כי אם והריחו ביראת הוי' דמורח ודאין, בגאולה העתידה לבוא במהרה בימינו.\n**********",[["2531","*","\"המאמר שנאמר בש\"פ מטות מסעי, ש\"ק מברכים חדש מנחם אב . . הוא המאמר זכור הוי' עטר\"ת [סה\"מ עטר\"ת ע' תקנד ואילך] . . עם איזה שינויים, ובהוספת התחלה וסיום\"*.\nהתחלת וסיום המאמר – הוגהו ע\"י כ\"ק אדמו\"ר שליט\"א."],["2532","1","מסעי לג, א."],["2533","2","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380678\" data-slug=\"likkutei-torah\" data-id=\"4001380678\">לקו\"ת מסעי (פח, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380688\" data-slug=\"likkutei-torah\" data-id=\"4001380688\">צא, א</a>)."],["2534","3","במדב\"ר פכ\"ג, ג. תנחומא שם – הובא בפרש\"י."],["2535","4","איכה ה, א."],["2536","5","ס' המאמרים אידיש ע' ריב."],["2537","6","עד כאן הוגה ע\"י כ\"ק אדמו\"ר שליט\"א."],["2538","7","מיכה ו, ה."],["2539","8","שם, ח."],["2540","9","קהלת יב, א-ב.\n*) <i>לשון ה</i>\"<i>פתח דבר</i>\"<i> למאמר ד\"ה זכור הוי' עטר\"ת שי\"ל בקונטרס בפ\"ע (קה\"ת – ה</i>'<i> מנחם אב תשי\"ג)</i>,<i> בתוספת איזה מ\"מ והערות מכ\"ק אדמו\"ר שליט\"א (חלקם נעתקו לקמן)</i>.<i> הקונטרס נשלח ע\"י כ\"ק אדמו\"ר שליט\"א לכו\"כ</i>.<i> וראה מכתב ז' מנחם-אב שנה זו (אגרות-קודש ח\"ז ע' שלג)</i>: \"<i>מצו\"פ קונטרס המדבר ג\"כ בענין זכרון הן זה שהקב\"ה מבקש מישראל והן שישראל מבקשים מהקב\"ה וכמבואר בפנים</i>\"<i> וראה גם אגרות-קודש שם ע' שלב</i>.<i> שלח</i>.<i> שמ</i>.<i> שמז</i>.<i> ועוד</i>."],["2541","10","קה\"ר עה\"פ (ז)."],["2542","11","שמואל-א ב, כח."],["2543","12","שופטים יח, ה."],["2544","13","במד\"ר הסדר: כהונה, לוי', ביהמ\"ק. וצ\"ע טעם לשינוי הסדר כאן (הערת כ\"ק אדמו\"ר שליט\"א לד\"ה זכור הנ\"ל)."],["2545","14","אולי הכוונה לבאר שהקדימה דביהמ\"ק היא בהתאם להמשך הכתוב \"עד שלא תחשך השמש\" (המו\"ל)."],["2546","15","והשכחה באה מבחי' אחוריים והזכירה משל אור הפנים (ראה רשימות לאיכה ע' לג [נדפס לאח\"ז באוה\"ת נ\"ך ח\"ב ע' א'פה]) – הערת כ\"ק אדמו\"ר שליט\"א לד\"ה זכור הנ\"ל."],["2547","16","לזח\"ג צג, ב."],["2548","17","תקו\"ז בהקדמה (ג, ב)."],["2549","18","עיין ד\"ה וספרתם לכם (המשך תרס\"ו)."],["2550","19","שער ח (שער דרושי נקודות) פ\"ב."],["2551","20","כנראה מרמז להא דהמשכת האור מבינה לז\"א הוא בבחי' חלון ומז\"א לנוקבא בבחי' נקב (ראה אמרי בינה שער הק\"ש פל\"ה ובכ\"מ. וצע\"ק בע\"ח שער דרושי אבי\"ע פי\"ג, שער סדר אבי\"ע פ\"א ועוד) – הערת כ\"ק אדמו\"ר שליט\"א לד\"ה זכור הנ\"ל."],["2552","21","ראה סידור (עם דא\"ח) סג, ד ואילך. אוה\"ת ויקהל ע' ב'קא ואילך."],["2553","22","ראה סה\"מ תרס\"ד ע' קמט ואילך. המשך תרס\"ו שם. ועוד."],["2554","23","חולין פ\"ט מ\"ב (הערת כ\"ק אדמו\"ר שליט\"א לד\"ה זכור הנ\"ל)."],["2555","24","ראה תורה אור פ' משפטים. ד\"ה ותחת רגליו (הערת כ\"ק אדמו\"ר שליט\"א לד\"ה זכור הנ\"ל)."],["2556","25","המשך תער\"ב ח\"א ע' תריח ואילך. ובכ\"מ."],["2557","26","ראה עץ חיים שער יו\"ד (שער התיקון) פ\"ג. שער לח (שער לאה ורחל) פ\"ב. ובכ\"מ."],["2558","27","תקו\"ז בהקדמה (יז, א)."],["2559","28","קהלת ח, א."],["2560","29","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370334\" data-slug=\"torah-or\" data-id=\"3901370334\">רמ\"ז לזח\"ב רכ, ב</a>. תו\"א משפטים עה, א. וראה סה\"מ תרצ\"ו ע' 119. וש\"נ."],["2561","30","פל\"ה בהגה\"ה."],["2562","31","ראה תקו\"ז תכ\"א (נט, ב). תמ\"ט (פה, ב)."],["2563","32","בראשית רבה פ\"א, ד."],["2564","33","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381206\" data-slug=\"likkutei-torah\" data-id=\"4001381206\">לקו\"ת שה\"ש יט, ב</a>."],["2565","34","ואתחנן ה, ד."],["2566","35","וילך לא, יח."],["2567","36","ירמי' ב, כז."],["2568","37","עקב י, יב."],["2569","38","ברכות לג, ב. וראה חדא\"ג שם ובמנחות (מג, ב). <a class=\"ft-cite\" href=\"#/read/tanya/3401310047\" data-slug=\"tanya\" data-id=\"3401310047\">תניא פמ\"ב</a>."],["2570","39","שמואל-א ב, ג."],["2571","40","ראה תקו\"ז תס\"ט בתחילתו."],["2572","41","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370304\" data-slug=\"torah-or\" data-id=\"3901370304\">תו\"א יתרו סח, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380811\" data-slug=\"likkutei-torah\" data-id=\"4001380811\">לקו\"ת פ' ראה כג, ד</a>. שמע\"צ פג, א. ובכ\"מ."],["2573","42","ספרי ר\"פ מטות. וראה לקו\"ת מטות שם."],["2574","43","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380690\" data-slug=\"likkutei-torah\" data-id=\"4001380690\">לקו\"ת מסעי צא, ג</a>. קונטרס עה\"ח פ\"ט."],["2575","44","וירא כא, ו."],["2576","45","תהלים קד, כו."],["2577","46","ויצא כט, לד."],["2578","47","רפמ\"ב. וראה תו\"א פ' משפטים ד\"ה ותחת רגליו."],["2579","48","ראה יד, א."],["2580","49","שמות ד, כב."],["2581","50","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380390\" data-slug=\"likkutei-torah\" data-id=\"4001380390\">מלכים-א יז, א</a>. ועוד. וראה לקו\"ת נשא כ, ג."],["2582","51","מנחות מג, ב ובפרש\"י. ועוד."],["2583","52","תולדות כו, יב."],["2584","53","ברכת יוצר אור."],["2585","54","ראה איכ\"ר עה\"פ."],["2586","55","וישלח לב, כו."],["2587","56","תהלים פ, טו."],["2588","57","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370157\" data-slug=\"torah-or\" data-id=\"3901370157\">תו\"א מקץ לד, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380529\" data-slug=\"likkutei-torah\" data-id=\"4001380529\">לקו\"ת קרח נג, ד</a>. ובכ\"מ."],["2589","58","וירא כב, כד."],["2590","59","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380260\" data-slug=\"likkutei-torah\" data-id=\"4001380260\">לקו\"ת ויקרא (מג, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380175\" data-slug=\"likkutei-torah\" data-id=\"4001380175\">כג, ד</a>). ויל\"ע בל\"ת להאריז\"ל ס\"פ וירא (הערת כ\"ק אדמו\"ר שליט\"א לד\"ה זכור הנ\"ל)."],["2591","60","נח ט, ו."],["2592","61","ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380362\" data-slug=\"likkutei-torah\" data-id=\"4001380362\">לקו\"ת במדבר (יג, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380366\" data-slug=\"likkutei-torah\" data-id=\"4001380366\">יד, ג</a>). רשימות איכה ע' מח* (הערת כ\"ק אדמו\"ר שליט\"א לד\"ה זכור הנ\"ל)."],["2593","62","ראה זח\"א קע, ב."],["2594","63","אמור כד, טז."],["2595","64","ראה תקו\"ז תכ\"ט (עג, א). ת\"ע (קלא, ב). טעמי המצות להאריז\"ל בלקו\"ת פ' בראשית.\n*) <i>אוה\"ת ואתחנן ע' רמו ואילך</i>.<i> סה\"מ תרכ\"ט ס\"ע רצ ואילך</i>."],["2596","65","גיטין נו, ב. וראה אוה\"ת ואתחנן וסה\"מ תרכ\"ט שם."],["2597","66","ישעי' נד, ד."],["2598","67","איכה א, א."],["2599","68","תענית כ, א. איכ\"ר ע\"פ זה. זח\"ב קכב, א."],["2600","69","ראה זהר ח\"א רי, א. ח\"ג כ, ב. עה, א."],["2601","70","שער ערה\"כ ערך אלמנה. וראה כתובות י, ב."],["2602","71","פרשתנו (מסעי) לג, ב."],["2603","72","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380692\" data-slug=\"likkutei-torah\" data-id=\"4001380692\">לקו\"ת</a> פרשתנו (מסעי) צב, א. שם, ד. צג, ד. צו, א."],["2604","73","בס' שרש ישע – הובא ברשימות איכה ע' יט [אוה\"ת נ\"ך ח\"ב ע' א'מח]. ראה ג\"כ זח\"ב כט, ב."],["2605","74","ראה גם אוה\"ת נ\"ך שם ע' א'מז ואילך."],["2606","75","חדא\"ג מהרש\"א כתובות שם."],["2607","76","תהלים מז, ד."],["2608","77","תצא כג, טו."],["2609","78","מכאן עד סוף המאמר הוגה ע\"י כ\"ק אדמו\"ר שליט\"א."],["2610","79","ראה בראשית רבה פט\"ז, ה."],["2611","80","ראה בכ\"ז לקו\"ת מסעי שם [שבהערה 2]. ד\"ה אלה מסעי בספר המאמרים תרכ\"ז [סה\"מ תרכ\"ז ע' שמא ואילך, ובהוצאת תש\"ס – ע' שסד ואילך]."],["2612","81","ישעי' יא, ג."],["2613","82","סנהדרין צג, ב."],["2614","83","ישעי' נח, יא."],["2615","84","בהעלותך יו\"ד, לה."],["2616","85","ראה אגה\"ק ס\"ד."]]],[1500390040,"<h3>בס\"ד. ש\"פ מטות ומסעי, מבה\"ח מנחם-אב, ה'תשט\"ז<sup data-n=\"2617\">*</sup></h3>\n(הנחה בלתי מוגה)\n<b>הללוי'</b> שירו להוי' שיר חדש תהלתו בקהל חסידים<sup data-n=\"2618\">1</sup>, וחותם<sup data-n=\"2619\">2</sup> רוממות אל בגרונם וחרב פיפיות בידם, דבהפסוקים שלאחר זה הוא מבאר מה יעשו בחרב וכו'. והנה איתא במדרש תהלים במקומו דמזמור זה מדבר בלע\"ל: מי הם החסידים אלו ישראל, כל זמן שרואים את הקב\"ה הם נעשים חסידים כו', ראוהו בים נעשו חסידים ואמרו שירה שנאמר<sup data-n=\"2620\">3</sup> אז ישיר כו', וכשיראו אותו לעוה\"ב הם נעשים חסידים שנאמר תהלתו בקהל חסידים. וכן איתא במכילתא וילקוט פ' בשלח דשיר זה הוא לעתיד לבוא, ולכן אומר שיר חדש לשון זכר<sup data-n=\"2621\">4</sup>, ובכ\"מ נאמר שירה חדשה לשון נקבה, ואפילו בגאולת מצרים אומר השירה הזאת לשון נקבה. וכדמבאר בשה\"ש רבה (עה\"פ שחורה אני ונאוה<sup data-n=\"2622\">5</sup>) נקבה זו נוטלת עישור נכסים כו' כך ירשו ישראל ארץ ז' עממין שהוא עישור ע' אומות כו' אמרו שירה בלשון נקבה כו' שנאמר כו' השירה הזאת לה', אבל לעת\"ל הן עתידין לירש כזכר היורש לכל נכסי אביו כו' אומרין בלשון זכר. וצריך להבין אומרו רוממות א-ל בגרונם וחרב פיפיות בידם, דמאחר שמדבר בגאולה העתידה, א\"כ מהו ענין החרב, והרי לעתיד כתיב<sup data-n=\"2623\">6</sup> וכתתו חרבותם לאתים גו' לא ישא גוי אל גוי חרב.\nב) <b>ולהבין</b> זה יש להקדים תחלה דאיתא במשנה (שבת פ\"ו מ\"ד) לא יצא האיש (בשבת) לא בסייף<sup data-n=\"2624\">7</sup> לא בקשת ולא בתריס ולא באלה ולא ברומח כו', רבי אליעזר אומר תכשיטין הן לו, וחכמים אומרים אינו אלא כו' שנאמר וכתתו חרבותם לאתים. והנה במשנה זו נימנו חמשה כלי זיין, דסייף הוא חרב שהוא כליזיין, וכן קשת, וגם תריס שענינו להגן בעד החצים ובליסטראות הוא ג\"כ בכלל הכלי זיין, וכן אלה פי' בגמרא<sup data-n=\"2625\">8</sup> מאי אלה קולפא, שהוא שבט שמכין בו וראשו עב, וא\"כ הוא ג\"כ כלי זיין. ואיתא בירושלמי<sup data-n=\"2626\">9</sup> ע\"פ<sup data-n=\"2627\">10</sup> וחמושים עלו בני ישראל מארץ מצרים, שבתיבת וחמושים יש ב' פירושים, פירוש חמש ופירוש מזויינים, והיינו שהיו מזויינים בהחמשה כלי זיין שחושב בהמשנה (דכן הוא הגירסא הנכונה בירושלמי<sup data-n=\"2628\">11</sup>). וצריך להבין ההפרש בין גאולת מצרים לגאולה העתידה, דבגאולה העתידה כתיב וכתתו חרבותם לאתים, ובגאולת מצרים הי' צריך לכלי זיין, דלכאורה, מאחר שהו\"ע של גאולה, א\"כ למה צריך לכלי זיין.\nג) <b>ולהבין</b> זה, צריך להקדים תחלה ענין החרב ברוחניות. דהנה אמרו רז\"ל<sup data-n=\"2629\">12</sup> כל הקורא ק\"ש כו' כאילו אוחז חרב של שתי פיות, דמשמע מזה שיש איזה מעלה בחרב של שתי פיות דוקא. והענין הוא, כדאיתא בזהר<sup data-n=\"2630\">13</sup> דחרב דא הוי', רישא דחרבא הוא יו\"ד דהוי', גופא דחרבא הוא וא\"ו, ה\"א ה\"א הן תרין פיות דילי', נרתקא דחרבא הוא שם אד'. והענין הוא, דהנה כתיב<sup data-n=\"2631\">14</sup> הוי' יחתו מריביו, היינו, שישנם אלו הלוחמים על הוי', ונצוח המלחמה הוא ע\"י שם הוי' גופא, דחרב דא הוי', וע\"י חרב הוי' מנצחים המלחמה כנגד אלו הלוחמים על הוי'.\n<b>והענין</b> הוא, דהנה יניקת החיצונים יכול להיות משני אופנים. אופן א' הוא מריבוי הצמצומים, דכשמאיר אוא\"ס בבחי' גילוי משם אינם יכולים לקבל, לפי שאין השראת אוא\"ס אלא בבחי' ביטול, אבל בבחי' יש אינו יכול להיות גילוי אוא\"ס, כי אין אני והוא יכולים לדור<sup data-n=\"2632\">15</sup>, ולכן הקליפות שהם יש ודבר נפרד אינם יכולים לקבל מבחי' גילוי, אבל כשנתצמצם בבחי' ריבוי הצמצומים, יכולים הם לקבל יניקה, לפי שעכ\"פ מעט ביטול יש בהם, דקרו לי' אלקא דאלקיא<sup data-n=\"2633\">16</sup>, אלא שהם מחזיקים גם את עצמם למציאות, אבל מעט ביטול יש בם, ולכן יכולים הם לקבל יניקה מריבוי הצמצומים. ואופן הב' הוא שמקבלים יניקתם מהגבהה והתנשאות, היינו מעולם התהו שקדם לתקון, ששם אינו תופס מקום כלל, וכחשיכה כאורה<sup data-n=\"2634\">17</sup> בשוה, וכמ\"ש<sup data-n=\"2635\">18</sup> שממית בידים תתפש והיא בהיכלי מלך, דכיון שנמצאת בהיכלי מלך ששם אינותופס מקום כלל, לכן הנה גם שממית בידים תתפש. וזהו מ\"ש<sup data-n=\"2636\">19</sup> אם תגביה כנשר, שמגביהים את עצמם למעלה מאד, וכמו דרך הנשר בשמים<sup data-n=\"2637\">20</sup>.\n<b>והנה</b> ענין זה גופא שיכולים לקבל יניקה ע\"י ב' אופנים אלו, הרי זה תלוי בעבודת האדם. דהנה כתיב<sup data-n=\"2638\">21</sup> יעקב חבל נחלתו, וכמו למשל<sup data-n=\"2639\">22</sup> החבל שראשו אחד קשור למעלה וראשו א' למטה, הנה כשמתנענע הקצה התחתון מתנענע גם קצה העליון. ועד\"ז הוא גם בעבודת נש\"י, שלפי אופן עבודת האדם למטה נעשה ג\"כ למעלה. והיינו שכאשר האדם משפיל את עצמו בדברים גשמיים, דתמורת זה שהי' צריך להיות פנימיות רצונו לאלקות בת\"ת ותפלה, הנה תמורת זה משפיל את עצמו בדברים גשמיים, עי\"ז הוא גורם גם למעלה ריבוי הצמצומים עד שיוכל להיות מזה יניקת החיצונים. וכן כשאדם מגבי' את עצמו בבחי' התנשאות וגסות, דהגם שיודע בעצמו היטב את הפחיתות שלו, מ\"מ הוא מתנשא בלא טעם ודעת, הנה רוח אייתי רוח<sup data-n=\"2640\">23</sup>, שגורם יניקת החיצונים ממקום גבוה מאד. וזהו ענין פרעה אותיות העורף<sup data-n=\"2641\">24</sup>, שמקבל מבחי' עורף דאריך, שהוא בחי' גבוה מאד, וענין זה תלוי בעבודה, שכאשר פנו אלי עורף ולא פנים<sup data-n=\"2642\">25</sup> (כמ\"ש בהפטרה), הנה עי\"ז נמשך בחי' פרעה שיונק מעורף דא\"א, ששם כחשיכה כאורה כו'. וזהו ענין חרב של שתי פיות, כדי להכרית יניקתם מב' האופנים.\nד) <b>ולהבין</b> הענין בפרטיות, הנה מבואר בספרי קבלה וחסידות בהדרושים דמצרים ויציאת מצרים, דמצרים הוא מיצר הגרון, שבגרון יש ג' בחי', קנה וושט וורידין, שהו\"ע ג' שרי פרעה<sup data-n=\"2643\">26</sup>, שר המשקים שר הטבחים ושר האופים. והנה, כשם שיש מצרים וג' שרי פרעה בלעו\"ז, כמו\"כ יש מצרים וג' השרים גם בקדושה. דשר המשקים הוא המשכת התענוג, שהרי מים מצמיחים כל מיני תענוג<sup data-n=\"2644\">27</sup>, והו\"ע המשכת התענוג האלקי בכל סדר ההשתלשלות. ובגוף האדם הוא הקנה, דבקנה יש גידי המוח וע\"י הגידים נמשך התענוג מהמוח בכל הגוף, כמארז\"ל<sup data-n=\"2645\">28</sup> תלת קני הוי חד פריש ללבא וחד פריש לריאה וחד פריש לכבדא, שהם אברים כללים, וזהו\"ע הקנה שהוא ממשיך את התענוג מהמוח ע\"י גידי המוח בכל הגוף. ובעבודה הוא לימוד התורה בתענוג, שהתענוג הוא הפנימיות שמהתורה, וכמו\"כ התענוג בתפלה, דזהו\"ע שר המשקים. ושר הטבחים בעבודה הו\"ע רתיחת הדמים בקדושה, שהואבחי' אהבה כרשפי אש, דשר המשקים הו\"ע אהבה בתענוגים שהיא אהבה שנמשכת כמים, ושר הטבחים הוא אהבה כרשפי אש. ושר האופים הוא תורה, והיינו דהגם שנת\"ל דשר המשקים הוא תורה, הנה זהו התענוג דתורה, אבל תורה סתם הו\"ע שר האופים, דתורה נקראת חטה, בגימטריא כ\"ב<sup data-n=\"2646\">29</sup>, כ\"ב אתוון דאורייתא, ומהחטה צריך לעשות לחם, כמ\"ש<sup data-n=\"2647\">30</sup> לכו לחמו בלחמי, ובכדי שמהחטה תהי' לחם הרי זה ע\"י אפי', כמ\"ש<sup data-n=\"2648\">31</sup> ואפו עשר נשים לחמכם בתנור אחד, דתנור הוא חמימות האהבה כרשפי אש, ואחד הוא יחידו של עולם, ותנור אחד היינו הקאָך והרשפי אש בענין יחידו של עולם, הרי שיש כאן ב' ענינים, ענין התנור שהוא הרשפי אש, וענין יחידו של עולם שהוא נעלה ביותר, וזהו\"ע שר האופים שהוא התורה, שהוא ממוצע בין הב' קוים דשר המשקים ושר הטבחים.\n<b>והנה</b> ג' שרים אלו דקדושה כורתים את החיות מהג' שרים דלעו\"ז. דהנה גם בלעו\"ז יש ג' שרי פרעה, דשר המשקים בלעו\"ז הוא התענוג בענינים גשמיים, דהגם שהוא תאות היתר, מ\"מ, השקוע בהם גורם שאינו שייך כלל לענין אלקי. ושר הטבחים הוא רתיחת הדמים בדברים גשמיים וגם בדברים חומריים. ושר האופים הוא שבכללות ענינו אינו מונח בתורה כי אם בגשמיות. וע\"י הג' שרים כמו שהם בקדושה מכריתים את היניקה מהג' שרי פרעה דלעו\"ז. דהנה, ע\"י שר המשקים בקדושה שהוא העבודה דאהבה בתענוגים, שענינו הוא המשכת התענוג בהשתלשלות ע\"י ספירת החכמה, שזהו\"ע הקנה, קנה חכמה קנה בינה<sup data-n=\"2649\">32</sup>, הנה עי\"ז הוא מכרית את היניקה שיונקים ממקום גבוה, דכאשר ההמשכה היא ע\"י החכמה שענינה ביטול, אזי אי אפשר להם לקבל, כי, מה שיונקים ממקום הגבוה, הרי זה כשהוא בבחי' מקיף דוקא, אבל כאשר נמשך בפנימיות, אזי אין יכולים לינק, כמבואר בקונטרס ומעין<sup data-n=\"2650\">33</sup> בארוכה. וזהו\"ע שר המשקים שכורת היניקה ממקום הגבוה. וע\"י שר הטבחים בקדושה הוא כורת את היניקה מריבוי צמצומים, שנעשה עי\"ז שהאדם משפיל את עצמו בדברים גשמיים, והיינו שע\"י האהבה כרשפי אש ורתיחת הדמים בקדושה, נכלה רתיחות הדמים שבלעו\"ז, שזהו מה שתרגם ע\"פ שר הטבחים, רב קטוליא, שענינו הוא כדאיתא בגמרא<sup data-n=\"2651\">34</sup> ע\"פ<sup data-n=\"2652\">35</sup> זובח תודה יכבדנני, כל הזובח את יצרו כו', והיינו שע\"י רתיחות הדמים שבקדושה הרי הוא מכלה את רתיחות הדמים שבלעו\"ז, ובמילא מתבטלת היניקה שמצד ריבוי הצמצומים.\n<b>וזהו</b> חרב של שתי פיות, שהו\"ע העבודה דאהבה בתענוגים ואהבה כרשפי אש. ובכללות הוא ההפרש בין תורה לתפלה, דתורה היא מלמעלה למטה, שעי\"זמכרית היניקה שמצד המקיף, ותפלה היא מלמטה למעלה, בדרך מלחמה, דשעת צלותא שעת קרבא<sup data-n=\"2653\">36</sup>, ועי\"ז מכרית היניקה מריבוי הצמצומים. וזהו חרב דא הוי', דב' האופנים ביניקת הקליפות נכרתים ע\"י הוי' דוקא, דהיניקה שמצד המקיף נכרתת ע\"י הוי', כמ\"ש&lt;19&gt; אם תגביה כנשר משם אורידך נאום הוי', וגם היניקה שמצד ריבוי הצמצומים נכרתת ע\"י שם הוי', שהרי יניקת הקליפות היא מצד ריבוי הצמצומים דשם אלקים דוקא, ובזה גופא אין זה מבחי' אל\"ה, כי אם מבחי' י\"ם, דממ\"ח צירופים אלו יונקים אדמת בני חם<sup data-n=\"2654\">37</sup>, אך מצד הגילוי דשם הוי' מתבטלת היניקה. וזהו חרב דא הוי', שהוא חרב של שתי פיות להכרית יניקתם בב' האופנים. ובעבודה הוא העבודה דתורה והעבודה דתפלה, ויש מעלה בתפלה שהיא מלמטה למעלה על התורה שהיא מלמעלה למטה, וע\"ד המעלה דאתכפיא על אתהפכא, וכמו מעלת הבע\"ת על צדיקים, שלכן משיח אתא לאתבא צדיקיא בתיובתא<sup data-n=\"2655\">38</sup>. וזהו כל הקורא ק\"ש כו' כאילו אוחז חרב של שתי פיות, דק\"ש נקראת חרב פיפיות להכרית היניקה מג' שרי פרעה, שעי\"ז היא היציאה ממצרים, ולכן מסיים בק\"ש אני הוי' אלקיכם אשר הוצאתי אתכם מארץ מצרים גו'<sup data-n=\"2656\">39</sup>.\nה) <b>וביאור</b> ענין החמשה כלי זיין בפרטיות בעבודה שבלב זו תפלה<sup data-n=\"2657\">40</sup>, הנה סייף שהוא חרב קאי על פסוקי דזמרה, מלשון לזמר עריצים<sup data-n=\"2658\">41</sup>, דהיינו שע\"י ההתבוננות בענין יהללו את שם הוי' כי הוא צוה ונבראו<sup data-n=\"2659\">42</sup>, הרי הוא מזמר את העריצים. וקשת הוא שמו\"ע, כמ\"ש<sup data-n=\"2660\">43</sup> בחרבי ובקשתי, ותרגם בצלותי ובבעותי, דמעלת הקשת הוא שפועל גם למרחוק, והוא ע\"י שמושכין את היתר, דכל מה שימשכו את היתר למטה יותר יגיע החץ למרחוק יותר, ועוד מעלה יש בקשת על סייף, שהוא הורג גם לשונא שאינו רואהו. וכמו\"כ הוא גם בהעבודה דשמו\"ע, דשמו\"ע הוא בקשה, הנה כל מה שיורגש אצלו החסרון ביותר, אזי תהי' הבקשה ומילוי הבקשה בעומק יותר, והיינו דכל שיתמרמר יותר על ריחוקו מאלקות, שזהו שמושכין את היתר למטה יותר, עי\"ז יהי' מילוי הבקשה בעומק יותר. ועוד זאת, שהורג גם לשונא שאינו רואהו, שהו\"ע דקות הרע, שהרי קודם התפלה הנה דרך איש ישר בעיניו<sup data-n=\"2661\">44</sup>, שהרי לא עבר על מ\"ע ומל\"ת, ובפרט כשלמד תורה מעט ומקיים מצוות הרי הוא צדיק בעיני עצמו, אמנם, כשמגיע להעבודה דשמו\"ע, כאַפּט ער זיך שיש בו רע ומתחרט עליו, שזוהי הבקשה בשמו\"ע סלח לנו, ואחרי שמו\"ע אומריםאשמנו בגדנו וכו', בכל פרטי כ\"ב האותיות, שעי\"ז מוציאים החיות מכ\"ב האותיות שמהם היא יניקת הלעו\"ז, כמבואר במ\"א<sup data-n=\"2662\">45</sup>. וכל זה הוא לפי שהגילוי הוא ביותר, דבשמו\"ע אומרים ברוך אתה הוי', שהו\"ע ההמשכה דהוי' שלמעלה מהשתלשלות, וההמשכה הוא באלקינו מלך העולם, ולכן מצד ריבוי האור מעבירים גם את דקות הרע, וכמ\"ש<sup data-n=\"2663\">46</sup> וגם את הצרעה וגו' אל גדול ונורא, דלפי שהוא אל גדול, לכן נכרת גם את דקות הרע. ואלה שהוא מקל לרדות<sup data-n=\"2664\">47</sup>, ענינו בעבודה הוא כמארז\"ל&lt;12&gt; לעולם ירגיז אדם יצ\"ט על יצה\"ר, ופירוש לעולם הוא לפי ששרש הרע וטוב הוא מבחי' גבורות וחסדים, ומצד הגבורות צריך להיות תמיד ענין הרוגז. ורומח הוא ק\"ש, דרמח הוא רמ\"ח תיבין דק\"ש<sup data-n=\"2665\">48</sup>, והוא\"ו רומז על הוא\"ו תיבות דשמע וברוך שם. והנה ההפרש בין אלה לרומח הוא, שע\"י רומח נעשה נטילת החיות לגמרי, משא\"כ באלה שהוא הכאה בלבד. וענינו בעבודה, דבמדות יש ב' בחי', מדות דהיתר ומדות דאיסור, הנה המדות דאיסור צריך להחרימם מכל וכל ע\"י רומח, משא\"כ במדות דהיתר צריך להיות האלה, להכותם ולהשתמש בהם בקדושה. והתריס שענינו להגן בעד החצים ובליסתראות, ענינו בעבודה הוא לבישת הטו\"ת קודם התפלה ובשעת התפלה, דהנה בשעת התפלה יש התגברות הלעו\"ז לבלבלו מעבודתו, כדאיתא בתניא<sup data-n=\"2666\">49</sup> שהוא כמשל ערל העומד לנגדו לבלבלו מעבודתו, ועל זה הוא ענין לבישת טו\"ת<sup data-n=\"2667\">50</sup> שנעשים לבושים להנפש להגן בעד החצים כו'.\n<b>ומעתה</b> יובן הטעם שאמרו שבשבת לא יצא האיש בסייף, דהנה בעבודה דששת ימי החול הנה שעת צלותא היא שעת קרבא להלחם עם הרע שבנפשו, אמנם בערב שבת עם חשיכה נפרד הרע מן הטוב, וכמאמר<sup data-n=\"2668\">51</sup> וכל דינין מתעברין מינה ולית שולטנא כו' ואיהי אתפרשת כו', ולכן בשבת אינו שייך ענין מלחמה הנ\"ל, וזהו שאמרו לא יצא האיש בחמשה כלי זיין הנ\"ל, כי בשבת אינו זמן המלחמה הנ\"ל. אבל רבי אליעזר אומר שמ\"מ תכשיטין הן לו, והיינו שהבירורים דששת ימי החול הנה גם בשבת הם תכשיטין להתקשט בהן, דהתפלות דימי החול מתעלים בהתפלה דשבת, והוא קישוט להאדם שנצח בימי החול. וחכמים אומרים שאינם תכשיטים, וראי' על זה, שהרי לעתיד כתיב וכתתו חרבותם לאתים, ואם היו תכשיט היו מתקשטים בהם לעתיד, אלא שאינם תכשיט כלל, ואדרבה כו', וטעם הדבר הוא לפי שכל המתאבק עם מנוול מתנוול ג\"כ<sup data-n=\"2669\">52</sup>, ולכן אין זה תכשיט כלל.<b>ועפ\"ז</b> יובן ההפרש בין גאולת מצרים לגאולה העתידה, דעם היות שבגאולה העתידה כתיב וכתתו חרבותם לאתים, מ\"מ, בגאולת מצרים כתיב וחמושים עלו, והיינו לפי שלעתיד כתיב<sup data-n=\"2670\">53</sup> ואת רוח הטומאה אעביר מן הארץ, משא\"כ בגאולת מצרים הי' הרע בתקפו עדיין, כמבואר בתניא<sup data-n=\"2671\">54</sup> בענין כי ברח העם<sup data-n=\"2672\">55</sup> שזהו לפי שהרע הי' בתקפו, אלא שכיון שהגאולה היתה צריכה להיות כהרף עין<sup data-n=\"2673\">56</sup>, לא רצו להתעסק (טשעפען זיך) עם זה, וכיון שהי' עדיין רע לכן הצטרכו לכלי זיין, משא\"כ לעתיד שאת רוח הטומאה אעביר מן הארץ, אזי וכתתו חרבותם לאתים.\n<b>והנה</b><sup data-n=\"2674\">57</sup> בגאולה העתידה יהי', בכללות, ב' מדריגות, בזמן וגם בנפש. דלעמי הארץ או כמ\"ש באגה\"ק לערב רב<sup data-n=\"2675\">58</sup>, ובהתחלת זמן הגאולה יהי' כן בכל ישראל, ע\"ד מרז\"ל<sup data-n=\"2676\">59</sup> אין בין העוה\"ז לימות המשיח אלא שעבוד מלכיות בלבד ויהי' צורך בחרב כו', אמנם ת\"ח וכמ\"ש באגה\"ק לישראל שאינם מערב רב, ואח\"כ יהי' כן בכלל, אשר את רוח הטומאה אעביר מן הארץ לא יצטרכו לחרב, ועז\"נ וכתתו חרבותם לאתים גו'. וזהו אומרו רוממות אל בגרונם וחרב פיפיות בידם, דאף אשר מדבר בלעתיד לבוא, כמ\"ש בפתיחת המזמור שירו להוי' שיר חדש תהלתו בקהל חסידים וכנ\"ל, מ\"מ הנה בתחילת זמן הגאולה יהי' צורך בכלי זיין. וע\"ז אומר שיהי' רוממות א-ל בגרונם וחרב פיפיות בידם, לעשות נקמה בגוים, שיהיו עוד הגוים קודם שיתבררו לעבדו שכם אחד, וגם ע\"ד המבואר בלקו\"ת<sup data-n=\"2677\">60</sup> ע\"פ כל גוים סבבוני<sup data-n=\"2678\">61</sup> שהוא גוי אשר בקרבך<sup data-n=\"2679\">62</sup> הגוף ונה\"ב, ויצטרכו לחרב פיפיות בידם. ואח\"כ בשלימות הגאולה וכתתו חרבותם לאתים גו' ולא ישא גוי אל גוי חרב, כי את רוח הטומאה אעביר מן הארץ, ונתתי שלום בארץ<sup data-n=\"2680\">63</sup> ע\"י שר שלום<sup data-n=\"2681\">64</sup> דוד<sup data-n=\"2682\">65</sup> מלך המשיח, בהגאולה העתידה, במהרה בימינו.\n**********",[["2617","*","\"המאמר שנאמר בש\"פ מטות-מסעי ש\"ק מברכים חדש מנחם-אב . . הוא המאמר לא יצא האיש לא בסייף [תרל\"ב] . . עם איזה שינויים, ובהוספת התחלה וסיום\"*.\nהתחלת וסיום המאמר – הוגהו ע\"י כ\"ק אדמו\"ר שליט\"א."],["2618","1","תהלים קמט, א."],["2619","2","ביל\"ש ברכה (עה\"פ ויאמר ה' מסיני): וחתם . . רוממות א-ל בגרונם. וראה רשימות הצ\"צ (יהל אור) לתהלים ע' תש בסופו."],["2620","3","בשלח טו, א."],["2621","4","ראה ג\"כ תוד\"ה ונאמר פסחים (קטז, ב) – ומשרז\"ל (ע\"ז כד, ב) וישרנה כו' שיר חדש עיין רשימות הצ\"צ (יהל אור) לתהלים ע' תשא."],["2622","5","שה\"ש א, ה."],["2623","6","ישעי' ב, ד."],["2624","7","עד כאן הוגה ע\"י כ\"ק אדמו\"ר שליט\"א.\n*) <i>לשון ה</i>\"<i>פתח דבר</i>\"<i> למאמר ד\"ה לא יצא האיש לא בסייף תרל\"ב שיצא לאור בקונטרס בפ\"ע (קה\"ת – ה' מנחם אב תשט\"ז)</i>,<i> ואח\"כ בסה\"מ תרל\"ב ע' נב ואילך</i>,<i> בתוספת איזה מ\"מ והערות מכ\"ק אדמו\"ר שליט\"א (חלקם נעתקו לקמן)</i>."],["2625","8","שם סג, א."],["2626","9","שבת שם."],["2627","10","בשלח יג, יח."],["2628","11","ראה ד\"ה לא יצא האיש הנ\"ל: \"בירושלמי שלפנינו הגי' חמשה עשר, אמנם בקה\"ע גורס חמשה, ופי' שלמד מל' וחמושים ל' חמשה, וביפ\"מ כ' בפי' שהגי' היא חמשה, ושהכי איתא במכילתא\". ובהערה שם: \"כן הוא ג\"כ בילקוט במקומו ובמכילתא דרשב\"י. וראה ג\"כ הדר זקנים עה\"פ\"."],["2629","12","ברכות ה, א."],["2630","13","ח\"ג ערב, א. עדר, ב."],["2631","14","שמואל-א ב, יו\"ד."],["2632","15","סוטה ה, א."],["2633","16","סוף מנחות. ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310027\" data-slug=\"tanya\" data-id=\"3401310027\">תניא פכ\"ב</a> ופכ\"ד. וצע\"ק בדרוש תער השכירה פ\"ח [<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650051\" data-slug=\"or-hatorah-hb\" data-id=\"8316650051\">אוה\"ת נ\"ך כרך ב ע' תשפ</a> ואילך]."],["2634","17","ע\"פ תהלים קלט, יב."],["2635","18","משלי ל, כח."],["2636","19","עובדי' א, ד."],["2637","20","משלי ל, יט. עפמש\"כ בעמק המלך שער עולם התהו פל\"ב שמדבר במלכות אדום. וראה ג\"כ ל\"ת להאריז\"ל עה\"פ משלי ל, יט."],["2638","21","האזינו לב, ט."],["2639","22","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310076\" data-slug=\"tanya\" data-id=\"3401310076\">תניא אגה\"ת פ\"ה</a>-וא\"ו."],["2640","23","ראה זח\"ב קסב, ב."],["2641","24","ל\"ת להאריז\"ל ר\"פ וישב. שם ר\"פ שמות. ועוד."],["2642","25","ירמי' ב, כז."],["2643","26","ראה תו\"א נח, ב ואילך. קב, ג ואילך."],["2644","27","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310006\" data-slug=\"tanya\" data-id=\"3401310006\">תניא פ\"א (ה, סע\"ב</a>)."],["2645","28","ראה זח\"ג רלה, ב."],["2646","29","זח\"ג קפח, ב."],["2647","30","משלי ט, ה."],["2648","31","בחוקותי כו, כו."],["2649","32","משלי ד, ה."],["2650","33","מאמר ח ואילך."],["2651","34","סנהדרין מג, ב."],["2652","35","תהלים נ, כג."],["2653","36","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380606\" data-slug=\"likkutei-torah\" data-id=\"4001380606\">ראה זהר ח\"ג רמג, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380855\" data-slug=\"likkutei-torah\" data-id=\"4001380855\">ח\"א רמ, ב</a>. תקוני זהר תי\"ג (כט, ב). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380859\" data-slug=\"likkutei-torah\" data-id=\"4001380859\">לקו\"ת בלק עב, א</a>. תצא לד, ג. לה, ג."],["2654","37","ראה ס' הליקוטים להאריז\"ל ר\"פ בא. פע\"ח שער חהמ\"צ פ\"ה. שער הכוונות ענין הפסח דרוש א. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370486\" data-slug=\"torah-or\" data-id=\"3901370486\">תו\"א הוספות קט, ד</a>."],["2655","38","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381329\" data-slug=\"likkutei-torah\" data-id=\"4001381329\">ראה זח\"ג קנג, ב</a>. וראה לקו\"ת דרושי שמע\"צ צב, ב. שה\"ש נ, סע\"ב. מאמרי אדמו\"ר האמצעי ויקרא ח\"א ע' שיב. וש\"נ."],["2656","39","שלח טו, מא."],["2657","40","תענית ב, א."],["2658","41","ראה ישעי' כה, ה."],["2659","42","תהלים קמח, ה."],["2660","43","ויחי מח, כב. ות\"א שם."],["2661","44","משלי כא, ב."],["2662","45","ראה סהמ\"צ להצ\"צ לח, ב."],["2663","46","עקב ז, כ-כא."],["2664","47","ראה תו\"א ס\"פ וישב. סד\"ה ואתה הרם (המשך והחרים תרל\"א). המשך וככה תרל\"ז פקי\"ט. קכח. ועוד."],["2665","48","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380869\" data-slug=\"likkutei-torah\" data-id=\"4001380869\">זח\"ב ערב, א</a>. וראה לקו\"ת תצא לח, א."],["2666","49","פכ\"ח."],["2667","50","ראה ג\"כ קובץ מכתבים לאדמו\"ר (מהורש\"ב) נ\"ע מכתב א [אגרות-קודש אדמו\"ר מהורש\"ב ח\"א ע' כא]."],["2668","51","זח\"ב קלה, ב."],["2669","52","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310033\" data-slug=\"tanya\" data-id=\"3401310033\">תניא ספכ\"ח</a>."],["2670","53","זכרי' יג, ב."],["2671","54","פל\"א."],["2672","55","בשלח יד, ה."],["2673","56","ראה מכילתא ופרש\"י בא יב, מא."],["2674","57","מכאן עד סוף המאמר הוגה ע\"י כ\"ק אדמו\"ר שליט\"א."],["2675","58","ראה זח\"ג קכה, א. עבודת הקודש ח\"ב פל\"ח. אגה\"ק סכ\"ו. – ועפי\"ז יש ליישב דברי הרמב\"ם הל' תשובה פ\"ח ה\"ז ובהל' שבת רפי\"ט דאין יוצאין בשבת ברומח וסייף וקשת ואלה ותריס ממש\"כ בהל' תשובה ספ\"ט – דלכאורה סותר להנ\"ל. וראה מפרשי הרמב\"ם שם בפ\"ח. וראה ג\"כ סנה' (צא, א) כאן לימוה\"מ כאן לעוה\"ב כו' כאן במחנה צדיקים כאן במחנה שכינה. ואכ\"מ."],["2676","59","ברכות לד, ב."],["2677","60","דברים צ, ד."],["2678","61","תהלים קיח, יו\"ד."],["2679","62","ע\"פ נצבים כח, מג."],["2680","63","בחוקותי כו, ו."],["2681","64","ראה תרגום לישעי' ט, ה."],["2682","65","ראה קובץ מכתבים לאדמו\"ר (מהורש\"ב) נ\"ע מכתב ט בסופו [אגרות-קודש אדמו\"ר מהורש\"ב ח\"א ע' שיב], דוד ולא קאמר בן דוד כו' וכמ\"ש ועבדי דוד מלך עליהם."]]],[1500390041,"<h3>בס\"ד. יום ד', חמשה עשר באב ה'תשל\"ה<sup data-n=\"2683\">*</sup></h3>\n<b>לא</b> היו ימים טובים לישראל כחמשה עשר באב וכיום הכפורים<sup data-n=\"2684\">1</sup>, וצריך להבין מהו טעם הדמיון והצד השוה שבין ט\"ו באב ליוהכ\"פ<sup data-n=\"2685\">2</sup>. גם צריך להבין מה שמאמר זה (לא היו יו\"ט כו') הוא בסיום וחותם<sup data-n=\"2686\">3</sup> מס' תענית, והרי ימים טובים הו\"ע השמחה, היפך ענין התענית. ובפרט שמהלשון לא היו יו\"ט לישראל כחמשה עשר באב כו' מוכח שהשמחה שבט\"ו באב (ויוהכ\"פ) היא ביותר מהשמחה שביו\"ט אף שהיא מ\"ע מה\"ת, ושמחת בחגיך<sup data-n=\"2687\">4</sup>, ולפי\"ז תוקשה יותר השייכות דענין זה ל(סיום וחותם) מס' תענית דוקא. והנה השייכות דט\"ו באב לענין תענית מוכח ג\"כ ממה שמקשר (במשנה) חמשה עשר באב ויום הכפורים, שיוהכ\"פ הוא התענית היחידי שמן התורה, ותענית זה הוא מיוחד ושונה משאר התעניות גם בזה שד' הצומות (וכן הצומות שנמנו במגילת תענית, וכמה מהם הובאו בטור<sup data-n=\"2688\">5</sup>) יהפכו לששון ולשמחה<sup data-n=\"2689\">6</sup>, משא\"כ התענית דיוהכ\"פ שיהי' גם לעתיד. ומזה שמקשר (במשנה) ט\"ו באב עם יוהכ\"פ, מוכח, שהיו\"ט דט\"ו באב שייך הוא לא רק לענין התענית שבמס' תענית [שלכן המאמר לא היו יו\"ט לישראל כט\"ו באב הוא בסיום וחותם מס' תענית], אלא גם להתענית דיוהכ\"פ.\n<b>והנה</b> הטעם מה שט\"ו באב הוא יו\"ט [דלכאורה אינו מובן, וכמו שמקשה בגמרא<sup data-n=\"2690\">7</sup>: בשלמא יום הכפורים משום דאית בי' סליחה ומחילה, יום שניתנו בו לוחות האחרונות, אלא ט\"ו באב מאי היא], מובא בדרושים<sup data-n=\"2691\">8</sup> מפע\"ח<sup data-n=\"2692\">9</sup>, לפי שאז הוא מילוי הלבנה. ומקשה על זה בהדרושים, והרי בכל חודש יש יום ט\"ו (שאז הוא מילוי הלבנה), ומהי המעלה דט\"ו באב דוקא, וממ\"ש לא היו יו\"ט כו' כחמשה עשר באב משמע שהוא למעלה גם מט\"ו בניסן (פסח) וט\"ו בתשרי (סוכות). והנה אחד הטעמים בגמרא שם<sup data-n=\"2693\">10</sup> (על מה שט\"ו באב הוא יו\"ט) הוא, מפני שאז תשש כוחה של חמה.ואינו מובן, הרי תשישת כוחה של חמה הו\"ע שבמאורות השמים ואינו נוגע לעניני ופעולות האדם (כשאר הטעמים שבגמרא שם), וא\"כ מהו היו\"ט כשתשש כוחה של חמה. והגם שמזה שתשש כוחה של חמה (אף שהו\"ע שבמאורות השמים) ישנן תוצאות בנוגע לענינים ופעולות שבארץ, וכדאיתא בגמרא שם ולא היו כורתין עצים למערכה כו', הרי מלשון הגמרא (מחמשה עשר באב ואילך תשש כוחה של חמה) משמע שהיו\"ט (והשמחה) דחמשה עשר באב הוא מצד זה גופא שתשש כוחה של חמה (ולא רק מצד התוצאות שעי\"ז), וא\"כ צ\"ל, שגם זה דתשש כוחה של חמה שייך הוא לעבודת האדם. שזהו ההשתוות דט\"ו באב ויוהכ\"פ, דכמו שהכפרה דיוהכ\"פ נעשית ע\"י עבודת האדם [דהגם שעיצומו של יום מכפר<sup data-n=\"2694\">11</sup>, מ\"מ, ע\"י עבודת האדם הכפרה היא ביתר שאת וביתר עוז<sup data-n=\"2695\">12</sup>. ויתרה מזו, שגם הכפרה הבאה מצד עיצומו של יום היא דוקא כאשר האדם מקיים (האַלט זיך אָן) עיצומו של יום, שהרי אכרת דיומא יו\"כ אינו מכפר<sup data-n=\"2696\">13</sup>], עד\"ז הוא גם בנוגע לתשש כוחה של חמה שבט\"ו באב [שגם לאחרי שתשש כו' יש כוחה של חמה, ורק שתשש כוחה], הו\"ע השייך לעבודת האדם.\n<b>ונקודת</b> הביאור בהמעלה דט\"ו באב, הגם שבכל ט\"ו בחודש הוא מילוי הלבנה, מבואר בהדרושים<sup data-n=\"2697\">14</sup>, שזהו לפי שהעלי' דט\"ו באב באה לאחרי הירידה דט\"ב. והענין הוא, הנה איתא בילקוט<sup data-n=\"2698\">15</sup>, עלה ארי' במזל ארי' והחריב אריאל כו' על מנת שיבוא ארי' [זה הקב\"ה דכתיב בי'<sup data-n=\"2699\">16</sup> ארי' שאג מי לא יירא], במזל ארי' [והפכתי אבלם לששון<sup data-n=\"2700\">17</sup>], ויבנה אריאל כו'. והיינו<sup data-n=\"2701\">18</sup>, שהגלות והחורבן שהי' במזל ארי' (בחודש החמישי) הוא אך ורק בכדי (על מנת) שיבוא ארי' כו' ויבנה אריאל, ביהמ\"ק השלישי, שהוא נעלה יותר מבית ראשון ושני. כי העילוי דביהמ\"ק השלישי (שהוא נעלה יותר מבית ראשון ומבית שני) בא דוקא ע\"י קדימת הגלות וכו'. וזהו<sup data-n=\"2697\">14</sup> המעלה דט\"ו באב על ט\"ו שבכל חודש, גם על ט\"ו בניסן (פסח) וט\"ו בתשרי (סוכות), כי מכיון שהעלי' דט\"ו באב באה לאחרי הירידה הגדולה דט\"ב (עלה ארי' כו' והחריב אריאל), לכן היא עלי' גדולה ביותר. וכידוע<sup data-n=\"2702\">19</sup> הכלל בעליות וירידות, שלפי\"ע הירידה כן היא העלי'. והגם שגם העלי' דט\"ו בניסן (פסח) באה לאחרי הירידה דגלות מצרים, הרי אז היו ישראל במעמד ומצב של צדיקים. וגם העלי' דט\"ו בתשרי (סוכות), הגםשהיא באה בהמשך להתשובה דיוהכ\"פ, מ\"מ, מכיון שכללות העבודה דתומ\"צ היא עבודה רוחנית [דהגם שהמצוות נתלבשו בדברים גשמיים, ציצית בצמר גשמי ותפילין בקלף גשמי, מ\"מ הרי ענין המצוות הוא להכניס רוחניות בהגשמיות<sup data-n=\"2703\">20</sup>], הרי הירידה שע\"י החטאים ועוונות (היפך ענין המצוות) היא בנוגע להגשמיות כמו ששייך לרוחניות<sup data-n=\"2704\">21</sup>, ובמילא אין זה עדיין תכלית הירידה, ולכן גם העלי' דסוכות שע\"י התשובה אינה תכלית העלי'. משא\"כ הירידה דט\"ב, ששפך חמתו על העצים ועל האבנים<sup data-n=\"2705\">22</sup> (עצים ואבנים גשמיים), היינו שהירידה (שמצד החטאים) פעלה בהגשמיות דעולם שאין תחתון למטה ממנו, הנה מכיון שהירידה דט\"ב היא ירידה שאין למטה ממנה, לכן גם העלי' דט\"ו באב שלאחרי ירידה זו היא עלי' גדולה ביותר, לפי\"ע עוצם הירידה. וזהו\"ע נחמה בכפליים<sup data-n=\"2706\">23</sup>, ואנכי אנכי הוא מנחמכם<sup data-n=\"2707\">24</sup>, ב\"פ אנכי<sup data-n=\"2708\">25</sup>. ועפ\"ז מובן שהיו\"ט דט\"ו באב הוא נעלה יותר גם מהיו\"ט דיוהכ\"פ. וזהו מה שאמרו לא היו יו\"ט לישראל כט\"ו באב וכיום הכפורים, שמקדים ט\"ו באב ליוהכ\"פ, אע\"פ שהענין דט\"ו באב (לפי כל הטעמים שבגמרא) נתחדש משך כמה שנים לאחרי יוהכ\"פ, וגם בזמני השנה (בכל שנה) יוהכ\"פ (שבחודש תשרי) הוא קודם לט\"ו באב, לפי שהיו\"ט דט\"ו באב הוא נעלה יותר (קודם במעלה) מהיו\"ט דיוהכ\"פ.\n<b>אך</b> עדיין צריך להבין, הרי ושמחת בחגיך הוא מ\"ע מה\"ת, משא\"כ היו\"ט (והשמחה) דט\"ו באב. וגם היו\"ט דיוהכ\"פ אינו מה\"ת [שהרי אין חיוב לשמוח ביוהכ\"פ, ואדרבה<sup data-n=\"2709\">26</sup>, המצוה דיוהכ\"פ היא ועניתם את נפשותיכם<sup data-n=\"2710\">27</sup>. ורק שמכיון שהוא יום סליחה וכפרה, הנה בדרך ממילא מסתעף מזה ענין השמחה], וא\"כ איך אפשר שהיו\"ט (והשמחה) דט\"ו באב ויוהכ\"פ יהי' גדול יותר מהימים טובים שמצוה מן התורה לשמוח בהם. אך הענין הוא, שבהעילוי דקיימא סיהרא באשלמותא ישנם שתי בחינות בכללות. הבחינה דקיימא סיהרא באשלמותא כמו שהיא מצד הסדר ודין התורה [ומזה נשתלשל הסדר דשינויי הלבנה ע\"פ טבע], והבחינה דקיימא סיהרא באשלמותא כמו שהיא מצד עבודת האדם, כמו שהיא למעלה מכמו שהוא ע\"פ דין התורה. כי ישראל הם למעלה מהתורה, שלכן נקראים ישראל בשם חתן והתורה בשם כלה<sup data-n=\"2711\">28</sup>, לפי שישראל הם משפיעים בתורה. דזהו\"ע ברכו בתורה תחילה<sup data-n=\"2712\">29</sup>, שישראל מברכים וממשיכים בתורה מבחינת נותן התורה<sup data-n=\"2713\">30</sup>, וע\"ד דוד הי' מחבר אורייתאבקוב\"ה<sup data-n=\"2714\">31</sup>. וזהו העילוי דט\"ו באב על ט\"ו בניסן וט\"ו בתשרי, כי שלימות הלבנה שבט\"ו בניסן וט\"ו בתשרי הו\"ע קיימא סיהרא באשלמותא שמצד הסדר דתורה, היינו מצד עבודת האדם כמו שהיא במדידה ע\"פ תורה. דהגם שע\"י עבודה זו נעשה עילוי בהעולם, מ\"מ העילוי הוא במדידה ובהגבלה. משא\"כ שלימות הלבנה שבט\"ו באב הו\"ע קיימא סיהרא באשלמותא כמו שהוא מצד העבודה דנש\"י שלמעלה מהתורה, עבודה דבכל מאדך.\n<b>ובכדי</b> לבאר ג' ענינים אלו [העולם כמו שהוא מצד עצמו, דעולם על מילואו נברא<sup data-n=\"2715\">32</sup>. מה שמיתוסף בהעולם ע\"י עבודת האדם כמו שהיא מצד המדידה דתורה. והחידוש שנעשה ע\"י העבודה דבכל מאדך שלמעלה ממדידה (גם מהמדידה דתורה)], מביא בהדרושים<sup data-n=\"2716\">33</sup> פירוש הכתוב<sup data-n=\"2717\">34</sup> ויתרון ארץ בכל היא מלך לשדה נעבד, שיש בזה ג' בחינות. בחינת ארץ כמו שהיא מצד עצמה, היתרון דארץ ע\"י בחינת כל, ובחינת מלך לשדה נעבד שנעלה גם מיתרון ארץ. דהנה יתרון ארץ הוא בחינת שדה (כמו שהיא מצד עצמה) [כי שדה היא בכלל ארץ אלא שלהיותה מהמובחר שבארץ, מה שראוי לזריעה ולצמיחה, לכן היא יתרון ארץ], אמנם מה שמלך לשדה נעבד (העילוי שנעשה בשדה ע\"י עבודה) הוא למעלה מיתרון ארץ. והענין הוא, הנה שדה קאי על ג\"ע, דכמו ששדה היא מהמובחר שבארץ מה שראוי לזריעה וצמיחה (כנ\"ל), כן ג\"ע הוא מהמובחר שבעולם מה שראוי לגילוי אור, היינו לבחינת אור שלמעלה מהאור שמאיר בכללות העולם. דהאור שמאיר בכללות העולם הוא מבחינת המדות, דזהו מה שההתהוות הוא מבחינת ששת ימי הבנין או שבעת ימי הבנין. והגם שבעשרה מאמרות נברא העולם<sup data-n=\"2718\">35</sup> (שבעשרה נכלל גם ג' מוחין), הרי זהו המוחין כמו שהם בהמדות. אבל האור שמאיר בג\"ע הוא (גם) מבחינת ג\"ר. ומטעם זה יש עוד מעלה בג\"ע לגבי כללות העולם, שהגילוי שבעולם הוא בבחינת ידיעת המציאות, ובג\"ע הוא גילוי המהות<sup data-n=\"2719\">36</sup>. וזהו מה שויתרון ארץ גו' הוא בחינת ג\"ע (וכנ\"ל שיתרון ארץ הוא בחינת שדה), כי ג\"ע הוא בחינת העולם כמו שהוא בנין שלם בכל הע\"ס, ז\"ת וג\"ר, בחינת עולם על מילואו נברא. וזהו ג\"כ מ\"ש ויתרון ארץ בכל היא, שהיתרון (והמעלה) בג\"ע לגבי כללות העולם הוא ע\"י כל, כל קאי על ספירת היסוד<sup data-n=\"2720\">37</sup> שנקרא כל על שם חמשים שערי בינה (כל בגימטריא חמשים<sup data-n=\"2721\">38</sup>) הנמשכים בו, ועי\"ז נמשך בו גם מבחינת החכמה, דחו\"ב הן כללות המוחין. ועילוי הנ\"ל שבג\"ע מהשהוא יתרון ארץ [מה שמאיר בו הבחי' דג\"ר, ושמצד זה יש בו גם גילוי המהות] הוא בחינת שדה מצד עצמה. אמנם ע\"י העבודה, מלך לשדה נעבד, נעשה עילוי שלמעלה מבחינת יתרון ארץ. וכדאיתא בזהר<sup data-n=\"2722\">39</sup> מלך לשדה נעבד מאן מלך דא מלך עילאה, שבחינה זו היא למעלה מעולם (גם כמו שהוא בשלימות, יתרון ארץ). כי כל ענין התהוות העולם הוא רק מעשרה מאמרות שראשיתם היא חכמה, ומלך עילאה הוא בחינת הכתר שלמעלה מהשתלשלות.\n<b>והנה</b> מכיון שבחינת הכתר (מלך עילאה) היא למעלה מהשתלשלות, לכן גם העבודה שבאדם הממשכת בחינה זו, צריכה להיות למעלה מהשתלשלות הכחות שבו, בבחינת בכל מאדך. כי ע\"י העבודה דתומ\"צ כמו שהיא בבחינת מדידה והגבלה (השתלשלות שבאדם), נמשך האור שבבחינת השתלשלות. והגם שע\"י העבודה דתומ\"צ (גם כשהעבודה היא במדידה והגבלה) נמשך אור נעלה יותר מהבחי' דג\"ע, וכדמוכח ממ\"ש<sup data-n=\"2723\">40</sup> ויניחהו בג\"ע לעבדה ולשמרה, לעבדה זה רמ\"ח מ\"ע ולשמרה זה שס\"ה מל\"ת<sup data-n=\"2724\">41</sup>, והיינו שהג\"ע אצל אדה\"ר לא הי' בחינת קבלת שכר כ\"א שהג\"ע הי' מקום עבודתו, וע\"י עבודתו בג\"ע המשיך אורות נעלים יותר מהבחי' דג\"ע<sup data-n=\"2725\">42</sup>, מ\"מ, זה מה שנמשך ע\"י העבודה כמו שהיא במדידה ע\"פ תורה הוא רק מה ששייך לעולם, והוא מה שע\"י התורה נעשה קיום העולם, כדאיתא בגמרא<sup data-n=\"2726\">43</sup> אם ישראל מקבלים התורה אתם מתקיימין. אבל המשכת האור שלמעלה מהשתלשלות היא ע\"י העבודה דבכל מאדך דוקא.\n<b>וע\"פ</b> הנ\"ל יובן מה שמקדים בהמאמר הפירוש דבמלך לשדה נעבד להביאור בהמעלה דט\"ו באב על ט\"ו בניסן וט\"ו בתשרי, כי מעלת ט\"ו באב על ט\"ו בניסן וט\"ו בתשרי הוא דוגמת המעלה דמלך לשדה נעבד על בחינת שדה כמו שהיא מצד עצמה. דהנה מעלת הג\"ע (שדה) שהוא בחינת יתרון ארץ, היינו מה שהעולם הוא בשלימות (כנ\"ל), הוא דוגמת קיימא סיהרא באשלמותא. אמנם, שלימות זו היא רק השלימות דעולם, וגם מה שמיתוסף בג\"ע ע\"י העבודה דלעבדה ולשמרה (כמו שהיא במדידה דתורה) הוא רק מה ששייך לעולם, ועד\"ז הוא גם בנוגע לשלימות הלבנה דט\"ו בניסן וט\"ו בתשרי, שמצד ענין התורה. משא\"כ שלימות הלבנה דט\"ו באב, מכיון שהיא באה לאחרי הירידה דט\"ב שירידה זו מעוררת העבודה דבכל מאדך (כמשי\"ת לקמן), היא דוגמת מלך לשדה נעבד, אור שלמעלה מהשתלשלות.\n<b>והנה</b> בכדי לבוא להעבודה דבכל מאדך שלמעלה ממדידה והגבלה, הוא ע\"י התבוננות בהמצרים וגבולים דעולם. כי ע\"י שהוא מרגיש את המצרים וגבולים דעולם, הנה זה גופא מעורר אותו שיצא מהמצרים וגבולים, ושעבודתו תהי' למעלהממדידה והגבלה. וכל מה שמרגיש יותר את המצרים וגבולים, שנוסף להמצרים והגבלות דעולם בכלל ישנם גם דברים המונעים ומבלבלים לעבודת ה', כמו הרעבון והחולי [דכשהאדם הוא רעב וחולה א\"א שיבין וישתכל כו' ולא יוכל לעבוד את ה'<sup data-n=\"2727\">44</sup> (היינו<sup data-n=\"2728\">45</sup> שבכדי לעבוד את ה' כשהוא חולה צריך להשתדלות מיוחדת)], ועאכו\"כ ההעלמות וההסתרים שבזמן הגלות, הנה כל מה שמרגיש יותר את המצרים וגבולים, זה מביא אותו יותר להעבודה דבכל מאדך, היציאה ממיצר וגבול. ובזה יובן מה שמביא בדרוש הנ\"ל את פירוש השני שבזהר, שמלך לשדה נעבד הוא לגריעותא, ששדה הוא בחינת שדה דלעו\"ז (בשדה מצאה<sup data-n=\"2729\">46</sup>), ומלך לשדה נעבד הוא מה שספירת המלכות רגלי' יורדות כו' ומתעלמת בשדה דלעו\"ז, כי ההתבוננות בהענין דמלך לשדה נעבד כמו שהוא לגריעותא, שהו\"ע גלות השכינה [שהסיבה לזה ששכינתא בגלותא הוא הגלות דישראל, מה שגלינו מפני חטאינו], הנה התבוננות זו מעוררת אותו שעבודתו תהי' למעלה ממדידה והגבלה, ועי\"ז נמשך אור שלמעלה מהשתלשלות, מלך לשדה נעבד למעליותא.\n<b>וזהו</b> עלה ארי' במזל ארי' והחריב אריאל כו' על מנת שיבא ארי' במזל ארי' ויבנה אריאל, כי יבא ארי' [זה הקב\"ה דכתיב בי' ארי' שאג מי לא יירא] הו\"ע התגלות הכתר שלמעלה מהשתלשלות&lt;18&gt;, ומכיון שהגילוי שלמעלה מהשתלשלות הוא ע\"י העבודה שלמעלה ממדידה והגבלה, לכן בכדי שיבא ארי' כו' הוצרך להיות עלה ארי' כו', כי המרירות והצער שמצד מיצר הגלות הוא המעורר את העבודה שלמעלה מהגבלה, כנ\"ל. ולכן ע\"י קדימת הגלות דוקא יבא ארי' כו' ויבנה אריאל, ביהמ\"ק השלישי. וזהו גם המעלה דביהמ\"ק דלעתיד על בית ראשון ובית שני, שדוקא בביהמ\"ק השלישי (להיותו אחרי קדימת הגלות האחרון) יהי' בו (עיקר) גילוי בחינת א\"ס שלמעלה מהשתלשלות (יבא ארי'). וזהו הטעם מה שביהמ\"ק דלעתיד יהי' בבחינת נצחיות (משא\"כ בית ראשון ובית שני היו בבחינת הפסק), כי מצד הגילוי דא\"ס שלמעלה מהשתלשלות, אין שייך ענין ההפסק. וזהו מ\"ש<sup data-n=\"2730\">47</sup> מקדש אד' כוננו ידיך הוי' ימלוך לעולם ועד, שהפירוש בזה הוא (כמ\"ש מעמק המלך בדרוש הנ\"ל<sup data-n=\"2731\">48</sup>), דלהיות שמקדש גו' כוננו ידיך, היינו שביהמ\"ק דלעתיד יהי' בידי הקב\"ה בעצמו [היינו בחינת הא\"ס שלמעלה מהשתלשלות] לכן הוי' ימלוך לעולם ועד, שיהי' בבחינת נצחיות.\n<b>והנה</b> הכח שיש בזמן הגלות להעבודה דבכל מאדך שעי\"ז יהי' ביהמ\"ק דלע\"ל, הוא מצד הגילויים דבית ראשון ובית שני שהיו לפני הגלות. שגילויים אלונותנים את הכח להאיר את חשכת הגלות בנר מצוה ותורה אור<sup data-n=\"2732\">49</sup>, ועד שעי\"ז יהי' ולילה כיום יאיר<sup data-n=\"2733\">50</sup> בגאולה העתידה. והטעם לזה (מה שבית ראשון ובית שני נותנים את הכח על העבודה דבכל מאדך שעי\"ז יהי' ביהמ\"ק השלישי) הוא, לפי שגם בבית ראשון ובית שני (אף שהי' בהם הפסק) הי' מעין ביהמ\"ק השלישי. ועד\"ז הוא גם בנוגע למשכן שהי' מעין ביהמ\"ק דלעתיד. דהגם שהמשכן נק' אהל<sup data-n=\"2734\">51</sup>, דירת ארעי (ודלא כהמקדש שנקרא בית<sup data-n=\"2735\">52</sup>, דירת קבע), הרי דוקא המשכן, מכיון שהי' מעשה ידי משה, הוא קיים לעולם<sup data-n=\"2736\">53</sup>. ובזה יובן מה שלאחרי שמביא בדרוש הנ\"ל את הפירוש דעמה\"מ שמקדש אד' כוננו ידיך קאי על ביהמ\"ק דלעתיד הוא מוסיף שהמשמעות מגמרא ומדרשים שקאי על משכן ומקדש (אף שפירוש זה אינו שייך לכאורה לתוכן הענין המבואר בדרוש זה), כי זה שבמקדש אד' כוננו ידיך יש ב' פירושים אלו (שקאי על ביהמ\"ק דלעתיד, ושקאי על משכן ומקדש) הוא<sup data-n=\"2737\">54</sup> לפי שבבית ראשון ובית שני (וכן במשכן) הי' מעין ביהמ\"ק דלעתיד כנ\"ל. ולכן מביא בהמאמר גם הפירוש שמקדש אד' כוננו ידיך קאי על משכן ומקדש, כי בזה מבאר, שהכח שבזה\"ג על העבודה להמשיך את ביהמ\"ק השלישי הוא מבית ראשון ובית שני (וגם ממשכן).\n<b>אמנם</b> עיקר הענין דמקדש אד' כוננו ידיך הוא בביהמ\"ק דלעתיד דוקא. משא\"כ במשכן ומקדש (בית ראשון ובית שני) הוא רק מעין ביהמ\"ק דלעתיד. כי פירוש כוננו ידיך הוא שנעשה בידי הקב\"ה בעצמו, היינו בחינת הכתר שלמעלה מהשתלשלות, וגילוי בחינה זו יהי' בביהמ\"ק דלעתיד, שאז דוקא יהי' אמיתית הענין דקיימא סיהרא באשלמותא<sup data-n=\"2738\">55</sup>, בחינת השלימות שלמעלה מהשתלשלות. דבחינת קיימא סיהרא באשלמותא שבבית ראשון [וכמרז\"ל<sup data-n=\"2739\">56</sup> שביהמ\"ק נבנה ע\"י שלמה, לפי ששלמה הי' בדור ט\"ו לאברהם ואז נתמלא דיסקוס של לבנה], הוא דוגמת בחינת יתרון ארץ, משא\"כ השלימות שבביהמ\"ק דלעתיד הו\"ע מלך לשדה נעבד. ובכדי להמשיך בחינת מלך לשדה נעבד כמו שהוא למעליותא, הוצרך להיות תחילה הגלות, בחינת מלך לשדה נעבד כמו שהוא לגריעותא. וע\"י ירידת המלכות בקצה הכי תחתון, עד שהיא נעבדת לשדה דלעו\"ז, תהי' עליית המלכות בבחינה הכי נעלית, עד שתאיר בה בחינת עתיק. שהטעם לזה שירושלים שהיא בחינת מלכות תיקרא נוה שאנן<sup data-n=\"2740\">57</sup> שקאי על בחינת עתיק, הוא מצד זה שבמלכות תאיר בחינת עתיק<sup data-n=\"2741\">58</sup>.<b>וזהו</b> גם השייכות דט\"ו באב ליום הכפורים. כי ביוהכ\"פ הוא עליית המלכות. דזהו מה שיוהכ\"פ הוא יום שנתחייב בחמש תפלות, שבכל תפלה מתעלית המלכות לבחינה עליונה יותר, ועד שבתפלת נעילה היא מתעלית בבחינת פנימיות עתיק. שלכן אומרים אז הוי' הוא האלקים ז\"פ, ברוך שם ג\"פ ושמע ישראל פ\"א, שזהו מצד עליית המלכות בעתיקא, כמבואר בכ\"מ<sup data-n=\"2742\">59</sup>. וזהו השייכות דט\"ו באב ליוהכ\"פ, כי בט\"ו באב מתעלית המלכות בבחינת פנימיות עתיק, ואדרבה, מכיון שהעלי' דט\"ו באב היא לאחרי הירידה דט\"ב, לכן עליית המלכות דט\"ו באב היא למעלה יותר מהעלי' דיוהכ\"פ, כי אם, בדוגמת העלי' שתהי' בגאולה העתידה ע\"י משיח צדקנו, שילחום<sup data-n=\"2743\">60</sup> מלחמות ה' וינצח [היינו שיצטרך ללחום עם מנגדים העומדים בתוקף כו' וינצח] ויבנה ביהמ\"ק במקומו ויקבץ נדחי ישראל, שיקבץ כל ניצוצות הקדושה, ונדחי ישראל כפשוטו – הענין דקיבוץ גליות, בקרוב ממש בגאולה האמיתית והשלימה ע\"י משיח צדקנו.\n**********",[["2683","*","מאמר זה הוגה ע\"י כ\"ק אדמו\"ר <i>בשעתו</i>, (קודם שנערך וי\"ל בקונטרס ט\"ו באב תשמ\"ט (לעיל ע' קסז ואילך)) – ונמצא בחדרו הק' לאחרי ג' תמוז. ומשנה לא זזה ממקומה."],["2684","1","משנה תענית כו, ב."],["2685","2","וכמו שמקשה הצ\"צ (רשימות לאיכה ריש ע' מד. אוה\"ת נ\"ך כרך ב ע' א'צו)."],["2686","3","להעיר מברכות (יב, א) הכל הולך אחר החתום."],["2687","4","ראה טז, יד. שו\"ע אדה\"ז או\"ח הל' יו\"ט סי' תקכ\"ט ס\"ו. וראה שאג\"א סי' סה. ואכ\"מ."],["2688","5","ושו\"ע או\"ח הל' תעניות סי' תק\"פ."],["2689","6","זכרי' ח, יט. תוספתא סוף תענית. וראה מאמר ד\"ה ציון במשפט תפדה שנה זו (תשל\"ה) הערה 43 (לעיל ע' קכח)."],["2690","7","תענית ל, ב."],["2691","8","ד\"ה נחמו עת\"ר [רישומי דברים דהמאמר – נדפסו בסה\"מ עת\"ר ע' ריח ואילך. והנחה – שם ע' רכא ואילך]."],["2692","9","שער כג (שער חג השבועות) בסופו (בדרוש על ט\"ו באב כו')."],["2693","10","לא, ריש ע\"א."],["2694","11","לפי ההלכה – \"עצמו של יוהכ\"פ מכפר (רק) לשבים\" (רמב\"ם הל' תשובה פ\"א ה\"ג). ומש\"כ בפנים – הכוונה בזה, שאפילו לדעת רבי שיוה\"כ מכפר גם לשאינם שבים (יומא פה, ב. שבועות יג, א) שייך הכפרה דיוהכ\"פ לעבודת האדם (כבפנים)."],["2695","12","ראה יומא שם, שע\"י התשובה מכפר יוהכ\"פ גם על פורק עול וכו'."],["2696","13","שבועות שם. וראה צפע\"נ הל' יבום פ\"ד ה\"כ."],["2697","14","רשימות הצ\"צ לאיכה שבהערה 2. ד\"ה נחמו עת\"ר פ\"י (ס\"ע רכט ואילך)."],["2698","15","ירמי' רמז רנט."],["2699","16","עמוס ג, ח."],["2700","17","ירמי' לא, יב."],["2701","18","ראה רשימות הצ\"צ לאיכה ע' כו (אוה\"ת נ\"ך כרך ב ע' א'נו)."],["2702","19","ד\"ה נחמו הנ\"ל פ\"ח – ב\"רישומי דברים\" שם (ע' ריט) מציין לד\"ה \"לסוסתי תקס\"ב תקס\"ד ו<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381175\" data-slug=\"likkutei-torah\" data-id=\"4001381175\">לקו\"ת</a>\" – והוא בסה\"מ תקס\"ד ע' כה ואילך. לקו\"ת שה\"ש יא, ג."],["2703","20","עיין תניא קו\"א רד\"ה להבין מ\"ש בפע\"ח."],["2704","21","ע\"ד הירידה שע\"י מקור כל החטאים, מעשה העגל."],["2705","22","איכ\"ר פ\"ד, יד. מדרש תהלים עה\"פ עט, א."],["2706","23","ישעי' מ, א. איכ\"ר ספ\"א."],["2707","24","ישעי' נא, יב."],["2708","25","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380902\" data-slug=\"likkutei-torah\" data-id=\"4001380902\">לקו\"ת נצבים מה, ד</a>. דרושי ש\"ש סה, ג."],["2709","26","ראה מס' סופרים פי\"ט ה\"ו. וראה גם שו\"ע אדה\"ז או\"ח סתקפ\"ב ס\"י."],["2710","27","אמור כג, יז."],["2711","28","ראה לקו\"ת ברכה ד\"ה תורה צוה בתחלתו. <i>וש\"נ</i>."],["2712","29","ראה ב\"מ פה, רע\"ב. נדרים פא, א."],["2713","30","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380691\" data-slug=\"likkutei-torah\" data-id=\"4001380691\">לקו\"ת מסעי צא, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380834\" data-slug=\"likkutei-torah\" data-id=\"4001380834\">ראה כט, ג</a>."],["2714","31","ספר הבהיר סנ\"ח (קצו) – הובא בזח\"ג רכב, ב. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380516\" data-slug=\"likkutei-torah\" data-id=\"4001380516\">לקו\"ת שלח נא, א</a>."],["2715","32","ראה ב\"ר פי\"ד, ז. פי\"ג, ג."],["2716","33","ד\"ה נחמו עת\"ר פ\"ג ואילך (ע' רכב ואילך). וראה ביאוה\"ז לאדמו\"ר האמצעי (בהוספות) חיי שרה קכט, ד ואילך."],["2717","34","קהלת ה, ח."],["2718","35","אבות רפ\"ה."],["2719","36","ראה ד\"ה איכה עת\"ר (סה\"מ עת\"ר ע' רטו), שב' המעלות שבג\"ע – מה שמאיר בו ג\"ר, וגילוי המהות – \"הא בהא תליא\"."],["2720","37","ראה זח\"ג רנז, סע\"א (ברע\"מ). פרדס שער יג (שער השערים) ספ\"ו. שער כג (שער ערכי הכינויים) מערכת כל כלה. ל\"ת להאריז\"ל עה\"פ וישב מ, א."],["2721","38","ראה פרדס שם."],["2722","39","ח\"א פ' חיי שרה קכב, א."],["2723","40","בראשית ב, טו."],["2724","41","זהר ח\"א כז, א. ח\"ב קסה, ב. תקו\"ז תכ\"א (סב, א). תנ\"ה (פח, ב)."],["2725","42","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380524\" data-slug=\"likkutei-torah\" data-id=\"4001380524\">לקו\"ת קרח נב, ג</a>."],["2726","43","שבת פח, א."],["2727","44","רמב\"ם הל' דיעות ספ\"ג."],["2728","45","וע\"ד \"מוכן לחסרון\" (שמונה פרקים להרמב\"ם רפ\"ח. וראה גם לח\"מ להל' תשובה פ\"ה ה\"ד). אבל אין לומר שכוונת הרמב\"ם בהל' דיעות שם ב\"ולא יוכל כו'\" היא שאינו יכול כלל – כנראה במוחש שבהשתדלות יכול הוא. ולהעיר מהל' ת\"ת להרמב\"ם פ\"א ה\"ח, ולאדה\"ז פ\"ג ה\"ד."],["2729","46","לשון הכתוב תצא כב, כז. וראה ב\"ב טז, ב – הובא בד\"ה ויהיו חיי שרה תר\"ל פ\"ה (סה\"מ תר\"ל ע' כג) לענין מלך לשדה נעבד."],["2730","47","בשלח טו, יז-ח."],["2731","48","סה\"מ עת\"ר ע' רכ. שם ע' רכח."],["2732","49","משלי ו, כג."],["2733","50","תהלים קלט, יב."],["2734","51","שמואל-ב ז, ו. שהש\"ר פ\"א, טז (ג). <a class=\"ft-cite\" href=\"#/read/torah-or/3901370198\" data-slug=\"torah-or\" data-id=\"3901370198\">תו\"א ויגש מג, ד</a>."],["2735","52","ראה ש\"ב שם. וראה זח\"ב רמא, א."],["2736","53","ראה סוטה ט, סע\"א. מדרש לק\"ט בשלח טו, יז."],["2737","54","ראה לקו\"ש ח\"ג ע' 782, שפירושים שבכתוב אחד שייכים זל\"ז."],["2738","55","ראה ד\"ה פדה בשלום תרע\"ה פשע\"ד (המשך תער\"ב ח\"ב ע' תשסט), שהגילוי בה\"ס האחרונות דמלכות, שהו\"ע קיימא סיהרא באשלמותא (ראה ד\"ה נחמו עת\"ר פ\"ב – ע' רכב) שהי' בימי שלמה, הוא בבחי' המלכות \"כמו שכלולה ביסוד שבה\", ורק לעתיד \"יהי' הגילוי בבחי' מלכות שבמל' עצמה\"."],["2739","56","שמו\"ר פט\"ו, כו. זח\"א קנ, רע\"א. ועוד."],["2740","57","ישעי' לג, כ."],["2741","58","ד\"ה נחמו עת\"ר פ\"ט (ע' קכח), ע\"פ זח\"ג קלז, סע\"א."],["2742","59","ראה מ\"ח סוף מס' יומא. לקו\"ת דרושי ש\"ש סה, ד."],["2743","60","רמב\"ם הלכות מלכים ספי\"א."]]],[1500390042,"<h3>בס\"ד. אור ליום ועש\"ק פ' ואתחנן, ט\"ו באב ה'תשל\"ח<sup data-n=\"2744\">*</sup></h3>\n(הנחה. בלתי מוגה)\n<b>ושננתם</b> לבניך ודברת בם<sup data-n=\"2745\">1</sup>, ולאח\"ז נאמר וקשרתם לאות על ידך גו'<sup data-n=\"2746\">2</sup>, מצות תפילין, עלי' אמרו רז\"ל<sup data-n=\"2747\">3</sup> הוקשה כל התורה כולה לתפילין, שהכוונה בזה היא להמצוות שבתורה<sup data-n=\"2748\">4</sup>, והיינו, שהכתוב מקדים ענין התורה לענין המצוות. וידוע דיוק רבותינו נשיאינו<sup data-n=\"2749\">5</sup>, שבפרשה שני' דק\"ש נאמר<sup data-n=\"2750\">6</sup> וקשרתם אותם לאות על ידכם גו' ולמדתם אותם את בניכם גו', שכתוב זה הוא בסדר הפוך, שמקדים ענין המצוות (מצות תפילין) לענין התורה. גם צריך להבין מהו הטעם שהסדר שתורה קודמת למצוות הוא בפרשה ראשונה דק\"ש, והסדר שמצוות קודמים לתורה הוא בפרשה שני' דק\"ש דוקא. גם צריך להבין דיוק הלשון בנוגע לענין התורה, שבפרשה ראשונה נאמר ושננתם גו', כפירוש רש\"י (ממדרשי רז\"ל<sup data-n=\"2751\">7</sup>) שהוא לשון חדוד, שיהיו מחודדים בפיך שאם ישאלך אדם דבר (הלכה<sup data-n=\"2752\">8</sup>) לא תהא צריך לגמגם בו אלא אמור לו מיד (ורק אח\"כ נאמר ודברת בם), ואילו בפרשה שני' נאמר ולמדתם גו', שלשון זה כולל כל אופני הלימוד (גם אם הלימוד אינו באופן דמחודד בפיך כו').\nב) <b>ויש</b> לבאר זה בהקדם ביאור ענין חמשה עשר באב (שזהו\"ע שהזמן גרמא), דאיתא במשנה<sup data-n=\"2753\">9</sup> לא היו ימים טובים לישראל כחמשה עשר באב וכיום הכפורים (כמבואר בגמרא<sup data-n=\"2754\">10</sup> פרטי הדברים בארוכה). ומבואר בדרושי רבותינו נשיאינו<sup data-n=\"2755\">11</sup>, שמלשון חז\"ל לא היו ימים טובים כו', משמע, שט\"ו באב הוא למעלה גם מהימים טובים שהם פסח שבועות וסוכות. ולכאורה<sup data-n=\"2756\">12</sup>, אפילו את\"ל הביאור במעלת חמשה עשר באב לגבי שבועות, שזהו מצד העילוי דיום חמשה עשר בחודש<sup data-n=\"2757\">13</sup>, שבו קיימא סיהרא באשלמותא<sup data-n=\"2758\">14</sup>, עדיין צריך ביאור והסבר במעלתחמשה עשר באב על חמשה עשר בניסן (פסח) וחמשה עשר בתשרי (סוכות), אע\"פ שבשלשתם ישנו העילוי דיום חמשה עשר בחודש שבו קיימא סיהרא באשלמותא. וידוע הביאור בזה<sup data-n=\"2759\">15</sup>, שמעלת חמשה עשר באב היא להיותו בחודש אב שהתחלתו היא באופן של ירידה גדולה, ועד לירידה אחר ירידה, שזהו\"ע לקו בכפלים, בגלל הירידה במצב הרוחני באופן שחטאו בכפלים<sup data-n=\"2760\">16</sup>. ולכן הנה גם העלי' שלאח\"ז – שבאה לאחרי עבודת התשובה באופן דבכה תבכה<sup data-n=\"2761\">17</sup>, בכי' בכפלים<sup data-n=\"2762\">18</sup> – היא באופן דנחמה בכפלים, ועד לעלי' הכי נעלית<sup data-n=\"2763\">19</sup>, שלא בערך מהעלי' דחמשה עשר בניסן וחמשה עשר בתשרי.\nג) <b>ובפרטיות</b> יותר, הנה גם חמשה עשר בתשרי הוא עלי' שלאחרי הירידה. וכידוע<sup data-n=\"2764\">20</sup> החילוק בין ניסן לתשרי, שענינו של ניסן הוא עבודת הצדיקים, שהרי בצאתם ממצרים היו בנ\"י בדרגא של צדיקים, דגר<sup data-n=\"2765\">21</sup> שנתגייר כקטן שנולד דמי<sup data-n=\"2766\">22</sup>. וזהו שחג הפסח הוא כנגד אברהם אבינו<sup data-n=\"2767\">23</sup>, שמדתו מדת החסד<sup data-n=\"2768\">24</sup>, ועבודתו היתה באופן של השפעה מלמעלה למטה, כמ\"ש<sup data-n=\"2769\">25</sup> ויקרא שם בשם ה' א-ל עולם, והיינו, שהמשיך אלקות בעולם להיות לו ית' דירה בתחתונים<sup data-n=\"2770\">26</sup>, לא רק באופן שהקב\"ה הוא א-ל <i>ה</i>עולם, אלא באופן שאלקות והעולם נעשה כולא חד<sup data-n=\"2771\">27</sup>, שזהו כללות ענין עבודת הצדיקים. משא\"כ תשרי, הרי השם תשרי עצמו הוא בסדר תשר\"ק שהוא מלמטה למעלה<sup data-n=\"2772\">28</sup>, וגם העבודה דחודש תשרי היא עבודת התשובה, שלכן באה לאחרי הקדמת העבודה דחודש אלול, בחרטה על העבר ואח\"כ קבלה טובה על להבא, ועד שבאים לחמשה עשר בתשרי, שקיימא סיהרא באשלמותא, שאז הוא היו\"ט דסוכות, עד להסיום וחותם שלו בשמע\"צ ושמח\"ת<sup data-n=\"2773\">29</sup> (כמבואר בארוכה בהדרושים בענין החילוק שבין ניסן לתשרי).\n<b>אמנם</b> ענין זה שגם חודש תשרי הוא עלי' שלאחרי הירידה, מצד עבודת התשובה שבו, הוא רק בערך ולגבי חודש ניסן, משא\"כ בערך ולגבי חודש אב (שרקבו אב היתה הירידה שלא בערך – חורבן ביהמ\"ק וגלות וכו' – בכל הפרטים), הרי גם העבודה דחודש תשרי שענינה עבודת התשובה היא ע\"ד עבודת הצדיקים. והענין בזה, דהנה, עבודת התשובה שבחודש תשרי היא באופן של הליכה דרגא אחר דרגא, שלכן צ\"ל ההקדמה ד\"ירח ימים\"<sup data-n=\"2774\">30</sup>, כמבואר בלקוטי תורה להאריז\"ל<sup data-n=\"2775\">31</sup> ולקו\"ת לאדמו\"ר הזקן<sup data-n=\"2776\">32</sup> שקאי על העבודה דחודש אלול, שעי\"ז נעשית ההליכה דרגא אחר דרגא עד שבאים להדרגא דראש השנה (שהוא גם הראש דחודש תשרי), ועד שלאח\"ז באים להשלימות דקיימא סיהרא באשלמותא, בימי הסוכות, שהתחלתם בחמשה עשר בחודש. משא\"כ בחודש אב, אין זה באופן של הליכה מדרגא לדרגא, אלא העלי' היא תיכף לאחרי תכלית הירידה דתשעה באב, מן הקצה אל הקצה, ועד שענין הנחמה ישנו כבר בת\"ב עצמו, שזהו שאומרים בתפלת מנחה מנחם ציון ובונה ירושלים, לפי שאז נולד משיח, מושיען של ישראל<sup data-n=\"2777\">33</sup>, שענינו הוא הנקודה והעיקר והעצם דתשובה<sup data-n=\"2778\">34</sup>. והיינו, שהענין דלידת משיח מתחיל באותו היום תומ\"י&lt;<b>א</b>&gt; ובאותו הרגע&lt;<b>ב</b>&gt; של תכלית הירידה, ובאופן שנמשך בגלוי בכמה ענינים שמתחילים לאחרי חצות היום דת\"ב<sup data-n=\"2781\">37</sup>, שהסיבה לכך היא בגלל שזהו זמן לידת משיח. ורק כדי שהגילוי יהי' בשלימות, צריכים להמתין עד חמשה עשר באב<sup data-n=\"2782\">38</sup>. וע\"ד שמצינו בסיבת היו\"ט דחמשה עשר באב להיותו יום שכלו בו מתי מדבר<sup data-n=\"2783\">39</sup>, שעד חמשה עשר באב הי' ספק בדבר, וכאשר קיימא סיהרא באשלמותא, אזי נתברר שכבר כלו מתי מדבר בת\"ב<sup data-n=\"2784\">40</sup>, והם עדה שלימה<sup data-n=\"2785\">41</sup>, שכתוב בהן<sup data-n=\"2786\">42</sup> ואתם הדבקים בהוי' אלקיכם חיים כולכם היום, ועומדים להיכנס לארץ<sup data-n=\"2787\">43</sup>, בגאולה האמיתית והשלימה<sup data-n=\"2788\">44</sup> ע\"י גואל ראשון, הקשורה עם\n<b>&lt;א&gt;</b>) וכמרז\"ל<sup data-n=\"2779\">35</sup> דגעתה פרתו ותומ\"י געתה פעם שני' וא\"ל דנולד מושיען של ישראל.\n<b>&lt;ב&gt;</b>) דלכן קרי לי' מזמור<sup data-n=\"2780\">36</sup> כי בהשריפה <i>כילה</i> חמתו.הגאולה ע\"י משיח צדקנו, שהוא גואל אחרון<sup data-n=\"2789\">45</sup> [כידוע שכל הגלויות נקראו ע\"ש מצרים<sup data-n=\"2790\">46</sup>, לפי שיש בהם הענין דגלות מצרים, ועד\"ז ישנה גאולת מצרים בכל הגאולות<sup data-n=\"2791\">47</sup>, ועל שמה נקראים כל הגאולות<sup data-n=\"2792\">48</sup>, עד לגאולה האחרונה, גאולה האמיתית והשלימה מן גלות זה האחרון, שאין אחרי' גלות<sup data-n=\"2793\">49</sup>, עלי' נאמר<sup data-n=\"2794\">50</sup> כימי צאתך מארץ מצרים אראנו נפלאות]. ולהעיר, שכן הוא גם בנוגע לפרשת השבוע, שתשעה באב והעילוי שבו הוא בפרשת ואתחנן (ובכו\"כ שנים חל גם ט\"ו באב בפרשת ואתחנן), הבאה <i>ברגעא חדא</i> לפ' דברים וחזון. וזהו העילוי דחודש אב אפילו לגבי העבודה דחודש תשרי (ועאכו\"כ לגבי העבודה דחודש ניסן), כי, העבודה דחודש תשרי היא באופן של הליכה מדרגא לדרגא, שתנועה זו שייכת לעבודת הצדיקים, ואילו העלי' דחודש אב היא מן הקצה אל הקצה, שזוהי התנועה דעבודת בעלי תשובה, שהרי ענין התשובה הוא בשעתא חדא וברגע חדא<sup data-n=\"2795\">51</sup>.\n<b>וזהו</b> גם הדיוק במארז\"ל לא היו ימים טובים לישראל כחמשה עשר באב וכיום הכפורים, שבתחילה נזכר חמשה עשר באב ואח\"כ יום הכפורים, להורות שמעלת חמשה עשר באב גדולה יותר ממעלת יום הכפורים, כי, אע\"פ שבנוגע ליוהכ\"פ נתפרש בגמרא<sup data-n=\"2796\">52</sup> שמעלתו היא \"משום דאית בי' סליחה ומחילה\", שהו\"ע עבודת התשובה [ומזה למדים שגם ענינו של חמשה עשר באב הו\"ע התשובה], מ\"מ, גדלה מעלת חמשה עשר באב יותר ממעלת יוהכ\"פ, לפי שבו מודגשת עבודת התשובה בשעתא חדא וברגע חדא, מן הקצה אל הקצה, משא\"כ ביוהכ\"פ שעבודת התשובה שבו באה לאחרי עבודה ארוכה עם כמה פרטים ופרטי פרטים, החל מר\"ח אלול, כנ\"ל.\nד) <b>וביאור</b> כללות הענין, כמובא בהדרושים&lt;15&gt; הכלל שהעלי' היא בערך הירידה, ולכן, כאשר הירידה היא עד למטה מטה ביותר, הנה לפום צערא אגרא<sup data-n=\"2797\">53</sup>, שדוקא אז נעשית העלי' למעלה מעלה ביותר. וע\"ד המבואר בכ\"מ<sup data-n=\"2798\">54</sup>, שכאשר ניצוץ קדושה נמצא למטה מטה, הרי זה גופא מורה ששרשו גבוה גבוה ביותר, כי, כל הגבוה ביותר יורד ונמצא למטה ביותר. וכדאיתא בכתבי האריז\"ל<sup data-n=\"2799\">55</sup> והובא בדרושי רבותינו נשיאינו בכ\"מ<sup data-n=\"2800\">56</sup> בפירוש הכתוב<sup data-n=\"2801\">57</sup> כי לא על הלחם לבדו יחי' האדם כי על כל מוצא פי הוי' יחי' האדם, דאע\"פ שגם באדם ישנו מוצא פי הוי',מ\"מ, דוקא ע\"י מוצא פי הוי' שבלחם שלמטה מן האדם, יחי' האדם עם המוצא פי הוי' שבו, והיינו, לפי שמוצא פי הוי' שבחי (ולמטה מזה) בצומח ודומם, שלמטה מהאדם, שרשו ממקום גבוה יותר, ולכן דוקא ע\"י עבודת האדם בהמוצא פי הוי' שבדצ\"ח להעלותו לשרשו ומקורו (שלמעלה משרש האדם), נעשה עילוי גם בהאדם, \"יחי' האדם\", ע\"ד מרז\"ל<sup data-n=\"2802\">58</sup> ארון נושאיו נשא.\n<b>ועד\"ז</b> הוא בכללות ענין הירידות, החל מהירידה דסדר השתלשלות, ועד לירידת הגלות (כמבואר באגה\"ת<sup data-n=\"2803\">59</sup>), שזהו ענינו של חודש אב ותשעה באב, שאז נעשה ענין הגלות כפשוטו באופן הכי תחתון – שע\"י כל זה באים לעלי' גדולה ביותר, וזהו התכלית דכללות ענין הגלות, שאין זה בשביל ענין של עונש ח\"ו, אלא כדי שיבואו לטהרה, וטהרה מביאה לידי קדושה&lt;<b>ג</b>&gt;, ומקדושה כו' עד לתכלית העלי' (כהסיום בברייתא הידועה<sup data-n=\"2806\">62</sup>) – ביאת אליהו הנביא ותחיית המתים, החל מהענין דתחה\"מ כפי שזוטרא דבכו מחי' מתים<sup data-n=\"2807\">63</sup>, שבכללות הו\"ע עבודת הבירורים, לברר הניצוצי קדושה שנפלו למטה, דמאן דנפיל מדרגי' אקרי מת<sup data-n=\"2808\">64</sup>, וע\"י שמבררם ה\"ה מחי' אותם, ואח\"כ מזכך ומעלה אותם עד לתכלית השלימות, כמצות רצונך<sup data-n=\"2809\">65</sup>. וכאמור לעיל שעילוי זה (שלאחרי הירידה דגלות) נעשה בגלוי כבר בת\"ב בתחלת זמן (ותפלת) מנחה, שאז כילה חמתו כביכול על העצים ועל האבנים&lt;36&gt;, שזה הראה בגלוי גודל האהבה דהקב\"ה, שכל חמתו כילה – לגמרי, שלא נשאר ממנה כלום, ומיד נולד משיח מושיען של ישראל. וכאמור, שענין זה בא לידי גילוי באופן ההנהגה דתשעה באב לאחרי חצות היום. אך עדיין אין זה תכלית שלימות הגילוי, והולך ומתגלה מיום ליום, ככל שהלבנה מתקרבת להמצב דקיימא סיהרא באשלמותא, עד לשלימות הגילוי בחמשה עשר באב, שנעשה יו\"ט גדול ביותר, ועד שלא היו ימים טובים לישראל כחמשה עשר באב.\nה) <b>והנה</b> ע\"פ האמור לעיל שדוקא ע\"י הירידה למטה מטה יכולים לפעול שתהי' העלי' למעלה מעלה, למקום גבוה יותר מהמקום שמשם היתה הירידה, מובן גם מעלת ענין המעשה לגבי ענין התלמוד, שזהו כללות החילוק שבין מצוות (מעשה) לתורה (תלמוד). דהנה, תורה ענינה המשכה מלמעלה למטה, וביחד עם זה,\n<b>&lt;ג&gt;</b>) דפרישות בכלל קדושה<sup data-n=\"2804\">60</sup>, וטהרה וקדושה – חו\"ב<sup data-n=\"2805\">61</sup>.הלא כה דברי כאש גו'<sup data-n=\"2810\">66</sup>, שלכן אין דברי תורה מקבלין טומאה<sup data-n=\"2811\">67</sup>, היינו, שגם כאשר נמצאים למטה, ואפילו אצל מי שהוא במעמד ומצב דהיפך הטהרה, גם שם אינם מקבלים טומאה. משא\"כ מצוות הרי ענינם הוא בדברים גשמיים דוקא<sup data-n=\"2812\">68</sup>, ועד שאפילו המצוות שענינם הוא הבנה והשגה שבמוח או הרגש שבלב, קשורים הם עם אברים הגשמיים, מוח הגשמי ולב הגשמי, ובפרט ע\"פ המבואר בכ\"מ<sup data-n=\"2813\">69</sup>, ששלימות העבודה בקיום מצוות אלו היא כאשר נעשה שינוי גם בהגשמיות דכלי המוח וכלי הלב (כיווץ והתרחבות והתפשטות). וכיון שבמצוות ישנו ענין של ירידה למטה יותר (בגשמיות), לכן על ידם דוקא מגיעים להגבוה גבוה ביותר.\nו) <b>וביאור</b> הענין, דהנה יש ב' דעות<sup data-n=\"2814\">70</sup> (ואלו ואלו דברי אלקים חיים<sup data-n=\"2815\">71</sup>) אם תלמוד גדול או מעשה גדול. וזהו גם החילוק בין ב' הסדרים שבכתוב (כנ\"ל שאלו ואלו דברי אלקים חיים), הסדר בפ' ראשונה דק\"ש, שתחילה נאמר ושננתם ואח\"כ נאמר וקשרתם, כהדעה שתלמוד גדול (שהרי קדימה בתורה מורה על קדימה במעלה), והסדר בפ' שני' דק\"ש, שתחילה נאמר וקשרתם ואח\"כ נאמר ולמדתם, כהדעה שמעשה גדול<sup data-n=\"2816\">72</sup>. והענין בזה, דהנה, ענין התלמוד הוא בפשטות כדי לדעת את המעשה אשר יעשון ואלה אשר לא תעשינה<sup data-n=\"2817\">73</sup> (שזהו כללות ענין המצוות, מצוות עשה ומצוות לא תעשה), ורק אח\"כ אפ\"ל קיום המצוות בפועל. וזהו הטעם שתלמוד גדול, לפי שהלימוד מביא לידי מעשה (כמבואר בהלכות ת\"ת לאדה\"ז<sup data-n=\"2818\">74</sup>). והיינו, שענין התלמוד קשור עם הראש שבאדם, שנקרא בשם ראש לפי שקודם במעלה ומושל ושולט על כל הגוף כולו, שדוגמתו הו\"ע המצוות, רמ\"ח מ\"ע כנגד רמ\"ח אברים ושס\"ה מל\"ת כנגד שס\"ה גידים<sup data-n=\"2819\">75</sup>, שהם למטה מהראש, שלכן צ\"ל תחילה החלטת הראש כיצד תהי' הנהגת הגוף. ורק שכאשר ישנם כבר ב' הענינים דתורה ומצוות, אזי יש מקום לב' דעות מה קדם, לימוד או עשי', ועד לדעה הב' שמעשה גדול, מצד העילוי שע\"י הירידה למטה דוקא (שזהו ע\"ד כללות העילוי דחודש אב, כנ\"ל).\n<b>ואעפ\"כ</b> נאמר ושננתם לפני וקשרתם, תלמוד לפני מעשה, כי, אע\"פ שגדלה מעלת המעשה, מ\"מ, כדי שיוכל להיות ענין המעשה צ\"ל תחילה ענין התלמוד שמביא לידי מעשה. וכמו שהוא בכללות עבודת האדם, דאף שנת\"ל (ס\"ד) שחיות האדם היא דוקא ע\"י מוצא פי הוי' שבלחם שלמטה מן האדם (מצד מעלת הירידה למטה דוקא), מ\"מ, כדי שיחי' האדם ע\"י אכילת הלחם צריך להכין תחילהאת הלחם שיהי' ראוי למאכל אדם, כדאיתא בגמרא<sup data-n=\"2820\">76</sup> אדם מביא חטין חטין כוסס (בתמי'), אלא צריך לעשות החיטים מאכל אדם (ע\"י העזר כנגדו<sup data-n=\"2821\">77</sup>). וכמו\"כ הוא בענין תלמוד ומעשה, שאף שמעשה גדול (מצד מעלת הירידה למטה), מ\"מ, כדי שיוכל להיות ענין המעשה צריך להיות הקדמת התלמוד. ועי\"ז ניתוסף גם בהתלמוד העילוי דמעשה, כשם שניתוסף בהאדם ע\"י אכילת הלחם, כנ\"ל.\nז) <b>וזהו</b> גם הביאור (בדא\"פ) בסדר ב' הפרשיות דק\"ש והשינויים ביניהם. דהנה אמרו רז\"ל<sup data-n=\"2822\">78</sup> (למה) קדמה פרשת שמע לפרשת והי' אם שמוע, והקדימה בסדר הכתובים היא לפי שכן הוא סדר העבודה, וכיון שסדר העבודה הוא שתחילה צ\"ל לימוד התורה, ואח\"כ הלימוד מביא לידי מעשה, לכן בפרשה ראשונה הסדר הוא ושננתם ואח\"כ וקשרתם, שע\"י הלימוד (ושננתם) יודע איך לקיים המצוות (וקשרתם) ומקיימן בשלימותן (וזה נעשה הכנה לקיום המצוות לעת\"ל כמצות רצונך<sup data-n=\"2823\">79</sup>). וזהו ג\"כ דיוק הלשון \"ושננתם\", שיהיו מחודדים בפיך שאם ישאלך אדם דבר הלכה כו', כי, בכדי שהלימוד יביא לידי מעשה, הרי זה רק כאשר הלימוד הוא באופן של לאסוקי שמעתא אליבא דהלכתא<sup data-n=\"2824\">80</sup>. אמנם לאחרי שקדמה פרשת שמע, שכבר ישנו הלימוד (ושננתם) והמעשה הבא על ידו (וקשרתם), אזי באה פרשה שני', שבה הסדר הוא בתחלה וקשרתם גו' ולאח\"ז לימוד התורה. וכיון שהלימוד לאסוקי שמעתא אליבא דהלכתא ישנו כבר לפנ\"ז (שזהו מש\"נ בפרשה ראשונה ושננתם גו' וקשרתם), לכן נאמר כאן \"ולמדתם\" סתם, שכולל כל אופני הלימוד (אפילו האופן דדרוש וקבל שכר<sup data-n=\"2825\">81</sup>).\n<b>ועוד</b> ענין בזה&lt;72&gt;, דהנה ידוע שלעתיד לבוא יהי' מעשה גדול. ולכן הסדר וקשרתם ואח\"כ ולמדתם (מעשה גדול) נאמר בפרשה שני' דוקא, כי, מההחילוקים בין פרשה ראשונה ופרשה שני', שפרשה ראשונה היא בלשון ציווי (בעבר ובהווה), ופרשה שני' היא בלשון ציווי וגם בלשון סיפור (בעתיד), והסיפור הוא שיהי' וסרתם ועבדתם גו'<sup data-n=\"2826\">82</sup>, ואח\"כ יהי' ענין התשובה, שזהו מ\"ש ושמתם את דברי אלה גו'. ולכן נאמר לאח\"ז וקשרתם גו' ולמדתם, כיון שלעת\"ל יהי' מעשה גדול.\nח) <b>וזהו</b> כללות הענין דהאי יומא דקא גרים<sup data-n=\"2827\">83</sup> – חמשה עשר באב – שהוא שלימות העלי' לאחרי הירידה דת\"ב, כפי שנמשך בגילוי בזמן שביהמ\"ק הי' קיים, ועד שאפילו בזמן הגלות ישנם כמה מנהגים בט\"ו באב לפי שבזמן ביהמ\"ק הי' יו\"ט גדול מהרבה טעמים שנאמרו ע\"ז בגמרא (כדאיתא בהשלמה לשו\"ע רבינוהזקן<sup data-n=\"2828\">84</sup>), ובפרי עץ חיים&lt;<b>ד</b>&gt; (המובא בדרושי רבותינו נשיאינו ד\"ה נחמו&lt;11&gt;) מונה ז' מעלות טובות של אותו יום המכונה ליסוד שהוא ז'. וע\"י כ\"ז בא ט\"ו באב למעלתו ומדרגתו כמו שיהי' לעת\"ל, שאז יתגלה גודל העילוי שהי' בהירידה בגלות, ואז יהי' גם מעשה גדול.\n<b>וכן</b> תהי' לנו בקרוב ממש, שע\"י עבודת התשובה בזמן הגלות (כמרומז בפרשה שני' דק\"ש בלשון עתיד), יקויים מ\"ש<sup data-n=\"2829\">85</sup> ושב הוי' אלקיך את שבותך ורחמך ושב וקבצך מכל העמים גו', היינו, ששכינתא שבגלותא<sup data-n=\"2830\">86</sup> תשוב מהגלות יחד עם בנ\"י<sup data-n=\"2831\">87</sup>, ובאופן שאתם תלוקטו לאחד אחד בני ישראל<sup data-n=\"2832\">88</sup>, שהקב\"ה מלקט את כל אחד ואחד מישראל<sup data-n=\"2833\">89</sup> – ע\"י ה\"אחד\" שבו, ומוליכו לקבל פני משיח צדקנו, בנערינו ובזקנינו בבנינו ובבנותנו<sup data-n=\"2834\">90</sup>, וכספם וזהבם אתם<sup data-n=\"2835\">91</sup>, עם כל הבירורים וכל הניצוצי קדושה, ועד ונצלתם גו'<sup data-n=\"2836\">92</sup>, שיבררו את הכל, ואת רוח הטומאה אעביר מן הארץ<sup data-n=\"2837\">93</sup>, ויראו בגלוי ש\"לא היו ימים טובים לישראל כחמשה עשר באב\", למטה מעשרה טפחים, בירושלים עיר הקודש ובארץ הקודש בכלל&lt;<b>ה</b>&gt;, בקרוב ממש, בביאת משיח צדקנו.\n**********\n<b>&lt;ד&gt;</b>) ובש\"ס&lt;52&gt; מונה ששה (מהם).\n<b>&lt;ה&gt;</b>) להעיר משתי הגירסות (בסוף תענית): (שבהם בנות) ירושלים, ישראל.",[["2744","*","במאמר זה תיקן כ\"ק אדמו\"ר שליט\"א כו\"כ תיקונים."],["2745","1","פרשתנו ו, ז."],["2746","2","שם, ח."],["2747","3","קידושין לה, א."],["2748","4","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061287\" data-slug=\"likkutei-sichot\" data-id=\"1300061287\">לקו\"ש ח\"ו ע' 277</a> בהערה."],["2749","5","ד\"ה ושננתם במאמרי אדה\"ז תקס\"ז ע' דש ואילך. ועם הגהות כו' – אוה\"ת פרשתנו ע' רלח ואילך. ע' רנב ואילך. וראה גם שם ס\"ע רפא. ח\"ה ע' ב'ט. ע' ב'יב."],["2750","6","עקב יא, יח-יט."],["2751","7","ספרי עה\"פ. קידושין ל, סע\"א."],["2752","8","ראה תוד\"ה אלא – קידושין שם. הל' ת\"ת לאדה\"ז פ\"ב ס\"ג."],["2753","9","תענית כו, ב."],["2754","10","שם ל, ב ואילך. וראה גם ב\"ב קכא, א ואילך."],["2755","11","ד\"ה נחמו עת\"ר (סה\"מ עת\"ר ע' ריח. ע' רכא)."],["2756","12","ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450626\" data-slug=\"or-hatorah-hb\" data-id=\"8316450626\">אוה\"ת</a> פרשתנו ח\"ו ע' ב'קצז ואילך; נ\"ך ח\"ב ע' א'צו. סה\"מ עת\"ר שם."],["2757","13","פרי עץ חיים סוף שער חג השבועות – דרוש לט\"ו באב."],["2758","14","זהר ח\"א קנ, רע\"א. ח\"ב פה, א."],["2759","15","אוה\"ת שם. סה\"מ עת\"ר שם ע' רכ. ע' רכט ואילך."],["2760","16","איכ\"ר ספ\"א. יל\"ש ישעי' רמז תמה."],["2761","17","איכה א, ב."],["2762","18","ראה סנהדרין קד, ב. ועוד. אוה\"ת נ\"ך שם ע' א'נ ואילך."],["2763","19","אוה\"ת נ\"ך שם וסה\"מ עת\"ר שם ע' רכו – עפ\"י ד\"ה לסוסתי תקס\"ד (מאמרי אדה\"ז תקס\"ד ע' כה ואילך)."],["2764","20","ראה אוה\"ת בא ע' רנז ואילך."],["2765","21","יבמות כב, א. וש\"נ."],["2766","22","ראה שם מו, א ואילך. כריתות ט, א. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181128\" data-slug=\"likkutei-sichot\" data-id=\"1300181128\">לקו\"ש חי\"ח ע' 119</a> הערה 26. חכ\"א ע' 63 ובהערה 15."],["2767","23","זח\"ג רנז, ב."],["2768","24","ראה ספר הבהיר סקצ\"א. השמטות לזח\"א רסד, ריש ע\"ב. ובכ\"מ."],["2769","25","וירא כא, לג."],["2770","26","ראה תו\"א ר\"פ תולדות."],["2771","27","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380888\" data-slug=\"likkutei-torah\" data-id=\"4001380888\">לקו\"ת תבוא מב, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380891\" data-slug=\"likkutei-torah\" data-id=\"4001380891\">מג, ג</a>. המשך תער\"ב ח\"א ע' רנז. ועוד."],["2772","28","אוה\"ת בא שם ריש ע' רסא."],["2773","29","ראה אוה\"ת שמע\"צ ע' א'תשפח ואילך. המשך וככה תרל\"ז פרק צז."],["2774","30","תצא כא, יג."],["2775","31","עה\"פ."],["2776","32","כ\"ה באוה\"ת נ\"ך שם ע' א'נ; דברים ח\"ו ע' ב'שמט – עפ\"י <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380868\" data-slug=\"likkutei-torah\" data-id=\"4001380868\">לקו\"ת תצא לז, ד</a>."],["2777","33","איכ\"ר פ\"א, נא. וראה ברכ\"י לשו\"ע או\"ח סתקנ\"ט ס\"ו, וזכור לאברהם ח\"א אות ט (בשם הרח\"ו)."],["2778","34","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381329\" data-slug=\"likkutei-torah\" data-id=\"4001381329\">ראה זח\"ג קנג, ב</a>. לקו\"ת שמע\"צ צב, ב. שה\"ש נ, סע\"ב. ד\"ה והניף וד\"ה ויאמר לו יהונתן תשי\"א (תורת מנחם – התוועדויות ח\"ג ע' 37 ואילך; ע' 50 ואילך)."],["2779","35","איכ\"ר שם."],["2780","36","איכ\"ר פ\"ד, יד. מדרש תהלים עה\"פ תהלים עט, א."],["2781","37","ראה רמ\"א או\"ח סתקנ\"ד סכ\"ב. סתקנ\"ח. סתקנ\"ט ס\"ג. שם ס\"י."],["2782","38","ראה גם ד\"ה לא היו יו\"ט לישראל כט\"ו באב תשמ\"ז סעיף ד (לעיל ע' קעח ואילך)."],["2783","39","תענית ל, סע\"ב."],["2784","40","פתיחתא לאיכ\"ר לג. הובא בפרש\"י ותוס' תענית שם. רשב\"ם (ד\"ה שכלו מתי מדבר) ב\"ב קכא, סע\"א."],["2785","41","לשון רש\"י – חוקת כ, א."],["2786","42","פרשתנו ד, ד."],["2787","43","פרש\"י חוקת שם, כב."],["2788","44","ראה נדרים כב, ב. שמו\"ר רפל\"ב. ובכ\"מ. וראה שעה\"ת (לאדהאמ\"צ) ח\"ב חינוך בתחלתו. אוה\"ת פרשתנו ע' סה. צג. וש\"נ."],["2789","45","ראה שמו\"ר פ\"ב, ד. זח\"א רנג, א. שער הפסוקים להאריז\"ל ויחי מט, י. תו\"א ר\"פ משפטים."],["2790","46","ב\"ר פט\"ז, ד. ויק\"ר פי\"ג, ה. וראה סה\"מ תש\"ט ע' 107."],["2791","47","ראה ד\"ה כימי צאתך מארמ\"צ תש\"ח רפי\"ב (סה\"מ תש\"ח ע' 164)."],["2792","48","לשון המאמר – סד\"ה נחמו הנ\"ל (סה\"מ שם ע' רלא)."],["2793","49","ראה תוד\"ה ה\"ג ונאמר – פסחים קטז, ב."],["2794","50","מיכה ז, טו."],["2795","51","זח\"א קכט, סע\"א ואילך."],["2796","52","תענית ל, ב. ב\"ב קכא, א."],["2797","53","אבות פ\"ה מכ\"א."],["2798","54","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380794\" data-slug=\"likkutei-torah\" data-id=\"4001380794\">לקו\"ת פ' ראה יט, ג</a>. סה\"מ תש\"ח ע' 94 ואילך. ובכ\"מ."],["2799","55","לקוטי תורה להאריז\"ל עקב ח, ג."],["2800","56","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380129\" data-slug=\"likkutei-torah\" data-id=\"4001380129\">לקו\"ת צו יג, ב</a> ואילך. ובכ\"מ."],["2801","57","עקב שם."],["2802","58","סוטה לה, א. ועוד. וראה שערי אורה ד\"ה בכ\"ה בכסלו ספכ\"ב."],["2803","59","פ\"ו."],["2804","60","ראה תו\"כ ר\"פ קדושים. תניא אגה\"ת פ\"י. ועוד. וראה תויו\"ט סוף סוטה."],["2805","61","לקו\"ת יוהכ\"פ ע, ג."],["2806","62","ע\"ז כ, ב. וש\"נ."],["2807","63","ע\"ז י, ב."],["2808","64","ראה זהר ח\"ג קלה, ב. הובא בעץ חיים שער ט (שער שבירת הכלים) פ\"ב. לקו\"ת חוקת נו, ד."],["2809","65","כלשון תפלת מוסף דיו\"ט. וראה המשך וככה תרל\"ז פי\"ז ואילך. ובכ\"מ."],["2810","66","ירמי' כג, כט."],["2811","67","ברכות כב, א."],["2812","68","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פרק לז</a>."],["2813","69","סה\"מ תרצ\"ז ע' 215. ע' 282. וש\"נ."],["2814","70","קידושין מ, ב."],["2815","71","עירובין יג, ב."],["2816","72","ראה בהדרושים שבהערה 5."],["2817","73","יתרו יח, כ. ויקרא ד, ב. ועוד."],["2818","74","פ\"ד ס\"ב-ג."],["2819","75","זח\"א קע, ב."],["2820","76","יבמות סג, א."],["2821","77","בראשית ב, יח. וראה יבמות שם."],["2822","78","ברכות יג, א במשנה."],["2823","79","ראה ספרי עה\"פ עקב יא, יז (הובא בפרש\"י שם, יח). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191040\" data-slug=\"likkutei-sichot\" data-id=\"1300191040\">לקו\"ש חי\"ט ע' 40</a>."],["2824","80","יומא כו, א."],["2825","81","סוטה מד, א. וש\"נ. וראה חולין סו, ב."],["2826","82","עקב שם, טז."],["2827","83","לשון חז\"ל – פסחים סח, ב."],["2828","84","או\"ח סקל\"א סוס\"ח."],["2829","85","נצבים ל, ג."],["2830","86","ראה מגילה כט, א. ספרי ס\"פ מסעי. זח\"א קכ, ב."],["2831","87","פרש\"י עה\"פ. מגילה שם. ועוד."],["2832","88","ישעי' כז, יב."],["2833","89","פרש\"י שם."],["2834","90","בא י, ט."],["2835","91","ישעי' ס, ט."],["2836","92","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370254\" data-slug=\"torah-or\" data-id=\"3901370254\">שמות ג, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370271\" data-slug=\"torah-or\" data-id=\"3901370271\">וראה ברכות ט, ב</a>. תו\"א וארא נו, סע\"ד. בא ס, ג. סד\"ה אם רוח המושל תרצ\"ה (סה\"מ קונטרסים ח\"ב שסג, א)."],["2837","93","זכרי' יג, ב."]]],[1500390043,"<h3>בס\"ד. ש\"פ עקב, כ\"ף מנחם-אב, ה'תשט\"ז<sup data-n=\"2838\">*</sup></h3>\n(הנחה בלתי מוגה)\n<b>והי'</b> עקב תשמעון את המשפטים האלה ושמרתם ועשיתם אותם ושמר ה\"א לך את הברית ואת החסד אשר נשבע גו'<sup data-n=\"2839\">1</sup>. וידוע הדיוק בזה<sup data-n=\"2840\">2</sup>, דהלשון תשמעון פירושו תשמעון ודאי, והיינו לפי שעקב קאי על הזמן דעקבתא דמשיחא, ומאחר שהוא דור היותר אחרון, לכן תשמעון ודאי, לפי שהוא דור היותר אחרון ואי אפשר לחכות יותר, ס'איז ניטאָ אויף ווען צו אָפּלייגן די בירורים, ולכן תשמעון ודאי<sup data-n=\"2841\">3</sup>.\n<b>והנה</b> בתיבת תשמעון יש ג' פירושים. תשמעון מלשון הבנה, כמ\"ש<sup data-n=\"2842\">4</sup> דבר כי שומע עבדך. תשמעון מלשון אסיפה, כמ\"ש<sup data-n=\"2843\">5</sup> וישמע שאול את העם. ותשמעון כפשוטו מלשון שמיעה, דענין השמיעה שייך למחשבה, שהרי האוזן היא רק הכלי שעל ידו שומעים, אבל השמיעה גופא היא במחשבה, וענין השמיעה שייך גם לדיבור, שהרי שומעים מה שמדברים. וזהו מ\"ש תשמעון ושמרתם ועשיתם, דתשמעון הוא מחשבה, וכנ\"ל שהשמיעה היא במחשבה, ושמרתם הוא דיבור, כמאמר<sup data-n=\"2844\">6</sup> שמור זה משנה, והוא הפסק הלכה כפי שבא בדיבור, דכאשר השכל הוא במחשבה, אזי הוא בהעלם עדיין, דישנם פנים להיתר וטהור ויש פנים להיפך<sup data-n=\"2845\">7</sup>, משא\"כ כאשר השכל בא בגילוי בדיבור, אזי ישנו פסק ההלכה. ואז לא תהי' יניקה לחיצונים, דכאשר הוא בהעלם עדיין אפשר להיות יניקה, אבל כאשר בא בגילוי אזי אין להם יניקה. וזהו שמור זה משנה, שהמשנה שענינה גילוי השכל בדיבור היא שמירה שלא יהי' יניקה כו'. ועשיתם הוא מעשה. והיינו שתשמעון ושמרתם ועשיתם הם מחשבה דיבור ומעשה. וההתחלה בזה היא מבחי' מחדומ\"ע שבמחשבה גופא, שזהו ג' הפירושים שבתיבת תשמעון, דשמיעה מלשון הבנה היינו מחשבה שבמחשבה, ושמיעה מלשון אסיפה היינו מעשה שבמחשבה, ושמיעה כפשוטו היינו דיבור שבמחשבה, ששומע מה שמדברים. וזהו והי' עקב תשמעון גו', דכאשר תשמעון בבחי' מחדומ\"ע שבמחשבה, ואח\"כ תשמעון ושמרתם ועשיתם במחדומ\"ע ממש, הנה עי\"ז ושמרה\"א לך את הברית ואת החסד אשר נשבע, דג' ענינים אלו (ברית חסד ושבועה) הם ההמשכה שמלמעלה. דברית הוא מעשה, דענין הכריתת ברית הוא שכורתין דבר שלם לשנים ועוברים ביניהם<sup data-n=\"2846\">8</sup>, שעי\"ז תהי' האהבה ביניהם בתמידות, גם במצב שלא יהי' טעם על האהבה, לא מצד בחי' הדיבור, ואפילו לא מצד בחי' המחשבה, ואעפ\"כ תהי' האהבה מצד הכר\"ב שהו\"ע של מעשה בפועל. וחסד הוא מחשבה, שהרי החסד הוא הרגש הלב והמוח, ולכן הוא בכלל מחשבה. ובפרט שכאן נאמר ושמר את החסד, כמבואר<sup data-n=\"2847\">9</sup> החילוק בין עושה חסד לנוצר חסד, דעושה חסד הוא עשיית החסד, ונוצר חסד הוא ששומר את החסד בלבבו ובמחשבתו. ושבועה הוא דיבור. וזהו והי' עקב גו' דכאשר תהי' העבודה מלמטה למעלה במחשבה דיבור ומעשה, אזי תהי' המשכת המחשבה דיבור ומעשה מלמעלה למטה.\n<b>וצריך</b> להבין טעם שינוי הסדר, שבעבודה מלמטה למעלה נאמרו המחדומ\"ע כסדרם, תחילה מחשבה ואח\"כ דיבור ומעשה, ובהמשכה מלמעלה למטה נאמר תחלה מעשה ואח\"כ מחשבה ודיבור. דלכאורה, מאחר שההמשכה שמלמעלה באה ע\"י עבודת האדם, א\"כ הי' צ\"ל סדר ההמשכה מלמעלה כפי סדר העבודה, ומהו הטעם שבעבודה הסדר הוא שמעשה בא אחרי מחשבה ודיבור, ובההמשכה מלמעלה בא המעשה קודם למחשבה ודיבור.\nב) <b>והענין</b> הוא, דהנה כללות עבודת האדם באה ע\"י ההתבוננות, דנקודת העבודה היא כמאמרז\"ל<sup data-n=\"2848\">10</sup> איזהו עבודה שבלב זו תפלה, וקודם לזה ההתבוננות דק\"ש וברכות ק\"ש וכו', וכתוב<sup data-n=\"2849\">11</sup> שמע ישראל הוי' אלקינו הוי' אחד, הנה הא' דאחד מורה על א\"ס אלופו של עולם, והח' מורה על ז' רקיעים וארץ, והד' מורה על ד' סטרין<sup data-n=\"2850\">12</sup>. והנה, הד' הוא ד' רבתי, והוא בחי' גדלות הדיבור. דדל\"ת הוא בחי' הדיבור, וד' רבתי הוא גדלות הדיבור, והוא בחי' הדיבור כמו שהוא במחשבה. והענין הוא עד\"מ כמו שאנו רואים באדם למטה, שכל פרטי הדיבורים כלולים תחילה במחשבתו, במחשבה אחת, דמחשבה אחת זו היא מקור כל הדיבורים הפרטיים, ולא זו בלבד שהמחשבה היא מקורם, אלא שהמחשבה כוללת בתוכה כל פרטי הדיבורים גם לאחר שנמשכו ממנה. ועד\"ז יובן גם למעלה, שכל פרטי העשרה מאמרות כלולים תחילה בבחי' מחשבה אחת הכוללת אותם<sup data-n=\"2851\">13</sup>, והוא בחי' המאמר דבראשית, כמארז\"ל<sup data-n=\"2852\">14</sup> בראשית נמי מאמר הוא, דמלשון זה מובן ב' הפכים, דמחד גיסא מובן שהמאמר דבראשית הוא בכלל המאמרות, ולאידך גיסא מובן שהוא למעלה מהם, שהרי צריך להודעה דנמי מאמר הוא, לפי שהמאמר דבראשית הוא למעלה משאר המאמרות,והוא בחי' המאמרות כמו שהם כלולים בהמחשבה. וזהו שאמרו<sup data-n=\"2853\">15</sup> והלא במאמר אחד יכול להבראות, דמאמר אחד קאי על המאמר דבראשית שהוא כולל בתוכו כל שאר המאמרות, ולכן הנה ממאמר אחד דבראשית יכול להבראות כל הבריאה. וזהו בחי' ד' רבתי שהו\"ע פרטי המאמרות כמו שהם כלולים בהמחשבה אחת הכוללת אותם, שהוא גדלות הדיבור, שהרי אין זה אמיתית ענין המחשבה, כי אם ענין הדיבור, אלא שהוא הדיבור כמו שהוא כלול עדיין בהמחשבה, שזהו בחי' גדלות הדיבור. וזהו\"ע הוי' אחד, שהוא הביטול כמו שהוא מצד בחי' ד' רבתי, גדלות הדיבור.\n<b>אמנם</b> מי הם המתבוננים והעובדים בביטול הלזה, הנה עז\"נ שמע ישראל, דישראל עלו במחשבה<sup data-n=\"2854\">16</sup>. ופירוש ישראל עלו במחשבה היינו מחשבה עילאה, שלמעלה מבחי' המחשבה כמו שהיא באה בציור מוגבל. והיינו דלא זו בלבד שהוא למעלה במדריגה מבחי' מחשבה שבדיבור ובחי' דיבור שבמחשבה, אלא הוא למעלה גם מבחי' מחשבה שבמחשבה. דהנה, מחשבה שבדיבור הוא מה שחושב איך לדבר, היינו איך לבאר בפרטי אופני הדיבור, ואין זה אמיתית ענין המחשבה, שהרי זה בחי' המחשבה כמו שמתלבשת בענין הדיבור, שחושב איך לדבר. ודיבור שבמחשבה הוא המחשבה עצמה שלמעלה מענין הדיבור, אבל מ\"מ הוא כולל את הדיבור, וכנ\"ל בענין גדלות הדיבור שהוא המחשבה אחת שכוללת את פרטי הדיבור. ואמיתית ענין המחשבה הוא בחי' מחשבה שבמחשבה, והיינו כמו שחושב את עצם השכל טרם שמתלבש בהאותיות, שהוא למעלה במדריגה מבחי' מחשבת השכל לאחר שמתלבש בהאותיות. ומעלת השכל טרם שמתלבש באותיות על בחי' השכל לאחר שמתלבש בהאותיות הוא בב' ענינים. הא', שהשכל שמתלבש בהאותיות הרי הוא מצוייר בפרטי אופני הביאור, שהם האותיות שמתלבש בהם, שהאותיות הם פרטי האופנים דביאור השכל, משא\"כ קודם שמתלבש בהאותיות הרי אינו מצוייר עדיין בפרטי אופני הביאור, ולכן אפשר לבארו בכמה אופנים שונים. והב', שהשכל טרם שמתלבש בהאותיות, הנה לא זו בלבד שאינו מצוייר בפרטי אופני הביאור, אלא עוד זאת, שגם השכל עצמו הוא בפשיטות, שהוא מופשט עדיין מפרטי השכל עצמו (לא רק מאופני הביאור). אמנם בחי' ישראל עלו במחשבה הוא בחי' מחשבה עילאה שלמעלה גם מבחי' מחשבה שבמחשבה, דבחי' מחשבה שבמחשבה הרי הוא בבחי' ציור, דאף שהוא מושלל מהאופנים והפרטים, אבל מ\"מ הוא בציור השכל עכ\"פ, משא\"כ מחשבה עילאה היא בפשיטות לגמרי.\nג) <b>אך</b> לפי זה צריך להבין למה ירדה הנשמה למטה, שזוהי ירידה מאיגרא רמה לבירא עמיקתא<sup data-n=\"2855\">17</sup> ממש, דמאחר ששרש הנשמות הוא במחשבה עילאה, א\"כ לאיזה תועלת ירדה למטה. אך הענין הוא, דירידה זו צורך עלי', והעלי' הוא למעלה גם מבחי' מחשבה עילאה.<b>והענין</b> הוא, דהנה איתא בגמרא<sup data-n=\"2856\">18</sup> כתוב אחד אומר<sup data-n=\"2857\">19</sup> ואספת דגנך, וכתוב אחד אומר<sup data-n=\"2858\">20</sup> ועמדו זרים ורעו צאנכם, כאן בזמן שישראל עושין רצונו של מקום, כאן בזמן שאין עושין רצונו של מקום. וידוע הקושיא בזה, הרי הפסוק ואספת דגנך נאמר בפ' והי' אם שמוע, שבה נאמר<sup data-n=\"2859\">21</sup> והי' אם שמוע תשמעו גו' בכל לבבכם ובכל נפשכם, ואיך אומר על זה שהוא בזמן שאין עושין רצונו של מקום. ותירץ הרב המגיד<sup data-n=\"2860\">22</sup>, דמכיון שהעבודה היא רק בכל לבבכם ובכל נפשכם, אבל חסרה העבודה דבכל מאדך<sup data-n=\"2861\">23</sup>, לכן נקרא אין עושין רצונו של מקום.\n<b>והענין</b> הוא, דהנה פירוש עושין רצונו של מקום הוא שצריך לעשות (מען דאַרף אויפמאַכן) הרצון במקום. דמקום קאי על סדר ההשתלשלות, ואוא\"ס עצמו הוא למעלה מבחי' מקום, כדאיתא במדרש<sup data-n=\"2862\">24</sup> ע\"פ<sup data-n=\"2863\">25</sup> הנה מקום אתי, הוא מקומו של עולם ואין העולם מקומו, ולכן צריך לעשות את הרצון במקום, והיינו, שלא רק הרצון בבחי' מקום הוא התחדשות, אלא ענין הרצון גופא הוא התחדשות, שהרי אוא\"ס לאו מכל אילין מדות איהו כלל<sup data-n=\"2864\">26</sup>, שהוא למעלה מכל הספירות ולמעלה גם מבחי' רצון שבתוכם, ובכדי שיהי' הרצון הרי זה חידוש, וכמ\"ש יהי רצון, דהיינו שיתחדש בחי' הרצון. ובכדי שיהי' בחי' הרצון הרי זה ע\"י קיום התומ\"צ, כמאמר<sup data-n=\"2865\">27</sup> נח\"ר לפני שאמרתי ונעשה רצוני, שע\"י שגורמים נח\"ר לפניו ית' בקיום התומ\"צ, אזי נעשה רצוני, שנתחדש בחי' הרצון. וכל זה הוא חידוש הרצון בכלל, שזה נעשה ע\"י קיום התומ\"צ בכלל. אמנם בכדי לעשות רצונו של מקום, היינו לחדש את הרצון במקום, לא מספיק קיום התומ\"צ בלבד, אלא צריך לזה האהבה דבכל מאדך, דבכדי לעשות את הרצון בכלל, מספיק גם העבודה כמו שהוא מצד בחי' בכל לבבך ובכל נפשך, אך בכדי לחדש את הרצון במקום, צריך לזה העבודה כמו שהוא מצד בכל מאדך דוקא. וזהו דפ' שני' דק\"ש הוא בחי' אין עושין רצונו של מקום, לפי שחסר בזה העבודה דבכל מאדך, וע\"י העבודה דבכל מאדך דוקא עושין רצונו של מקום.\nד) <b>והענין</b> הוא, דהנה ברצון יש ב' מדרגות, רצון התחתון ורצון העליון. וב' בחי' רצון אלו ישנם בנה\"ב, ומזה יובן גם בנה\"א, ועד\"ז יובן גם למעלה. דהנה, רצון התחתון בנה\"ב הוא ע\"ד מה שרוצה במסחר, שרצון זה נולד מהשכל,דכאשר מבין איך שענין המסחר טוב לפניו, אזי רוצה בזה, ומצד הרצון הרי הוא חושב בהמסחר, ומדבר ועושה בזה, ורצון זה הוא רצון התחתון, מאחר שהוא נולד מהשכל. ורצון העליון הוא רצון שלמעלה מהשכל, וכמו מה שרוצה לחיות, שרוצה בקיומו, דרצון זה אינו מצד השכל והטעם. ומבחי' רצון זה שרוצה לחיות, נמצא גם הרצון שרוצה במסחר, והיינו דהרצון שרוצה לחיות מצטייר ע\"י השכל ברצונות פרטיים כפי אופני השכל שהשכיל מה שטוב לפניו, דכל הרצונות פרטיים הוא הרצון שרוצה לחיות כמו שהצטייר ע\"י השכל. והנה, ההפרש בין רצה\"ת לרצה\"ע הוא, דרצה\"ת הוא בהגבלה, דמאחר שנולד מהשכל, הרי הוא בהגבלה כפי הגבלת השכל. וגם רצון זה הוא רק בחיצוניות בהנפש, דלהיותו רק מצד ההתבוננות, הרי הוא מגיע רק באותו מקום בהנפש שהשכל מגיע, משא\"כ רצה\"ע שלמעלה מהשכל הרי הוא בלי גבול, והוא הרצון שמצד פנימיות הנפש. ומזה יובן גם בנה\"א, שיש בו רצה\"ת ורצה\"ע, דרצה\"ת הוא מה שרוצה באלקות מצד ההתבוננות, ורצון העליון הוא בחי' לאהבה את ה\"א כי הוא חייך<sup data-n=\"2866\">28</sup>, שאין זה מצד הטעם, כי אם שזהו חיותו. וכמו (בנה\"ב) הרצון שרוצה לחיות. והוא בחי' רצה\"ע רעוא דכל רעוין<sup data-n=\"2867\">29</sup>.\n<b>ועד\"ז</b> יובן גם למעלה, דרצה\"ת הוא הרצון כמו שבא בהשתלשלות ע\"י החכמה, ורצה\"ע הוא הרצון שלמעלה מהטעם, שממנו נמשכים כל הרצונות (וכנ\"ל בנה\"ב שכל הרצונות נמשכים מהרצון שרוצה לחיות), רעוא דכל רעוין. וזהו ענין עושין רצונו של מקום, דהיינו עשיית הרצון שלמעלה מהשתלשלות, רצון העליון, במקום, בהשתלשלות, דע\"י המשכת הרצון שלמעלה מהשתלשלות בהשתלשלות, אזי תהי' למטה הנהגה דבלי גבול, לפי שגם בהגבול דהשתלשלות מאיר הבל\"ג. ולכן הנה בזמן שעושין רצונו של מקום אזי ועמדו זרים ורעו צאנכם, לפי שגם למטה יהי' הנהגה דבלי גבול. והוא ע\"ד מ\"ש<sup data-n=\"2868\">30</sup> ביום ההוא יהי' הוי' אחד, דעכשיו לא כמו שאני נכתב אני נקרא<sup data-n=\"2869\">31</sup>, היינו דעכשיו הנה הוי' הוא בהעלם, משא\"כ לעתיד הנה הוי' יהי' בגילוי למטה. והמשכה זו היא ע\"י האהבה דבכל מאדך&lt;23&gt;, דבכדי להגיע לבחי' הבל\"ג שלמעלה הרי זה ע\"י העבודה בהבל\"ג שבנפש, דהגם שאין זה אמיתית הבל\"ג, שהרי זה רק מאד שלך<sup data-n=\"2870\">32</sup>, מ\"מ להיות שבאדם עכ\"פ הרי זה בל\"ג, והוא רצה\"ע שבאדם, הנה עי\"ז הוא ממשיך גם את רצה\"ע שלמעלה, שזהו\"ע עושין רצונו של מקום.\nה) <b>וזהו</b> שמע ישראל הוי' אלקינו הוי' אחד, דהוי' אלקינו הוא הוי' שלמעלה מהשתלשלות כחנו וחיותינו, שהוא בחי' הוי' עילאה, והוי' אחד הוא הוי' תתאה, דהוי' הוא צמצום והתפשטות המשכה והתפשטות<sup data-n=\"2871\">33</sup>, שעי\"ז (הוי' תתאה)אפשר להיות אחד, היינו התהוות ז' רקיעים וארץ וד' סטרין. וזהו שמע ישראל הוי' אלקינו הוי' אחד, דשמע ישראל הוא ההתבוננות, הוי' אלקינו, הוי' עילאה כחנו וחיותינו, ועי\"ז הנה הוי' (תתאה) אחד, היינו הביטול. וזהו ענין ירידת הנשמה למטה, לפי שעל ידי ההתבוננות למטה דוקא נעשה בה העבודה דתשובה, שהיא העבודה דבל מאדך, שעי\"ז עושין רצונו של מקום, דהיינו המשכת רצה\"ע, שלמעלה גם מבחי' מחשבה עילאה, שרש הנשמות.\nו) <b>וזהו</b> והי' עקב תשמעון גו' ושמרתם ועשיתם, שהו\"ע העבודה דמחדומ\"ע כמו שהוא מצד האהבה דבכל מאדך, הנה ע\"י עבודה זו, אזי ושמר ה\"א לך את הברית ואת החסד ואת השבועה, דברית חסד ושבועה הם ההמשכות שלמעלה מהשתלשלות, והו\"ע עושין רצונו של מקום. וזהו מ\"ש ושמר את החסד, שהכוונה היא ע\"ד מ\"ש בזהר<sup data-n=\"2872\">34</sup> ע\"פ<sup data-n=\"2873\">35</sup> ואיש כי יקח את אחותו חסד הוא, איש דא קוב\"ה, אשר יקח את אחותו דא כנס\"י (והו\"ע יחוד הקב\"ה וכנס\"י, יחוד קוב\"ה ושכינתי'), וכ\"כ למה חסד הוא חסד הוא ודאי, והיינו שבכדי שתהי' ההמשכה למטה הרי זה ע\"י החסד ממנו ית'. וכמ\"ש<sup data-n=\"2874\">36</sup> זכור רחמיך וחסדיך כי מעולם המה, דענין הזכירה שייך לומר רק על דבר שנופל בו ענין השכחה, והיינו דלהיות שכללות ההשתלשלות אינו תופס מקום לפניו ית', לכן אנו מבקשים זכור רחמיך וחסדיך, דרחמיך הו\"ע יגמה\"ר שלמעלה מהשתלשלות, כמ\"ש<sup data-n=\"2875\">37</sup> ויעבור הוי' על פניו ויקרא הוי', דמ\"ש ויעבור הוי' הוא הוי' עילאה שלמעלה מהשתלשלות, וחסדיך הוא בחי' רב חסד שלמעלה מהשתלשלות, כי מעולם המה, דעולם הוא לשון העלם<sup data-n=\"2876\">38</sup>, והיינו שהם בהעלם בשרשן, כענין ע\"ס הגנוזות, ע\"ס דעקודים, וצריך להמשיך בחי' זו בעולם כפשוטו, היינו שגם למטה תהי' ההמשכה דבלי גבול, ועי\"ז הנה ועמדו זרים ורעו צאנכם. והמשכה זו היא ע\"י האהבה דבכל מאדך דוקא, והיינו שלא מספיק קיום התומ\"צ במחדומ\"ע בלבד, שהרי מחדומ\"ע הם רק לבושים בלבד שבאין ערוך לכחות הנפש, ובמכ\"ש לבחי' הרצון, כידוע דמחשבה ודיבור הם כעין עילה ועלול, שהמחשבה הוא עילה לגבי הדיבור, וכמו\"כ הדיבור לגבי המעשה, משא\"כ המחדומ\"ע לגבי כחות הנפש ובפרט לגבי הרצון הם באי\"ע, ולכן צ\"ל העבודה דבכל מאדך דוקא, שעי\"ז יהי' המשכת רצה\"ע. אמנם בכדי שהאהבה דבכל מאדך תפעל המשכת רצה\"ע דלמעלה, צריך לזה כריתת ברית, דמאחר שאין הנבראים תופסים מקום כלל, איך ימשיכו ע\"י עבודתם, אלא שהוא מצד הכר\"ב שהעבודה דלמטה תמשיך הגילויים מלמעלה. ולכן מקדים הכתוב את הברית לחסד ושבועה, לפי שכללות ההמשכה הוא מצד הברית. וזהו והי' עקב תשמעון גו', דבהזמן דעקבתא דמשיחא תשמעון ודאי, לפי שהוא דור היותר אחרון, ולא ידח ממנו נדח<sup data-n=\"2877\">39</sup>,ולכן תשמעון ודאי, בבחי' בכל מאדך, ועי\"ז ושמר את הברית גו', שתהי' הגאולה מהגלות ביד רמה, ע\"י משיח צדקנו, במהרה בימינו.\n**********",[["2838","*","על רשימת ההנחה שבארכיון ספריית אגודת חסידי חב\"ד – תיקן כ\"ק אדמו\"ר שליט\"א כמה תיקונים בכתי\"ק (<i>המו\"ל</i>)."],["2839","1","ריש פרשתנו."],["2840","2","בכל הבא לקמן – ראה ד\"ה זה מאדמו\"ר הצ\"צ שנדפס בקונטרס בפ\"ע בשנה זו [תשט\"ז] בתוספת איזה מ\"מ והערות מכ\"ק אדמו\"ר שליט\"א, ולאח\"ז באוה\"ת ריש פרשתנו. וראה גם המשכו בד\"ה ושמתי כדכד (לקמן ע' שלב ואילך)."],["2841","3","ראה גם מכתב ח' אלול שנה זו (אגרות-קודש חי\"ג ע' תמד)."],["2842","4","שמואל-א ג, י. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171112\" data-slug=\"likkutei-sichot\" data-id=\"1300171112\">לקו\"ש חי\"ז ע' 112</a>."],["2843","5","שם טו, ד. ועוד."],["2844","6","ראה קדושין לז, א. סה\"מ תש\"ד ע' 133. וש\"נ."],["2845","7","ראה ירושלמי סנהדרין פ\"ד ה\"ב."],["2846","8","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380896\" data-slug=\"likkutei-torah\" data-id=\"4001380896\">לקו\"ת נצבים מד, ב</a>. אוה\"ת פרשתנו שם ס\"ו."],["2847","9","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370309\" data-slug=\"torah-or\" data-id=\"3901370309\">תו\"א יתרו סט, סע\"ב</a> ואילך."],["2848","10","תענית ב, א."],["2849","11","ואתחנן ו, ד."],["2850","12","ראה סמ\"ק הובא בב\"י או\"ח סי' ס\"א. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300141022\" data-slug=\"likkutei-sichot\" data-id=\"1300141022\">לקו\"ש חי\"ד ע' 22</a>."],["2851","13","ראה זח\"ב כ, א."],["2852","14","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380359\" data-slug=\"likkutei-torah\" data-id=\"4001380359\">ר\"ה לב, א</a>. ראה לקו\"ת ר\"פ בחוקותי. שם במדבר יב, ד. ועוד."],["2853","15","אבות ריש פ\"ה."],["2854","16","ב\"ר פ\"א, ד. ועוד."],["2855","17","ע\"פ לשון חז\"ל – חגיגה ה, ב."],["2856","18","ברכות לה, ב."],["2857","19","פרשתנו יא, יד."],["2858","20","ישעי' סא, ה."],["2859","21","פרשתנו שם, יג."],["2860","22","ראה או\"ת להה\"מ פרשתנו ד\"ה מפני מה. וראה גם חדא\"ג מהרש\"א לברכות שם. מאמרי אדמו\"ר הזקן תקס\"ג ח\"ב ע' תרעט. תרפב. תקס\"ט ע' קלה. שערי תשובה ח\"ב נא, א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300121098\" data-slug=\"likkutei-sichot\" data-id=\"1300121098\">לקו\"ש חי\"ב ע' 98</a> ובהנסמן שם."],["2861","23","ואתחנן ו, ה."],["2862","24","ב\"ר פס\"ח, ט. ובכ\"מ."],["2863","25","תשא לג, כא."],["2864","26","תקוני זהר בהקדמה (יז, ב)."],["2865","27","ספרי ופרש\"י פינחס כח, ח."],["2866","28","נצבים ל, כ."],["2867","29","זח\"ב פח, ב."],["2868","30","זכרי' יד, ט."],["2869","31","פסחים נ, א."],["2870","32","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370180\" data-slug=\"torah-or\" data-id=\"3901370180\">תו\"א מקץ לט, ד</a>. ובכ\"מ."],["2871","33","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380042\" data-slug=\"likkutei-torah\" data-id=\"4001380042\">לקו\"ת בשלח א, א</a>. ובכ\"מ."],["2872","34","ח\"ג ז, ב."],["2873","35","קדושים כ, יז."],["2874","36","תהלים כה, ו."],["2875","37","תשא לד, ו."],["2876","38","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380330\" data-slug=\"likkutei-torah\" data-id=\"4001380330\">קה\"ר עה\"פ ג</a>, יא. ראה לקו\"ת במדבר ה, ג."],["2877","39","ע\"פ שמואל-ב יד, יד."]]],[1500390044,"<h3>בס\"ד. ש\"פ ראה, מבה\"ח אלול, ה'תשט\"ז<sup data-n=\"2878\">*</sup></h3>\n(הנחה בלתי מוגה)\n<b>ושמתי</b> כדכד שמשתיך<sup data-n=\"2879\">1</sup>, ואמרז\"ל<sup data-n=\"2880\">2</sup> חד אמר שהם וחד אמר ישפה אמר הקב\"ה להוי כדין וכדין. הנה פסוק זה הוא אחד היעודים שיהיו בהגאולה העתידה לבוא ע\"י משיח צדקנו במהרה בימינו. ויש בזה ב' אופנים, שהם וישפה, ואמר הקב\"ה להוי כדין וכדין. ולהבין ב' אופנים אלו ברוחניות, היינו בהגילוי אלקות שיהי' לע\"ל, יובן זה מזה שב' אבנים אלו היו מי\"ב האבנים טובות אשר בהחושן של כה\"ג, למספר שבטי בנ\"י, שהם כנגד יוסף וישפה כנגד בנימין. והנה, יוסף ובנימין הם צדיק עליון וצדיק תחתון, דבחי' יוסף הוא המשכת אלקות מלמעלה למטה, יוסף הוא המשביר בר<sup data-n=\"2881\">3</sup>, שממשיך אלקות מלמעלמ\"ט, והיינו דגם כאשר העולם לא נזדכך עדיין עד כדי כך שיוכל לקבל בתוכו גילוי אור נעלה, מ\"מ נמשך אור בדרך מלמעלמ\"ט. ובחי' בנימין הוא זיכוך ועלי' מלמטלמ\"ע, היינו שפועל בירור זיכוך עלי' והתקשרות בנש\"י וחלקם בעולם, ובמילא גם בכללות הבריאה, שיוכלו לקבל את האור. וע\"ד משל כמו שמוח הבע\"ח אינו כלי לשכל ומוח האדם הוא כלי לשכל, לפי שהוא מזוכך יותר, הנה עבודתו של בנימין הוא העלאה מלמטלמ\"ע שפועל זיכוך במוח ושכל האדם עד שיהי' כלי לאור אלקי נעלה. והנה, בב' אופנים אלו יש בכל אחד מהם מעלה מיוחדת. המעלה בעבודתו של בנימין, שהו\"ע ישפה, שהמטה מתייחד יותר עם האור אלקי, דלהיות אשר ההמשכה היא מצד הזיכוך שנעשה כלי להאור, במילא הרי הוא ביחוד גמור עם האור. והמעלה בעבודתו של יוסף, שהו\"ע שהם, שנמשך אור נעלה ביותר שאינו כפי אופן התחתון כי אם כפי שהוא מצד העליון. ועל זה אמר הקב\"ה להוי כדין וכדין, אשר לע\"ל יהיו ב' המעלות. וכמבואר כל הנ\"ל באריכות בלקו\"ת בהדרושים ושמתי כדכד<sup data-n=\"2882\">4</sup>. והנה, ידוע שכל הגילוים שיהיו לעתיד תלויים במעשינו ועבודתינו כל זמן משך הגלות<sup data-n=\"2883\">5</sup>, ומאחר שלעתיד יהיו האופנים דמלמעלמ\"ט ומלמטלמ\"ע, בהכרח לומר שגם בהעבודה בזמן משך הגלות ישנם ג\"כ אופנים אלו. וצריך להבין מהו\"ע ב' אופנים אלו דשהם וישפה בעבודה.\n<b>ולהבין</b> זה צריך להקדים תחלה משנת\"ל<sup data-n=\"2884\">6</sup> דוהי' עקב קאי על הזמן דעקבתא דמשיחא, דאז הנה תשמעון ודאי, לפי שהוא דור האחרון, ולא ידח ממנונדח, ולזאת הנה בדור זה תשמעון ודאי. וכללות העבודה הוא תשמעון ושמרתם ועשיתם, שהוא מחשבה דבור ומעשה, וכאשר המחדומ\"ע שלו יהיו מחדומ\"ע של נה\"א לבדו, והוא מחדומ\"ע דתומ\"צ, אזי הנה ושמר ה\"א לך את הברית ואת החסד ואת השבועה, שיומשך המחדומ\"ע שמלמעלה אליו. דבכללות הוא שע\"י עבודתו נעשה יחוד העובד עם הנעבד, יחוד נש\"י עם הקב\"ה, יחוד פב\"פ, וע\"י האהבה דבכל מאדך<sup data-n=\"2885\">7</sup> ממשיך הגילויים שלמעלה מהשתלשלות. אמנם זה שע\"י עבודתו ממשיך הגילוי שמלמעלה, הוא רק מצד הכריתת ברית בלבד, שהרי לאו מכל אלין מדות איהו כלל, ובכדי שמעשה הנבראים יהי' תופס מקום, הוא רק מצד הברית.\nב) <b>והנה</b> ענין הברית הוא התורה, כמ\"ש<sup data-n=\"2886\">8</sup> את הברית אשר כרת עמנו בחורב<sup data-n=\"2887\">9</sup>, ובילקוט<sup data-n=\"2888\">10</sup> ע\"פ<sup data-n=\"2889\">11</sup> אלה דברי הברית איתא<sup data-n=\"2890\">12</sup> אין ברית אלא תורה, והיינו שהתורה הוא הברית המאחד נש\"י עם הקב\"ה, וכמ\"ש<sup data-n=\"2891\">13</sup> אנכי עומד בין הוי' וביניכם, דאנכי מי שאנכי, דלא אתרמיז לא בשום אות ולא בשום קוץ<sup data-n=\"2892\">14</sup>, דבכללות הוא הכתר, הנה הוא מחבר ישראל וקוב\"ה ע\"י התורה. וביאור הענין הוא, ע\"פ הידוע שבכל ממוצע המחבר שני דברים יש ב' בחי', בחי' א' השייכת להעליון, ובחי' ב' השייכת להתחתון, וע\"י ב' הבחי' שבו נעשה ממוצע המחבר. וכמו\"כ יובן גם בהתורה שהיא ממוצע המחבר נש\"י וקוב\"ה, שיש בהתורה בחי' השייכת לנבראים, ובחי' השייכת להקב\"ה, ועי\"ז היא מחברת נש\"י וקוב\"ה. דהנה, התורה נתלבשה בדברים גשמיים כו', ומצד זה היא שייכת לנבראים, ובכללות הו\"ע גליא דתורה. ויש בחי' בהתורה כמו שהיא בענינים רוחניים, והוא בחי' סתים דתורה שמדברת בעניני אלקות, שלכן הוא סתים (לגבינו), שהרי התורה היא חכמתו ורצונו של הקב\"ה. וע\"י ב' בחי' אלו התורה היא ממוצע המחבר אוא\"ס ב\"ה ונש\"י.\n<b>וביאור</b> ב' בחי' אלו בהתורה בעומק יותר, הנה ידוע דמה שאורייתא מחכמה נפקת<sup data-n=\"2893\">15</sup> אין הכוונה על חכמה תתאה וחכמה עילאה בלבד, כי אם על חכמה סתימאה, דח\"ס הוא הממוצע האמיתי. דהנה, כללות הכתר הוא ממוצע בין אוא\"ס המאציל והנאצלים, והוא ע\"י ב' הבחי' שבהכתר, בחי' תחתונה שבמאציל, ובחי' ראשונה שבאצילות, דע\"י ב' בחי' אלו (בחי' תחתונה שבמאציל ושרש ומקור הנאצלים) נעשה הכתר ממוצע לחבר אוא\"ס המאציל עם האצילות. אמנם ב' בחי' אלו כמו שהם בכתר, הרי הם ב' מדריגות מיוחדות, ואין זה אמיתית ענין הממוצע,והממוצע האמיתי הוא בחי' חכמה סתימאה, לפי שבח\"ס הנה ב' בחי' אלו (השייכות להמאציל והשייכות לאצי') אינם ב' מדריגות מיוחדות, אלא הם כאחד, ולכן הוא הממוצע האמיתי. ויובן זה עד\"מ כמו שאנו רואים למטה בנפש האדם, דבכח החכמה יש ב' ענינים הפכיים, כח ההפשטה וההפלאה, וכח הירידה וההלבשה. ענין ההפלאה שבחכמה הוא מה שבכחו להפשיט את השכל מהציורים החומרים וגם מהציורים הגשמיים ואפילו מהציורים הרוחניים, והיינו שמפשיט את השכל מכל הציורים שבו, אורך רוחב ועומק, ונשאר רק הנקודה, שזוהי בחי' הנקודה שבחכמה. וענין הירידה וההלבשה דחכמה הוא שבכח החכמה להוריד את המושכל עד למטה מטה, כמו וידבר שלשת אלפים משל<sup data-n=\"2894\">16</sup> ולמטה יותר. והנה, ב' ענינים אלו שבחכמה אינם ב' ענינים נבדלים זה מזה, אלא הוא ענין אחד. דכח הירידה הוא מצד כח ההפלאה, דמה שבכחו להוריד את המושכל עד למטה מטה הוא לפי שתופס את עצם נקודת השכל המופשט מכל ציור, ומשום זה דוקא ביכלתו להוריד את השכל עד למטה מטה. ועד\"ז יובן למעלה בבחי' ח\"ס, דב' הבחי' שבח\"ס, הבחי' השייכת להמאציל והבחי' השייכת להאצילות, אינם ב' ענינים נבדלים זמ\"ז, אלא הו\"ע אחד, ולכן הנה ח\"ס הוא הממוצע האמיתי. וכמו\"כ יובן בתורה, דב' הענינים שבתורה, מה שהיא חכמתו של הקב\"ה, ומה שנתלבשה בדברים גשמיים, אינם ב' בחי' נבדלים זמ\"ז, גליא דתורה וסתים דתורה, כי אם שאורייתא מחכמה (סתימאה) נפקת, ומצד בחי' העליונה שבתורה הנה משום זה דוקא ירדה למטה ונתלבשה בדברים גשמיים. ולכן נקראת התורה ברית, שהוא הממוצע האמיתי בין נש\"י ואוא\"ס ב\"ה.\n<b>והנה</b> כמו\"כ המצוות נקראים ברית, לפי שבהמצוות יש ג\"כ ב' בחי', שהרי הם עצמן נעשים מדברים גשמיים, ובהם הוא המשכת רצון העליון, דרצון הוא למעלה מחכמה. וב' בחי' אלו בהמצוות אינם ב' ענינים נבדלים, אלא הו\"ע אחד, שהרי המצוות המתלבשים בדברים גשמיים, הן הן עצמם הוא רצון העליון, שכך עלה ברצונו לקיים המצוות בגשמיות דוקא. ולפי שהוא רצה\"ע שלמעלה גם מהחכמה, לכן הוא יורד למטה בדברים גשמיים דוקא. אמנם זה גופא שע\"י תומ\"צ יהי' אפשר להיות היחוד דנש\"י עם אוא\"ס, דלכאורה, כיון שאוא\"ס לאו מכל אלין מדות איהו כלל, איך יהי' תופס מקום מעשה התחתונים שיהי' יחוד פב\"פ, דמאחר שלאו מכל אלין מדות איהו כלל, אי אפשר שיהי' יחוד פב\"פ, הן מצד אוא\"ס והן מצד נש\"י, הנה עז\"נ אנכי עומד בין הוי' וביניכם להגיד לכם את דבר הוי', דאנכי מי שאנכי הוא בחי' הכתר שלמעלה משניהם, ובכח הכתר נעשה היחוד ע\"י התורה.\nג) <b>וזהו</b> והי' עקב תשמעון את המשפטים האלה, דהנה, התרגום דמשפט הוא הלכתא<sup data-n=\"2895\">17</sup>, שהו\"ע הלכות התורה, והיינו דכיון שבפסוק זה מבאר היחוד דנש\"י עם הקב\"ה כנ\"ל, לכן נאמר את המשפטים האלה, שהיחוד הוא ע\"י הלכות התורה. ותשמעון היינו לשון אסיפה, כמו וישמע שאול כו'&lt;6&gt;, והענין הוא לקבץולאסוף כל פזורי ניצוצי נפשו האלקית שנתקשרה ברצונות זרות, ע\"י ריבוי המחשבות ופיזור הנפש, דהגם דכתיב<sup data-n=\"2896\">18</sup> וברכך הוי' אלקיך בכל אשר תעשה דוקא, שצריך להיות העשי' בגשמיות, מ\"מ, המחשבה אינה צריכה להיות שקועה בזה, וכמ\"ש<sup data-n=\"2897\">19</sup> יגיע כפיך כי תאכל, שצריך להיות יגיע כפים בלבד, אבל לא יגיעת המוח והלב, ולכן צריך לקבץ את הניצוצות שנתפזרו בפיזור הנפש, וכמ\"ש<sup data-n=\"2898\">20</sup> אם יהי' נדחך בקצה השמים משם יקבצך. וכשם שצריך לאסוף פזורי ניצוצי נפשו, כך צריך להיות האסיפה גם בהלכות התורה, דמצד הפיזור שנעשה בנפשו, נעשה אצלו העלם והסתר גם בהתורה, שאינו יכול לברר ולפסוק הלכה לאמיתתה, ועז\"נ תשמעון את המשפטים, אלו ההלכות, דתשמעון הוא אסיפה, שצריך להיות האסיפה בנפשו והאסיפה בהלכות התורה. וזהו ג\"כ מ\"ש<sup data-n=\"2899\">21</sup> ואספת דגנך ותירושך ויצהרך, דנש\"י נקראים בשם דגנך ותירושך ויצהרך, והם ג' חלוקי דרגות בנש\"י, כהנים לויים וישראלים. דגנך אלו ישראלים, דכמו שבגשמיות הרי הלחם הוא העיקר, דלחם לבב אנוש יסעד<sup data-n=\"2900\">22</sup>, ושאר המאכלים הם רק תוספות על הלחם, כמו\"כ גם בנש\"י העיקר הוא ישראלים, דגם כהנים ולויים הם ישראלים, אלא שיש בהם תוספת מעלה דכהנים ולויים, ולכן ישראלים נקראים דגנך. תירושך אלו לויים, דעבודת הלויים הוא באמירת שירה, ואין אומרים שירה אלא על היין<sup data-n=\"2901\">23</sup>. ויצהרך אלו כהנים, שעבודתם היא בבחי' שמן, בחשאי וברעותא דלבא<sup data-n=\"2902\">24</sup>. וזהו ואספת דגנך ותירושך ויצהרך, שהו\"ע אסיפת פזורי הניצוצים בכל הג' סוגים שבנש\"י. גם פירוש ואספת דגנך תירושך ויצהרך הו\"ע האסיפה שצריך להיות בהתורה, דהתורה נקראת ג\"כ בשם דגנך תירושך ויצהרך, והם חילוקי המדריגות שיש בתורה. דגנך הוא גליא דתורה, תירושך הוא פנימיות התורה, רזין דאורייתא, ויצהרך הוא רזין דרזין, וכמו שמן שצף ע\"ג היין<sup data-n=\"2903\">25</sup>, כמבואר באמרי בינה<sup data-n=\"2904\">26</sup> באריכות. וזהו ואספת דגנך גו', שהו\"ע האסיפה שצריך להיות בכל חלקי התורה. וזהו והי' עקב תשמעון את המשפטים האלה, שכאשר יהי' האסיפה דפזורי ניצוצי נפשו והאסיפה בהתורה, ובכללות הוא העבודה דתשמעון ושמרתם ועשיתם שהם מחדומ\"ע, עי\"ז יומשך גם המחדומ\"ע מלמעלמ\"ט, שיהי' יחוד פב\"פ דנש\"י ואוא\"ס ב\"ה.\nד) <b>אמנם</b> כל זה הוא בעבודה דמחדומ\"ע כמו שהיא מצד רצון התחתון הנולד מהשכל. אמנם בהעבודה כמו שהיא מצד רצון העליון, דהיינו העבודה דרעו\"ד שלמעלה מטעם ודעת, דבכללות הוא האהבה דבכל מאדך שנאמרה בפ'ראשונה דק\"ש, הנה בפ' זו לא נזכר הפסוק ואספת דגנך תירושך ויצהרך (שנעשה מצד הענין דאם יהי' נדחך גו') כמו בפ' שני' דק\"ש, לפי שמצד האהבה דבכל מאדך, שהו\"ע עושין רצונו של מקום, כנ\"ל<sup data-n=\"2905\">27</sup> בשם המגיד שהו\"ע המשכת רצה\"ע שלמעלה מהשתלשלות, הנה מצד המשכת בחי' זו אין צריך להיות העבודה דואספת, כי אם כמ\"ש<sup data-n=\"2906\">28</sup> וברך גו' דגנך תירושך ויצהרך, שלא יהי' בהם בחי' פיזור הנפש ברצונות זרות כו', שענין זה שייך בהשתלשלות דוקא, אבל מצד האהבה דבכל מאדך שממשיכים הרצון שלמעלה מהשתלשלות, אין שייך ענין זה. וזהו אמיתית ענין הברית דתורה, דתורה ענינה המשכה מלמעלה למטה, היינו המשכת האור עליון כמו שהוא (שלא לפי ערך הנבראים), והוא האור שלמעלה מהשתלשלות, דתפלה היא העלאה מלמטה למעלה, ואספת דגנך גו', אבל התורה היא המשכה מלמעלה למטה, המשכת האור שלמעלה מהשתלשלות, והוא ע\"י הקדמת העבודה דרעו\"ד, בחי' בכל מאדך, שאז נמשך ע\"י התורה האור שלמעלה מהשתלשלות, וזהו אמיתית ענין הברית דתורה, שהתורה הוא המחבר ומייחד נש\"י בהבחי' שלמעלה מהשתלשלות.\nה) <b>ושרש</b> ההפרש בין ב' בחי' אלו, הנה ידוע שבענין כר\"ב ישנם ב' אופנים. אופן א' הוא כמו שכרת אברהם אבינו עם אבימלך ע\"י שבע כבשות<sup data-n=\"2907\">29</sup>, ששניהם נשתתפו בהכבשות, שלכל אחד מהם הי' חלק בזה, ועי\"ז הם מתייחדים. ואופן הב' הוא, שלוקחים דבר א' שלם וחותכים לשנים והכורתים את הברית עוברים בין הבתרים<sup data-n=\"2908\">30</sup>. והנה, כאשר חותכים דבר א' לשנים הרי זה לכאורה היפך השלימות ופירוד כו', אך באמת הנה זהו אמיתית היחוד, היינו שכל אחד לעצמו הוא רק חצי דבר, ואינו שום מציאות מבלעדי השני. ועד\"ז יובן גם למעלה, שבחי' הברית דתורה בהעבודה דואספת דגנך גו', הנה אף שנעשה עי\"ז המשכת האור, מ\"מ הרי הוא מציאות לעצמו. אמנם התורה שאחרי הקדמת העבודה דרעו\"ד ותשובה, דתשובה הוא ג\"כ ברית, כמ\"ש<sup data-n=\"2909\">31</sup> לעברך בברית ה\"א, הרי זה באופן נעלה יותר, שאינו שום מציאות לעצמו כו', ועי\"ז הוא המשכת האור שלמעלה מהשתלשלות. ובזה יובן ג\"כ בענין הכר\"ב דר\"ה, כמ\"ש<sup data-n=\"2910\">32</sup> אתם נצבים היום גו' לעברך בברית, דלכאורה אינו מובן, הרי גם בכל השנה יש כר\"ב דאוא\"ס ונש\"י, ומהו\"ע הכר\"ב דר\"ה. אך הענין הוא, שהכר\"ב דכל השנה היא ע\"ד הכר\"ב דשבע כבשות, אמנם בר\"ה הוא העבודה דתשובה, שאינו שום מציאות לעצמו כו', והוא היחוד באוא\"ס עצמו בעל הרצון.\nו) <b>ובזה</b> יובן ג\"כ מה שפירש\"י ע\"פ והי' עקב תשמעון, אם המצוות קלות שהאדם דש בעקביו תשמעון. וענין זה הוא כמ\"ש בזהר<sup data-n=\"2911\">33</sup> ע\"פ<sup data-n=\"2912\">34</sup> למה אירא בימירע עון עקבי יסובני, שהו\"ע העבירות קלות שהאדם דש בעקביו. דהנה, ביעקב כתיב<sup data-n=\"2913\">35</sup> וידו אוחזת בעקב עשו, דיעקב פירושו יו\"ד עקב<sup data-n=\"2914\">36</sup>, שהוא מאיר בכל המדריגות עד בחי' העקביים, והו\"ע הזהירות בכל הענינים, גם בקלות שבקלות, שזהו יו\"ד עקב. ושרש ההמשכה דיעקב יו\"ד עקב, שתהי' בו הזהירות גם בקלות שבקלות, הוא כמ\"ש<sup data-n=\"2915\">37</sup> הקל קול יעקב, קלא קדמאה חסר וקלא בתראה מלא, קלא בתראה מלא הוא התורה, וקלא קדמאה חסר הוא קלא דלא אשתמע, והו\"ע העבודה דרעו\"ד. וכאשר הקל קול, קלא קדמאה וקלא בתראה, והוא התורה שאחרי העבודה דרעו\"ד, אזי ישנו הענין דיעקב, יו\"ד עקב, שהו\"ע הזהירות גם בקלות שבקלות. והיינו שכאשר עבודתו היא ע\"פ טעם ודעת, אזי יש חילוק בין קלות שבקלות וחמורות שבחמורות, אבל כאשר יש בו ההמשכה דתורה אחרי הקדמת העבודה דרעו\"ד שלמעלה מטו\"ד, אזי אין חילוק כלל בין קלות וחמורות, וזהו הקל קול יעקב, וכאשר הקל קול יעקב אזי אין הידים ידי עשו שולטות<sup data-n=\"2916\">38</sup>. וז\"ש למה אירא בימי רע עון עקבי יסובני, לפי שחסר בחי' יעקב יו\"ד עקב, וידו אוחזת כו'. וזהו מה שפירש\"י ע\"פ והי' עקב תשמעון, אם המצוות קלות שהאדם דש בעקביו, לפי שפסוק זה מבאר ענין ההמשכה שלמעלה מהשתלשלות, שהוא ע\"י התורה שאחרי הקדמת העבודה דרעו\"ד, ולכן פירש\"י שצ\"ל הזהירות גם במצוות קלות, שזהו הוראה שעבודתו היא למעלה מטו\"ד שלכן נזהר בקלות כמו בחמורות. וכיון שעבודתו היא למעלה מטו\"ד, אזי ושמר ה\"א לך את הברית ואת החסד ואת השבועה, שיומשך האור שלמעלה מהשתלשלות.\nז) <b>והנה</b><sup data-n=\"2917\">39</sup> ב' אופנים אלו בעבודה, העבודה דהקל קול, תפלה ותורה, הוא העבודה שבדרך מלמטלמ\"ע ובדרך מלמעלמ\"ט, וכמבואר בארוכה בכ\"מ. ולהיות דבקדושה הוא התכללות והתאחדות, הרי גם בעבודת התפלה עצמה<sup data-n=\"2918\">40</sup> ישנם ב' אופנים אלו, עבודת הלילה ועבודת היום. וי\"ל שעד\"ז הוא ג\"כ החילוק דהעבודה דבכל לבבך ובכל נפשך והעבודה דבכל מאדך&lt;7&gt;, וגם בהעבודה דבכל מאדך ישנם ב' אופנים אלו, דבכל מאדך יש בחי' רצון ובחי' תענוג. וכן בתורה עצמה<sup data-n=\"2919\">41</sup> ישנם ב' האופנים, והם תושב\"כ ותושבע\"פ, כמבואר במ\"א. וע\"י ב' אופנים אלו בעבודתינו בזמן משך הגלות, יהיו לע\"ל ב' האופנים דשהם וישפה. כי עכשיו בזמן הגלות הוא בהעלם, דבין העלי' שנעשה בהעולם ובין המשכת האור שבעולם הוא בהעלם, ולע\"ל יתגלה זה שפעלו בהעבודה בזמן הגלות, ושמתי כדכד שהם וישפה, ולהוי כדין וכדין.\n**********",[["2878","*","התחלת וסיום המאמר הוגהו ע\"י כ\"ק אדמו\"ר שליט\"א. גוף המאמר הוא המשך להמאמר ד\"ה והי' עקב תשמעון דש\"פ עקב (לעיל ע' שכה ואילך)."],["2879","1","ישעי' נד, יב."],["2880","2","ב\"ב עה, א."],["2881","3","ע\"פ מקץ מב, ו."],["2882","4","פרשתנו כד, ד ואילך. כו, ג ואילך."],["2883","5","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא ריש פל\"ז</a>."],["2884","6","רד\"ה והי' עקב (לעיל שם). וש\"נ."],["2885","7","ואתחנן ו, ה."],["2886","8","שם ה, ב."],["2887","9","עד כאן הוגה ע\"י כ\"ק אדמו\"ר שליט\"א."],["2888","10","פ' בא רמז קצה."],["2889","11","תבוא כח, סט."],["2890","12","בכל הבא לקמן – ראה ד\"ה והי' עקב תשמעון מאדמו\"ר הצ\"צ פ\"ו ואילך שנדפס בקונטרס בפ\"ע בשנה זו [תשט\"ז], ולאח\"ז באוה\"ת עקב ע' תפו ואילך."],["2891","13","ואתחנן ה, ה."],["2892","14","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380641\" data-slug=\"likkutei-torah\" data-id=\"4001380641\">ראה זהר ח\"א קסז, ב</a>. ח\"ג יא, א. לקו\"ת פינחס פ, ב. שם פרשתנו לא, ד."],["2893","15","זח\"ב פה, א. ועוד."],["2894","16","מלכים-א ה, יב."],["2895","17","וישב מ, יג."],["2896","18","פרשתנו טו, יח."],["2897","19","תהלים קכח, ב."],["2898","20","נצבים ל, ד."],["2899","21","עקב יא, יד. וראה אוה\"ת שם ס\"ז. וש\"נ."],["2900","22","תהלים קד, טו."],["2901","23","ברכות לה, א."],["2902","24","ראה זח\"ג לט, א. קעז, ב."],["2903","25","ראה טבול יום פ\"ב מ\"ה. שבת ה, ב."],["2904","26","שער הק\"ש פנ\"ג ואילך [וראה בהנסמן בסוף האמ\"ב שם – הוצאת קה\"ת תשמ\"ה – קמח, ד]."],["2905","27","ד\"ה והי' עקב פ\"ג (לעיל ס\"ע שכז ואילך)."],["2906","28","עקב ז, יג."],["2907","29","וירא כא, כז ואילך."],["2908","30","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380896\" data-slug=\"likkutei-torah\" data-id=\"4001380896\">לקו\"ת נצבים מד, ב</a>. אוה\"ת שם ס\"ו."],["2909","31","נצבים כט, יא."],["2910","32","שם, ט."],["2911","33","ח\"א קצח, א ואילך."],["2912","34","תהלים מט, ו."],["2913","35","תולדות כה, כו."],["2914","36","פרדס שער כג (שער ערכי הכינויים) בערכו. עץ חיים שער ג (שער סדר האצילות). פ\"ב."],["2915","37","תולדות כז, כב. וראה זח\"א נ, ב. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480126\" data-slug=\"or-hatorah-hb\" data-id=\"8316480126\">אוה\"ת תולדות רסד, א</a>. שם כרך ה תתצד, ב."],["2916","38","ב\"ר פס\"ה, כ."],["2917","39","מכאן עד סוף המאמר הוגה ע\"י כ\"ק אדמו\"ר שליט\"א."],["2918","40","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380830\" data-slug=\"likkutei-torah\" data-id=\"4001380830\">לקו\"ת דברים כח, ג</a> (הערה בקונטרס הנ\"ל שבהערה 12)."],["2919","41","ראה לקו\"ת שם יב, ג. צה, ד. – ע\"פ המבואר בפנים י\"ל, כפשטות לשון הש\"ס (ב\"ב עה, א), דחד אמר שהם וח\"א ישפה קאי על הכתוב ושמתי כדכד. ראה שם בפירש\"י ותוס' ועוד (הערה בקונטרס הנ\"ל הערה 12)."]]]]});
